def install_coverage_cross_root_contract(image_base):
    global COVERAGE_EXPECTED_CROSS_ROOT_HOOKS
    global COVERAGE_EXPECTED_FUNCTION_HOOKS
    global COVERAGE_EXPECTED_CROSS_ROOT_OWNERS
    global COVERAGE_EXPECTED_CROSS_ROOT_TARGETS
    global COVERAGE_CROSS_ROOT_PAIRS_SHA256
    global COVERAGE_CROSS_ROOT_OWNERS_SHA256
    global COVERAGE_CROSS_ROOT_TARGETS_SHA256
    try:
        contract = COVERAGE_CROSS_ROOT_CONTRACTS_BY_IMAGE_BASE[image_base]
    except KeyError as ex:
        raise RuntimeError(
            "unsupported coverage cross-root image base 0x%08x" % image_base
        ) from ex
    COVERAGE_EXPECTED_CROSS_ROOT_HOOKS = contract["hooks"]
    COVERAGE_EXPECTED_FUNCTION_HOOKS = contract["function_hooks"]
    COVERAGE_EXPECTED_CROSS_ROOT_OWNERS = contract["owners"]
    COVERAGE_EXPECTED_CROSS_ROOT_TARGETS = contract["targets"]
    COVERAGE_CROSS_ROOT_PAIRS_SHA256 = contract["pairs_sha256"]
    COVERAGE_CROSS_ROOT_OWNERS_SHA256 = contract["owners_sha256"]
    COVERAGE_CROSS_ROOT_TARGETS_SHA256 = contract["targets_sha256"]


install_coverage_cross_root_contract(DEFAULT_BASE)

