# The PE has exactly two direct `_setjmp3(env, 0)` calls.  A host setjmp made
# inside an ordinary import wrapper would save the wrapper's frame and leave a
# dead longjmp destination as soon as that wrapper returned.  These calls are
# therefore lowered in the generated owner body itself.  Pin both physical
# instructions and every recursive-descent body which contains a copy: this is
# deliberately not a target-wide `_setjmp3` substitution.
SETJMP_THUNK_RVA = 0x005EC352
SETJMP_THUNK_MACHINE = bytes.fromhex("ff256c646030")
SETJMP_IAT_RVA = 0x0060646C
SETJMP_IMPORT_NAME = "VCRUNTIME140.dll!_setjmp3"
SETJMP_CALL_SPECS = {
    0x005A0F52: {
        "continuation": 0x005A0F57,
        "machine": bytes.fromhex("e8fbb30400"),
        "members": frozenset((0x005A0E10,)),
    },
    0x005B1094: {
        "continuation": 0x005B1099,
        "machine": bytes.fromhex("e8b9b20300"),
        "members": frozenset((0x005B1040,)),
    },
}
# All native exits from a body with a live automatic jmp_buf must unregister
# through one cleanup label.  Counts include fault exits and generic indirect
# switch fallbacks, not merely translated x86 RET instructions.
SETJMP_BODY_RETURN_COUNTS = {
    0x005A0E10: 38,
    0x005B1040: 25,
}
# At a non-default image base the generator stops at the exact proved local
# jump-table range instead of emitting accidental instructions from its
# relocated pointer bytes.  Ten apparent `return;` statements belonged to
# that data, not to executable control flow.
SETJMP_REBASED_BODY_RETURN_COUNTS = {
    0x005B1040: 15,
}

# libepoxy's generated provider selector is the single boundary shared by all
