def read_manual_rvas(path, expected, label):
    """Read one public/manual split from its C interface X-macro list."""
    with open(path, encoding="utf-8") as source:
        values = tuple(int(match.group(1), 16) for line in source
                       for match in [re.match(
                           r"\s*X\(([0-9a-fA-F]{8}),\s*0x[0-9a-fA-F]+u,",
                           line)] if match)
    if len(values) != expected or len(set(values)) != len(values):
        raise RuntimeError(
            "%s list must contain %d unique RVAs" % (label, expected))
    return frozenset(values)


MANUAL_KAGE_RVAS = read_manual_rvas(
    MANUAL_KAGE_HEADER, 9, "manual KAGE")
MANUAL_PORTABLE_RVAS = read_manual_rvas(
    MANUAL_PORTABLE_HEADER, 4, "manual portable")
MANUAL_RVAS = MANUAL_KAGE_RVAS | MANUAL_PORTABLE_RVAS
if len(MANUAL_RVAS) != 13:
    raise RuntimeError("manual runtime boundary lists overlap")

