_C_SOURCE_NOISE = re.compile(
    r'/\*.*?\*/|//[^\r\n]*|"(?:\\.|[^"\\])*"|\'(?:\\.|[^\'\\])*\'',
    re.DOTALL,
)
_MANUAL_DECLARATION_PREFIX = re.compile(
    r"\s*(?:(?:uint(?:8|16|32|64)_t|int)\s+"
    r"[A-Za-z_][A-Za-z0-9_]*"
    r"(?:\s*,\s*[A-Za-z_][A-Za-z0-9_]*)*\s*;\s*)*\Z"
)


def _mask_c_comments_and_literals(source):
    """Preserve C offsets/braces while hiding comments and literals."""
    return _C_SOURCE_NOISE.sub(
        lambda match: "".join(
            "\n" if char == "\n" else " " for char in match.group(0)),
        source,
    )


def _manual_wrapper_body(masked_source, rva, label):
    signature = re.compile(
        r"\bvoid\s+sub_%08x\s*\(\s*CPU\s*\*__restrict\s+c\s*\)\s*\{"
        % rva)
    matches = list(signature.finditer(masked_source))
    if len(matches) != 1:
        raise RuntimeError(
            "%s coverage wrapper %08x definition count changed: %d"
            % (label, rva, len(matches)))
    open_brace = matches[0].end() - 1
    depth = 0
    for position in range(open_brace, len(masked_source)):
        char = masked_source[position]
        if char == "{":
            depth += 1
        elif char == "}":
            depth -= 1
            if depth == 0:
                return (open_brace + 1, position,
                        masked_source[open_brace + 1:position])
    raise RuntimeError("%s wrapper %08x has no closing brace" % (label, rva))


def validate_manual_coverage_hooks():
    """Measure all thirteen public hooks and prove first-statement ordering.

    A declaration without an initializer may precede the hook; any load,
    assignment, call, branch or initialized declaration may fault or mutate
    state and therefore invalidates semantic entry coverage.
    """
    sources = {
        "manual KAGE": MANUAL_KAGE_SOURCE,
        "manual portable": MANUAL_PORTABLE_SOURCE,
    }
    masked = {}
    for label, path in sources.items():
        with open(path, encoding="utf-8") as stream:
            raw = stream.read()
        if raw.count('#include "guest_coverage_generated.h"') != 1:
            raise RuntimeError(
                "%s must include guest_coverage_generated.h exactly once"
                % label)
        masked[label] = _mask_c_comments_and_literals(raw)

    hook_positions = set()
    for macro, rva, _expected_id in COVERAGE_MANUAL_SPECS:
        label = ("manual KAGE" if rva in MANUAL_KAGE_RVAS
                 else "manual portable")
        source = masked[label]
        body_start, _body_end, body = _manual_wrapper_body(
            source, rva, label)
        hook = re.compile(
            r"\bguest_coverage_function\s*\(\s*%s\s*\)\s*;"
            % re.escape(macro))
        matches = list(hook.finditer(body))
        if len(matches) != 1:
            raise RuntimeError(
                "%s wrapper %08x matching coverage-hook count changed: %d"
                % (label, rva, len(matches)))
        if _MANUAL_DECLARATION_PREFIX.fullmatch(
                body[:matches[0].start()]) is None:
            raise RuntimeError(
                "%s wrapper %08x coverage hook is not first executable "
                "statement" % (label, rva))
        hook_positions.add((label, body_start + matches[0].start()))

    all_positions = set()
    call = re.compile(r"\bguest_coverage_function\s*\(")
    for label, source in masked.items():
        all_positions.update((label, match.start())
                             for match in call.finditer(source))
    if all_positions != hook_positions:
        raise RuntimeError(
            "manual coverage-hook call universe changed: %d expected / %d "
            "found" % (len(hook_positions), len(all_positions)))
    if len(hook_positions) != COVERAGE_EXPECTED_MANUAL_FUNCTION_HOOKS:
        raise RuntimeError("manual coverage-hook census changed")
    return len(hook_positions)



_JCC_STATEMENT = re.compile(r"if \((.*)\) goto L_([0-9a-f]{8});\Z", re.S)


def jcc_statement_condition(statements, target):
    """COND of a rendered `if (COND) goto L_<target>;`, else None.

    A paired consumer renders the comparison directly, an unpaired one the
    cc_* switch; both are one statement of this exact shape.  Seams must not
    pin one of the two spellings: which one the emitter picks depends on the
    pairing pass, not on the guest code.
    """
    if len(statements) != 1:
        return None
    match = _JCC_STATEMENT.match(statements[0])
    if match is None or int(match.group(2), 16) != target:
        return None
    return match.group(1)


def jcc_statement_matches(statements, target):
    return jcc_statement_condition(statements, target) is not None


def function_symbols(rva):
    """Return the public dispatch symbol and emitted implementation symbol."""
    public = "sub_%08x" % rva
    emitted = ("guest_original_%08x" % rva
               if rva in MANUAL_RVAS else public)
    return public, emitted


def render_guest_funcs_header(names, manual_originals):
    """Render the stable common prototype header.

    Public dispatch symbols remain common to every generated TU.  Exact
    implementations behind manual boundaries are private to manual_*.h; only
    the twelve declarations already present in the established corpus remain
    here so this dependency firewall itself causes no full rebuild.
    """
    preserved = [
        (rva, name) for rva, name in manual_originals
        if rva in LEGACY_GUEST_FUNCS_MANUAL_ORIGINAL_RVAS
    ]
    if (len(preserved) != 12 or
            frozenset(rva for rva, _name in preserved) !=
            LEGACY_GUEST_FUNCS_MANUAL_ORIGINAL_RVAS):
        raise RuntimeError(
            "legacy guest_funcs manual-original declarations changed")

    lines = [
        "/* GENERATED -- one declaration per guest function. */\n",
        "#ifndef GUEST_FUNCS_H\n#define GUEST_FUNCS_H\n",
        "#include \"guest.h\"\n\n",
    ]
    lines.extend("void %s(CPU *__restrict c);\n" % name
                 for _rva, name in names)
    lines.append(
        "\n/* Exact originals behind manual runtime boundaries. */\n")
    lines.extend("void %s(CPU *__restrict c);\n" % name
                 for _rva, name in preserved)
    lines.append("\n#endif\n")
    return "".join(lines)


def kage_gl_provider_resolver_for_body(img, root_rva, order,
                                       extra_entries):
    """Pin the exact translated original behind the manual Vita resolver.

    The frozen ABI is ECX=canonical ASCII name, EDX=zero-terminated provider
    array, and one caller-owned entrypoint-offset-array argument at [ESP+4].
    The original and the manual replacement both return with a plain RET, so
    only the return word is consumed here and the wrapper's argument remains
    for its caller.  This validator deliberately emits no source seam.
    """
    if root_rva != KAGE_GL_PROVIDER_RESOLVER_RVA:
        return False

    start = KAGE_GL_PROVIDER_RESOLVER_RVA
    end = KAGE_GL_PROVIDER_RESOLVER_END_RVA
    body = img.code_at(start, end - start)
    decoded = tuple(T.CS.disasm(body, start))
    table_rva = end
    table = img.code_at(
        table_rva, 4 * KAGE_GL_PROVIDER_RESOLVER_SWITCH_ENTRIES)
    switch_targets = tuple(img.rva_of(int.from_bytes(
        table[offset:offset + 4], "little"))
        for offset in range(0, len(table), 4))
    relocations = tuple(sorted(
        rva for rva in img.reloc_rvas if start <= rva < end))
    direct_xrefs = []
    for site in range(img.text_rva, img.text_end - 4):
        if img.mem[site] != 0xE8:
            continue
        displacement = int.from_bytes(
            img.code_at(site + 1, 4), "little", signed=True)
        if ((site + 5 + displacement) & 0xFFFFFFFF) == start:
            direct_xrefs.append(site)

    def ordered_rva_sha256(values):
        return hashlib.sha256(b"".join(
            value.to_bytes(4, "little") for value in values)).hexdigest()

    if (hashlib.sha256(body).hexdigest() !=
            KAGE_GL_PROVIDER_RESOLVER_BODY_SHA256 or
            body[:len(KAGE_GL_PROVIDER_RESOLVER_ENTRY_MACHINE)] !=
            KAGE_GL_PROVIDER_RESOLVER_ENTRY_MACHINE or
            img.code_at(KAGE_GL_PROVIDER_RESOLVER_SWITCH_SITE_RVA,
                        len(KAGE_GL_PROVIDER_RESOLVER_SWITCH_MACHINE)) !=
            KAGE_GL_PROVIDER_RESOLVER_SWITCH_MACHINE or
            hashlib.sha256(table).hexdigest() !=
            KAGE_GL_PROVIDER_RESOLVER_SWITCH_TABLE_SHA256 or
            len(set(switch_targets)) !=
            KAGE_GL_PROVIDER_RESOLVER_SWITCH_ENTRIES or
            ordered_rva_sha256(switch_targets) !=
            KAGE_GL_PROVIDER_RESOLVER_SWITCH_TARGETS_SHA256 or
            any(table_rva + offset not in img.reloc_rvas
                for offset in range(0, len(table), 4)) or
            len(decoded) != KAGE_GL_PROVIDER_RESOLVER_INSTRUCTIONS or
            sum(ins.size for ins in decoded) != len(body) or
            decoded[-1].address != end - 1 or
            decoded[-1].mnemonic != "ret" or decoded[-1].op_str or
            len(order) != KAGE_GL_PROVIDER_RESOLVER_INSTRUCTIONS or
            order[0] != start or order[-1] != end - 1 or
            len(extra_entries) != KAGE_GL_PROVIDER_RESOLVER_SWITCH_ENTRIES or
            frozenset(extra_entries) != frozenset(switch_targets) or
            len(relocations) != KAGE_GL_PROVIDER_RESOLVER_RELOCATIONS or
            ordered_rva_sha256(relocations) !=
            KAGE_GL_PROVIDER_RESOLVER_RELOCATIONS_SHA256 or
            len(direct_xrefs) != KAGE_GL_PROVIDER_RESOLVER_DIRECT_XREFS or
            direct_xrefs[0] != 0x00574054 or
            direct_xrefs[-1] != 0x00594AE2 or
            ordered_rva_sha256(direct_xrefs) !=
            KAGE_GL_PROVIDER_RESOLVER_DIRECT_XREFS_SHA256):
        raise RuntimeError("KAGE GL provider resolver body/ABI census changed")
    return True


def kage_pc_handoff_for_body(img, root_rva, em, order):
    """Return the exact caller-side KAGE handoff statement for this body.

    A false result from the runtime helper falls through to the original
    translated bytes.  The helper is true only after an explicitly enabled PC
    backend has become ready; it neither writes the guest's GLFW-init flag nor
    fabricates the absent GLFW object.
    """
    members = frozenset(order)
    if KAGE_PC_HANDOFF_SITE_RVA not in members:
        return None
    if root_rva not in KAGE_PC_HANDOFF_ROOTS:
        raise RuntimeError(
            "unexpected KAGE handoff body membership at root %08x" % root_rva)
    if (img.code_at(KAGE_PC_HANDOFF_CALL_RVA,
                    len(KAGE_PC_HANDOFF_MACHINE)) !=
            KAGE_PC_HANDOFF_MACHINE):
        raise RuntimeError("KAGE caller handoff machine window changed")
    if (img.code_at(KAGE_PC_HANDOFF_TARGET_RVA,
                    len(KAGE_PC_HANDOFF_TARGET_MACHINE)) !=
            KAGE_PC_HANDOFF_TARGET_MACHINE):
        raise RuntimeError("KAGE caller handoff destination changed")
    required = {
        KAGE_PC_HANDOFF_CALL_RVA, 0x005BFA12, 0x005BFA14,
        KAGE_PC_HANDOFF_SITE_RVA, KAGE_PC_HANDOFF_TARGET_RVA,
    }
    if not required.issubset(members):
        raise RuntimeError(
            "KAGE caller handoff body is missing pinned instructions")
    if KAGE_PC_HANDOFF_SITE_RVA in em.labels:
        raise RuntimeError("KAGE caller handoff site acquired an alternate entry")
    if KAGE_PC_HANDOFF_TARGET_RVA not in em.labels:
        raise RuntimeError("KAGE caller handoff destination is not a local label")
    return ("if (guest_kage_pc_handoff_ready()) "
            "goto L_%08x;" % KAGE_PC_HANDOFF_TARGET_RVA)


def kage_pc_present_seams_for_body(img, root_rva, em, order):
    """Validate the exact PC platform-present leaves in this body.

    Every seam is reached only after the original render-target-null test.
    Enabled PC mode replaces the platform leaf, then rejoins at the precise
    successful SwapBuffers continuation.  Disabled mode emits no side effect
    and falls through to the original bytes.
    """
    members = frozenset(order)
    expected = tuple(
        spec for spec in KAGE_PC_PRESENT_SEAMS
        if spec["root"] == root_rva
    )
    observed = tuple(
        spec for spec in KAGE_PC_PRESENT_SEAMS
        if spec["site"] in members
    )
    if not expected and not observed:
        return ()
    if tuple(spec["site"] for spec in observed) != \
            tuple(spec["site"] for spec in expected):
        raise RuntimeError(
            "unexpected KAGE present seam membership at root %08x" %
            root_rva)

    body_spec = next(
        (spec for spec in KAGE_PC_PRESENT_ROOT_BODIES
         if spec["root"] == root_rva), None)
    if body_spec is None:
        raise RuntimeError(
            "KAGE present body identity is missing at root %08x" % root_rva)
    body = img.code_at(root_rva, body_spec["end"] - root_rva)
    if (len(order) not in body_spec["insn_counts"] or
            hashlib.sha256(body).hexdigest() != body_spec["body_sha256"]):
        raise RuntimeError(
            "KAGE present body/CFG identity changed at root %08x" % root_rva)

    rendered = []
    for spec in expected:
        start = spec["window_start"]
        end = spec["window_end"]
        site = spec["site"]
        target = spec["target"]
        window = img.code_at(start, end - start)
        decoded = tuple(T.CS.disasm(window, start))
        decoded_sites = frozenset(ins.address for ins in decoded)
        if (hashlib.sha256(window).hexdigest() != spec["window_sha256"] or
                not decoded or decoded[-1].address + decoded[-1].size != end or
                not decoded_sites.issubset(members) or
                img.code_at(site, len(KAGE_PC_PRESENT_SITE_MACHINE)) !=
                KAGE_PC_PRESENT_SITE_MACHINE or
                img.code_at(target, len(spec["target_machine"])) !=
                spec["target_machine"]):
            raise RuntimeError(
                "KAGE present machine window changed at %08x" % site)
        if site in em.labels:
            raise RuntimeError(
                "KAGE present site acquired an alternate entry at %08x" % site)
        if target not in members:
            raise RuntimeError(
                "KAGE present continuation left local CFG at %08x" % target)
        rendered.append((site, target))
    return tuple(rendered)


def kage_pc_input_bypass_for_body(img, root_rva, em, order):
    """Pin the exact PC-keyboard / Vita-XInput split in this body."""
    members = frozenset(order)
    if KAGE_PC_INPUT_BYPASS_SITE_RVA not in members:
        return None
    if root_rva != KAGE_PC_INPUT_BYPASS_ROOT:
        raise RuntimeError(
            "unexpected KAGE input bypass membership at root %08x" % root_rva)
    if (img.code_at(KAGE_PC_INPUT_BYPASS_MACHINE_RVA,
                    len(KAGE_PC_INPUT_BYPASS_MACHINE)) !=
            KAGE_PC_INPUT_BYPASS_MACHINE):
        raise RuntimeError("KAGE input bypass machine window changed")
    if (img.code_at(KAGE_PC_INPUT_BYPASS_TARGET_RVA,
                    len(KAGE_PC_INPUT_BYPASS_TARGET_MACHINE)) !=
            KAGE_PC_INPUT_BYPASS_TARGET_MACHINE):
        raise RuntimeError("KAGE input bypass destination changed")
    if (img.code_at(KAGE_VITA_XINPUT_AFTER_RESOLVE_MACHINE_RVA,
                    len(KAGE_VITA_XINPUT_AFTER_RESOLVE_MACHINE)) !=
            KAGE_VITA_XINPUT_AFTER_RESOLVE_MACHINE):
        raise RuntimeError("KAGE Vita XInput resolver/DInput seam changed")
    if (img.code_at(KAGE_VITA_XINPUT_READY_MACHINE_RVA,
                    len(KAGE_VITA_XINPUT_READY_MACHINE)) !=
            KAGE_VITA_XINPUT_READY_MACHINE):
        raise RuntimeError("KAGE Vita XInput detect/notification seam changed")
    if (img.code_at(KAGE_VITA_XINPUT_DETECT_WORKER_SEAM_RVA,
                    len(KAGE_VITA_XINPUT_DETECT_WORKER_MACHINE)) !=
            KAGE_VITA_XINPUT_DETECT_WORKER_MACHINE):
        raise RuntimeError("KAGE Vita XInput detector-worker seam changed")
    if (KAGE_VITA_XINPUT_DETECT_WORKER_CALLBACK_RELOC_RVA not in
            img.reloc_rvas or
            int.from_bytes(img.code_at(
                KAGE_VITA_XINPUT_DETECT_WORKER_CALLBACK_RELOC_RVA, 4),
                "little") != img.va(KAGE_VITA_XINPUT_DETECT_WORKER_CALLBACK_RVA)):
        raise RuntimeError("KAGE Vita XInput detector-worker callback changed")
    required = {
        KAGE_PC_INPUT_BYPASS_MACHINE_RVA,
        KAGE_PC_INPUT_BYPASS_SITE_RVA,
        KAGE_PC_INPUT_BYPASS_TARGET_RVA,
        KAGE_VITA_XINPUT_AFTER_RESOLVE_MACHINE_RVA,
        KAGE_VITA_XINPUT_SKIP_DINPUT_SITE_RVA,
        KAGE_VITA_XINPUT_DETECT_RVA,
        KAGE_VITA_XINPUT_READY_MACHINE_RVA,
        KAGE_VITA_XINPUT_SKIP_NOTIFICATION_SITE_RVA,
        KAGE_VITA_XINPUT_READY_TARGET_RVA,
        KAGE_VITA_XINPUT_DETECT_WORKER_SEAM_RVA,
        KAGE_VITA_XINPUT_DETECT_WORKER_CALL_RVA,
        KAGE_VITA_XINPUT_DETECT_WORKER_CONTINUATION_RVA,
    }
    if not required.issubset(members):
        raise RuntimeError("KAGE platform input body is missing pinned instructions")
    if KAGE_PC_INPUT_BYPASS_SITE_RVA in em.labels:
        raise RuntimeError("KAGE input bypass site acquired an alternate entry")
    if KAGE_VITA_XINPUT_SKIP_DINPUT_SITE_RVA not in em.labels:
        raise RuntimeError("KAGE Vita XInput resolver continuation lost its entry")
    return True


def kage_pc_clipboard_seam_for_body(img, root_rva, em, order):
    """Select one exact no-GLFW PC clipboard entry seam."""
    members = frozenset(order)
    expected = next(
        (spec for spec in KAGE_PC_CLIPBOARD_SEAMS
         if spec["root"] == root_rva), None)
    observed = tuple(
        spec for spec in KAGE_PC_CLIPBOARD_SEAMS
        if spec["root"] in members or spec["call"] in members
    )
    if expected is None and not observed:
        return None
    if expected is None or observed != (expected,):
        raise RuntimeError(
            "unexpected KAGE clipboard body membership at root %08x" %
            root_rva)

    body = img.code_at(expected["root"],
                       expected["end"] - expected["root"])
    window = img.code_at(expected["root"],
                         expected["window_end"] - expected["root"])
    required = {
        expected["root"], expected["window_push"], expected["call"],
        expected["last"],
    }
    if (len(order) != expected["insns"] or
            not order or order[0] != expected["root"] or
            max(order) != expected["last"] or
            hashlib.sha256(body).hexdigest() !=
            expected["body_sha256"] or
            hashlib.sha256(window).hexdigest() !=
            expected["window_sha256"] or
            expected["window_end"] != expected["call"] +
            len(KAGE_PC_CLIPBOARD_CALL_MACHINE) or
            img.code_at(expected["window_push"],
                        len(KAGE_PC_CLIPBOARD_WINDOW_PUSH_MACHINE)) !=
            KAGE_PC_CLIPBOARD_WINDOW_PUSH_MACHINE or
            img.code_at(expected["call"],
                        len(KAGE_PC_CLIPBOARD_CALL_MACHINE)) !=
            KAGE_PC_CLIPBOARD_CALL_MACHINE or
            not required.issubset(members)):
        raise RuntimeError(
            "KAGE PC clipboard %s body/machine identity changed" %
            expected["kind"])
    if expected["call"] in em.labels:
        raise RuntimeError(
            "KAGE PC clipboard call acquired an alternate entry at %08x" %
            expected["call"])
    return expected


def kage_pc_console_command_trace_for_body(img, root_rva, em, order):
    """Pin the exact Console::RunCommand entry used as an automation ACK."""
    members = frozenset(order)
    if root_rva != KAGE_PC_CONSOLE_COMMAND_ROOT:
        if KAGE_PC_CONSOLE_COMMAND_ROOT in members:
            raise RuntimeError(
                "Console::RunCommand entry appeared in another body")
        return False
    body = img.code_at(
        KAGE_PC_CONSOLE_COMMAND_ROOT,
        KAGE_PC_CONSOLE_COMMAND_END - KAGE_PC_CONSOLE_COMMAND_ROOT)
    required = {
        KAGE_PC_CONSOLE_COMMAND_ROOT,
        KAGE_PC_CONSOLE_COMMAND_LAST,
    }
    if (len(order) != KAGE_PC_CONSOLE_COMMAND_INSNS or
            not order or order[0] != KAGE_PC_CONSOLE_COMMAND_ROOT or
            max(order) != KAGE_PC_CONSOLE_COMMAND_LAST or
            hashlib.sha256(body).hexdigest() !=
            KAGE_PC_CONSOLE_COMMAND_SHA256 or
            img.code_at(KAGE_PC_CONSOLE_COMMAND_ROOT,
                        len(KAGE_PC_CONSOLE_COMMAND_ENTRY_MACHINE)) !=
            KAGE_PC_CONSOLE_COMMAND_ENTRY_MACHINE or
            not required.issubset(members) or
            KAGE_PC_CONSOLE_COMMAND_ROOT in em.labels):
        raise RuntimeError(
            "Console::RunCommand body/entry identity changed")
    return True


def kage_pc_keyboard_snapshot_for_body(img, root_rva, em, order):
    """Validate and select the exact host-keyboard producer boundary.

    The native backend owns only a host array.  This generated function is the
    sole layer that copies it into guest memory, before any original poll
    instruction mutates the current/previous arrays.  The embedded original
    GLFW callback stays out of the callable dispatch table.
    """
    if root_rva == KAGE_PC_KEYBOARD_CALLBACK_RVA:
        raise RuntimeError(
            "original GLFW keyboard callback became a dispatch root")
    if root_rva != KAGE_PC_KEYBOARD_POLL_ROOT:
        return False

    members = frozenset(order)
    poll = img.code_at(
        KAGE_PC_KEYBOARD_POLL_ROOT,
        KAGE_PC_KEYBOARD_POLL_END - KAGE_PC_KEYBOARD_POLL_ROOT)
    callback = img.code_at(
        KAGE_PC_KEYBOARD_CALLBACK_RVA,
        KAGE_PC_KEYBOARD_CALLBACK_END - KAGE_PC_KEYBOARD_CALLBACK_RVA)
    vtable = img.code_at(
        KAGE_PC_KEYBOARD_VTABLE_RVA,
        KAGE_PC_KEYBOARD_VTABLE_END - KAGE_PC_KEYBOARD_VTABLE_RVA)
    init_window = img.code_at(
        KAGE_PC_KEYBOARD_INIT_START,
        KAGE_PC_KEYBOARD_INIT_END - KAGE_PC_KEYBOARD_INIT_START)
    copy_window = img.code_at(
        KAGE_PC_KEYBOARD_COPY_START,
        KAGE_PC_KEYBOARD_COPY_END - KAGE_PC_KEYBOARD_COPY_START)

    if (len(order) != KAGE_PC_KEYBOARD_POLL_INSNS or
            not order or order[0] != KAGE_PC_KEYBOARD_POLL_ROOT or
            max(order) != KAGE_PC_KEYBOARD_POLL_END - 1 or
            hashlib.sha256(poll).hexdigest() !=
            KAGE_PC_KEYBOARD_POLL_SHA256):
        raise RuntimeError("PC keyboard poll body/CFG identity changed")
    if (KAGE_PC_KEYBOARD_CALLBACK_RVA in members or
            KAGE_PC_KEYBOARD_CALLBACK_RVA in em.labels or
            hashlib.sha256(callback).hexdigest() !=
            KAGE_PC_KEYBOARD_CALLBACK_SHA256):
        raise RuntimeError("PC keyboard callback identity/reachability changed")
    if (img.code_at(KAGE_PC_KEYBOARD_CALLBACK_SET_RVA,
                    len(KAGE_PC_KEYBOARD_CALLBACK_SET_MACHINE)) !=
            KAGE_PC_KEYBOARD_CALLBACK_SET_MACHINE):
        raise RuntimeError("PC keyboard callback registration changed")
    if (KAGE_PC_KEYBOARD_VTABLE_SLOT !=
            KAGE_PC_KEYBOARD_VTABLE_RVA +
            KAGE_PC_KEYBOARD_VTABLE_SLOT_OFFSET or
            hashlib.sha256(vtable).hexdigest() !=
            KAGE_PC_KEYBOARD_VTABLE_SHA256 or
            int.from_bytes(img.code_at(KAGE_PC_KEYBOARD_VTABLE_SLOT, 4),
                           "little") != img.va(KAGE_PC_KEYBOARD_POLL_ROOT)):
        raise RuntimeError("PC keyboard vtable identity changed")
    if (hashlib.sha256(init_window).hexdigest() !=
            KAGE_PC_KEYBOARD_INIT_SHA256 or
            hashlib.sha256(copy_window).hexdigest() !=
            KAGE_PC_KEYBOARD_COPY_SHA256):
        raise RuntimeError("PC keyboard buffer initialization/copies changed")
    required = {
        KAGE_PC_KEYBOARD_POLL_ROOT,
        KAGE_PC_KEYBOARD_COPY_START,
        0x005A0248, 0x005A0267, 0x005A0268, 0x005A0282, 0x005A028C,
        KAGE_PC_KEYBOARD_POLL_END - 1,
    }
    if not required.issubset(members):
        raise RuntimeError("PC keyboard poll is missing pinned copy instructions")
    return True


def theoraplayer_pc_worker_bypass_for_body(img, root_rva, em, order):
    """Return the exact PC no-video-worker edge for this physical body."""
    members = frozenset(order)
    if THEORAPLAYER_PC_WORKER_BYPASS_SITE_RVA not in members:
        return None
    if root_rva != THEORAPLAYER_PC_WORKER_BYPASS_ROOT:
        raise RuntimeError(
            "unexpected Theoraplayer worker bypass membership at root %08x"
            % root_rva)
    if (img.code_at(THEORAPLAYER_PC_WORKER_BYPASS_MACHINE_RVA,
                    len(THEORAPLAYER_PC_WORKER_BYPASS_MACHINE)) !=
            THEORAPLAYER_PC_WORKER_BYPASS_MACHINE):
        raise RuntimeError("Theoraplayer worker bypass machine window changed")
    if (img.code_at(THEORAPLAYER_PC_WORKER_BYPASS_TARGET_RVA,
                    len(THEORAPLAYER_PC_WORKER_BYPASS_TARGET_MACHINE)) !=
            THEORAPLAYER_PC_WORKER_BYPASS_TARGET_MACHINE):
        raise RuntimeError("Theoraplayer worker bypass destination changed")
    required = {
        THEORAPLAYER_PC_WORKER_BYPASS_MACHINE_RVA,
        THEORAPLAYER_PC_WORKER_BYPASS_SITE_RVA,
        THEORAPLAYER_PC_WORKER_BYPASS_TARGET_RVA,
    }
    if not required.issubset(members):
        raise RuntimeError(
            "Theoraplayer worker bypass body is missing pinned instructions")
    if THEORAPLAYER_PC_WORKER_BYPASS_SITE_RVA in em.labels:
        raise RuntimeError(
            "Theoraplayer worker bypass site acquired an alternate entry")
    if THEORAPLAYER_PC_WORKER_BYPASS_TARGET_RVA not in em.labels:
        raise RuntimeError(
            "Theoraplayer worker bypass destination is not a local label")
    return ("if (guest_kage_pc_handoff_ready()) "
            "goto L_%08x;" % THEORAPLAYER_PC_WORKER_BYPASS_TARGET_RVA)


def intro_pc_native_skip_for_body(img, root_rva, em, order):
    """Validate the untouched Intro setup and its native action-skip seam."""
    members = frozenset(order)
    has_setup = INTRO_PC_SETUP_SITE_RVA in members
    has_skip = INTRO_PC_NATIVE_SKIP_SITE_RVA in members
    if not has_setup and not has_skip:
        return None
    if has_setup and has_skip:
        raise RuntimeError("Intro setup and skip sites unexpectedly overlap")

    if has_setup:
        if root_rva != INTRO_PC_SETUP_ROOT:
            raise RuntimeError(
                "unexpected Intro setup membership at root %08x" % root_rva)
        if (img.code_at(INTRO_PC_SETUP_MACHINE_RVA,
                        len(INTRO_PC_SETUP_MACHINE)) !=
                INTRO_PC_SETUP_MACHINE):
            raise RuntimeError("Intro setup machine window changed")
        required = {
            INTRO_PC_SETUP_MACHINE_RVA,
            INTRO_PC_SETUP_SITE_RVA,
            INTRO_PC_SETUP_CONTINUATION_RVA,
            0x0050C226,
        }
        if not required.issubset(members):
            raise RuntimeError(
                "Intro setup body is missing pinned instructions")
        return "setup"

    if root_rva != INTRO_PC_NATIVE_SKIP_ROOT:
        raise RuntimeError(
            "unexpected Intro native-skip membership at root %08x" % root_rva)
    if (img.code_at(INTRO_PC_NATIVE_SKIP_MACHINE_RVA,
                    len(INTRO_PC_NATIVE_SKIP_MACHINE)) !=
            INTRO_PC_NATIVE_SKIP_MACHINE):
        raise RuntimeError("Intro native-skip machine window changed")
    root_bytes = img.code_at(
        INTRO_PC_NATIVE_SKIP_ROOT,
        INTRO_PC_NATIVE_SKIP_ROOT_END - INTRO_PC_NATIVE_SKIP_ROOT)
    if hashlib.sha256(root_bytes).hexdigest() != \
            INTRO_PC_NATIVE_SKIP_ROOT_SHA256:
        raise RuntimeError("Intro native-skip owner bytes changed")
    required = {
        INTRO_PC_NATIVE_SKIP_MACHINE_RVA,
        0x004B78F1,
        0x004B78F3,
        INTRO_PC_NATIVE_SKIP_CALL_RVA,
        INTRO_PC_NATIVE_SKIP_SITE_RVA,
        0x004B78FD,
        0x004B790B,
        0x004B7910,
        0x004B7912,
        INTRO_PC_NATIVE_SKIP_TARGET_RVA,
        0x004B7932,
        0x004B7A03,
        0x004B7A13,
        0x004B7A46,
    }
    if not required.issubset(members):
        raise RuntimeError(
            "Intro native-skip body is missing pinned instructions")
    if INTRO_PC_NATIVE_SKIP_SITE_RVA in em.labels:
        raise RuntimeError("Intro native-skip site acquired an alternate entry")
    if INTRO_PC_NATIVE_SKIP_TARGET_RVA not in em.labels:
        raise RuntimeError("Intro native-skip target is not a local label")
    if len(order) != 126:
        raise RuntimeError(
            "Intro native-skip owner instruction count changed: %d" % len(order))
    return "native_skip"


def vita_rooted_file_probe_for_body(img, root_rva, em, order):
    """Authenticate the Vita data-root edge into Resource::Open stdio.

    The frozen helper has 51 direct callers, so the replacement stays inside
    its one owner and recognizes only the title data root.  The downstream
    fopen import still owns path normalization and rejects traversal/siblings.
    """
    members = frozenset(order)
    site = VITA_ROOTED_FILE_PROBE_SITE_RVA
    target = VITA_ROOTED_FILE_PROBE_DIRECT_RVA
    if site not in members:
        return False
    if root_rva != VITA_ROOTED_FILE_PROBE_ROOT_RVA:
        raise RuntimeError(
            "unexpected Vita rooted-file probe membership at root %08x" %
            root_rva)

    owner = img.code_at(
        VITA_ROOTED_FILE_PROBE_ROOT_RVA,
        VITA_ROOTED_FILE_PROBE_END_RVA -
        VITA_ROOTED_FILE_PROBE_ROOT_RVA,
    )
    ordered = hashlib.sha256(b"".join(
        address.to_bytes(4, "little") for address in order)).hexdigest()
    direct_xrefs = []
    for address in range(img.text_rva, img.text_end - 4):
        if img.mem[address] != 0xE8:
            continue
        displacement = int.from_bytes(
            img.code_at(address + 1, 4), "little", signed=True)
        if ((address + 5 + displacement) & 0xFFFFFFFF) == \
                VITA_ROOTED_FILE_PROBE_ROOT_RVA:
            direct_xrefs.append(address)
    xrefs_hash = hashlib.sha256(b"".join(
        address.to_bytes(4, "little")
        for address in direct_xrefs)).hexdigest()

    if (len(order) != VITA_ROOTED_FILE_PROBE_INSTRUCTIONS or
            order[0] != VITA_ROOTED_FILE_PROBE_ROOT_RVA or
            order[-1] != 0x005631F9 or
            hashlib.sha256(owner).hexdigest() !=
            VITA_ROOTED_FILE_PROBE_BODY_SHA256 or
            ordered != VITA_ROOTED_FILE_PROBE_ORDER_SHA256 or
            img.code_at(
                VITA_ROOTED_FILE_PROBE_MACHINE_RVA,
                len(VITA_ROOTED_FILE_PROBE_MACHINE)) !=
            VITA_ROOTED_FILE_PROBE_MACHINE or
            img.code_at(
                target,
                len(VITA_ROOTED_FILE_PROBE_DIRECT_MACHINE)) !=
            VITA_ROOTED_FILE_PROBE_DIRECT_MACHINE or
            len(direct_xrefs) != VITA_ROOTED_FILE_PROBE_DIRECT_XREFS or
            xrefs_hash != VITA_ROOTED_FILE_PROBE_XREFS_SHA256):
        raise RuntimeError("Vita rooted-file probe body/caller census changed")
    if site in em.labels:
        raise RuntimeError(
            "Vita rooted-file probe site acquired an alternate entry")
    if target not in em.labels:
        raise RuntimeError(
            "Vita rooted-file direct-stdio target is not a local label")
    return True


def render_vita_rooted_file_probe():
    """Route only approved Vita title-root spellings to frozen stdio."""
    return (
        "#if defined(__vita__)",
        "    /* Vita title-root paths are absolute, despite not being X:/ paths. */",
        "    {",
        "        static const char _vita_root_tail[] = \"data/isaacr001\";",
        "        uint32_t _vita_root_offset = 4U;",
        "        uint32_t _vita_root_index = 0U;",
        "        if (c->edx > _vita_root_offset &&",
        "                ld8((uint32_t)(c->esi + 0U)) == (uint8_t)'u' &&",
        "                ld8((uint32_t)(c->esi + 1U)) == (uint8_t)'x' &&",
        "                ld8((uint32_t)(c->esi + 2U)) == (uint8_t)'0' &&",
        "                ld8((uint32_t)(c->esi + 3U)) == (uint8_t)':') {",
        "            if (ld8((uint32_t)(c->esi + _vita_root_offset)) ==",
        "                    (uint8_t)'/')",
        "                ++_vita_root_offset;",
        "            while (_vita_root_index < sizeof _vita_root_tail - 1U &&",
        "                    _vita_root_offset + _vita_root_index < c->edx &&",
        "                    ld8((uint32_t)(c->esi + _vita_root_offset +",
        "                        _vita_root_index)) ==",
        "                    (uint8_t)_vita_root_tail[_vita_root_index])",
        "                ++_vita_root_index;",
        "            _vita_root_offset += _vita_root_index;",
        "            if (_vita_root_index == sizeof _vita_root_tail - 1U &&",
        "                    (_vita_root_offset == c->edx ||",
        "                     ld8((uint32_t)(c->esi + _vita_root_offset)) ==",
        "                        (uint8_t)'/'))",
        "                goto L_00563151;",
        "        }",
        "    }",
        "#endif",
    )


def lua_pc_startup_bypass_for_body(img, root_rva, em, order):
    """Validate the exact PC-only edge around reserve/Lua initialization."""
    members = frozenset(order)
    if LUA_PC_STARTUP_BYPASS_SITE_RVA not in members:
        return False
    if root_rva not in LUA_PC_STARTUP_BYPASS_ROOTS:
        raise RuntimeError(
            "unexpected Lua startup bypass membership at root %08x" % root_rva)
    machine_windows = (
        (LUA_PC_STARTUP_BYPASS_MANAGER_ZERO_RVA,
         LUA_PC_STARTUP_BYPASS_MANAGER_ZERO_MACHINE,
         "manager zero-state"),
        (LUA_PC_STARTUP_BYPASS_SITE_MACHINE_RVA,
         LUA_PC_STARTUP_BYPASS_SITE_MACHINE,
         "site"),
        (LUA_PC_STARTUP_BYPASS_TARGET_RVA,
         LUA_PC_STARTUP_BYPASS_TARGET_MACHINE,
         "target"),
    )
    for address, expected, description in machine_windows:
        if img.code_at(address, len(expected)) != expected:
            raise RuntimeError(
                "Lua startup bypass %s machine window changed" % description)
    skipped = img.code_at(
        LUA_PC_STARTUP_BYPASS_SITE_RVA,
        LUA_PC_STARTUP_BYPASS_SKIPPED_END_RVA -
        LUA_PC_STARTUP_BYPASS_SITE_RVA,
    )
    if hashlib.sha256(skipped).hexdigest() != \
            LUA_PC_STARTUP_BYPASS_SKIPPED_SHA256:
        raise RuntimeError("Lua startup bypass skipped machine region changed")
    required = {
        LUA_PC_STARTUP_BYPASS_MANAGER_ZERO_RVA, 0x0050B656,
        LUA_PC_STARTUP_BYPASS_SITE_MACHINE_RVA,
        LUA_PC_STARTUP_BYPASS_SITE_RVA, 0x0050B6F4, 0x0050B6F6,
        0x0050B71C, 0x0050B767,
        0x0050B7A7, 0x0050B7AD, 0x0050B7B4, 0x0050B7B6,
        0x0050B7BC, LUA_PC_STARTUP_BYPASS_TARGET_RVA, 0x0050B7CB,
        0x0050B7D5,
    }
    if not required.issubset(members):
        raise RuntimeError(
            "Lua startup bypass body is missing pinned instructions")
    if LUA_PC_STARTUP_BYPASS_SITE_RVA in em.labels:
        raise RuntimeError("Lua startup bypass site acquired an alternate entry")
    if LUA_PC_STARTUP_BYPASS_TARGET_RVA in em.labels:
        raise RuntimeError(
            "Lua startup bypass target acquired an alternate entry")
    if LUA_VITA_STARTUP_INIT_RVA not in em.labels:
        raise RuntimeError("Lua startup initializer resume is not a local label")
    return True


def lua_pc_tick_bypass_for_body(img, root_rva, em, order):
    """Validate the exact PC/no-Lua edge around the main-loop GC tick."""
    members = frozenset(order)
    if LUA_PC_TICK_BYPASS_SITE_RVA not in members:
        return False
    if root_rva != LUA_PC_TICK_BYPASS_ROOT:
        raise RuntimeError(
            "unexpected Lua tick bypass membership at root %08x" % root_rva)

    if img.code_at(LUA_PC_TICK_BYPASS_MACHINE_RVA,
                   len(LUA_PC_TICK_BYPASS_MACHINE)) != \
            LUA_PC_TICK_BYPASS_MACHINE:
        raise RuntimeError("Lua tick bypass machine window changed")
    callee = img.code_at(
        LUA_PC_TICK_CALLEE_RVA,
        LUA_PC_TICK_CALLEE_END_RVA - LUA_PC_TICK_CALLEE_RVA,
    )
    if hashlib.sha256(callee).hexdigest() != LUA_PC_TICK_CALLEE_SHA256:
        raise RuntimeError("Lua tick controller body changed")
    if (img.code_at(LUA_PC_TICK_COUNT_RVA,
                    len(LUA_PC_TICK_COUNT_MACHINE)) !=
            LUA_PC_TICK_COUNT_MACHINE or
            img.code_at(LUA_PC_TICK_STEP_RVA,
                        len(LUA_PC_TICK_STEP_MACHINE)) !=
            LUA_PC_TICK_STEP_MACHINE):
        raise RuntimeError("Lua tick lua_gc argument windows changed")

    rel32_xrefs = []
    for site in range(img.text_rva, img.text_end - 4):
        if img.mem[site] != 0xE8:
            continue
        displacement = int.from_bytes(
            img.code_at(site + 1, 4), "little", signed=True)
        if ((site + 5 + displacement) & 0xFFFFFFFF) == \
                LUA_PC_TICK_CALLEE_RVA:
            rel32_xrefs.append(site)
    address_refs = tuple(
        site for site in sorted(img.reloc_rvas)
        if int.from_bytes(img.code_at(site, 4), "little") ==
        img.va(LUA_PC_TICK_CALLEE_RVA)
    )
    iat_value = img.va(LUA_GC_IAT_RVA).to_bytes(4, "little")
    iat_operands = []
    cursor = img.text_rva
    while True:
        cursor = img.mem.find(iat_value, cursor, img.text_end)
        if cursor < 0:
            break
        iat_operands.append(cursor)
        cursor += 1
    imports = dict(read_imports(EXE))
    if (tuple(rel32_xrefs) != (LUA_PC_TICK_BYPASS_SITE_RVA,) or
            address_refs or
            tuple(iat_operands) != LUA_GC_IAT_OPERAND_RVAS or
            any(site not in img.reloc_rvas for site in iat_operands) or
            imports.get(LUA_GC_IAT_RVA) != LUA_GC_IMPORT_NAME):
        raise RuntimeError("Lua tick caller/callee/IAT identity changed")

    required = {
        LUA_PC_TICK_BYPASS_MACHINE_RVA, 0x0048BE06,
        LUA_PC_TICK_BYPASS_SITE_RVA, LUA_PC_TICK_BYPASS_TARGET_RVA,
        0x0048BE12,
    }
    if not required.issubset(members):
        raise RuntimeError("Lua tick bypass body is missing pinned instructions")
    if LUA_PC_TICK_BYPASS_SITE_RVA in em.labels:
        raise RuntimeError("Lua tick bypass site acquired an alternate entry")
    if LUA_PC_TICK_BYPASS_TARGET_RVA not in em.labels:
        raise RuntimeError("Lua tick bypass continuation is not a local label")
    return True


def lua_pc_room_init_bypass_for_body(img, root_rva, em, order):
    """Validate the exact PC/no-Lua diagnostic tail in Room::Init."""
    members = frozenset(order)
    site = LUA_PC_ROOM_INIT_BYPASS_SITE_RVA
    target = LUA_PC_ROOM_INIT_BYPASS_TARGET_RVA
    if site not in members:
        return False
    if root_rva not in LUA_PC_ROOM_INIT_BYPASS_ROOTS:
        raise RuntimeError(
            "unexpected Room::Init Lua bypass membership at root %08x"
            % root_rva)

    owner = img.code_at(
        LUA_PC_ROOM_INIT_OWNER_RVA,
        LUA_PC_ROOM_INIT_OWNER_END_RVA - LUA_PC_ROOM_INIT_OWNER_RVA,
    )
    skipped = img.code_at(site, target - site)
    required = {
        LUA_PC_ROOM_INIT_PREFIX_RVA, site, 0x003B5861,
        0x003B5867, 0x003B5869, 0x003B586B,
        0x003B586E, 0x003B5870, 0x003B5873,
        0x003B5875, 0x003B5877, 0x003B587A,
        0x003B587C, 0x003B587F, 0x003B5880,
        0x003B5882, 0x003B5884, 0x003B5887,
        0x003B5889, 0x003B588C, 0x003B588D,
        0x003B5892, 0x003B5894, 0x003B5899,
        0x003B589F, target,
    }
    if (hashlib.sha256(owner).hexdigest() !=
            LUA_PC_ROOM_INIT_OWNER_SHA256 or
            img.code_at(LUA_PC_ROOM_INIT_PREFIX_RVA,
                        len(LUA_PC_ROOM_INIT_PREFIX_MACHINE)) !=
            LUA_PC_ROOM_INIT_PREFIX_MACHINE or
            hashlib.sha256(skipped).hexdigest() !=
            LUA_PC_ROOM_INIT_SKIPPED_SHA256 or
            img.code_at(target, len(LUA_PC_ROOM_INIT_TARGET_MACHINE)) !=
            LUA_PC_ROOM_INIT_TARGET_MACHINE or
            img.code_at(LUA_PC_ROOM_INIT_FORMAT_RVA,
                        len(LUA_PC_ROOM_INIT_FORMAT)) !=
            LUA_PC_ROOM_INIT_FORMAT or
            not required.issubset(members) or
            any(rva not in img.reloc_rvas
                for rva in LUA_PC_ROOM_INIT_RELOC_RVAS) or
            int.from_bytes(img.code_at(0x003B5863, 4), "little") !=
            img.va(LUA_GC_IAT_RVA) or
            any(img.code_at(call, 2) != bytes.fromhex("ffd6")
                for call in LUA_PC_ROOM_INIT_CALL_RVAS)):
        raise RuntimeError("Room::Init Lua diagnostic block changed")
    if any(site <= label <= target for label in em.labels):
        raise RuntimeError(
            "Room::Init Lua bypass region acquired an alternate entry")
    if root_rva == LUA_PC_ROOM_INIT_OWNER_RVA and (
            len(order) != 73 or not order or max(order) != 0x003B58E8):
        raise RuntimeError("Room::Init Lua tail owner CFG changed")
    return True


def kage_pc_loop_stages_for_body(img, root_rva, em, order):
    """Validate all seven exact main-loop/backend timing seams."""
    members = frozenset(order)
    stage_sites = frozenset(stage[0] for stage in KAGE_PC_LOOP_STAGES)
    reached = stage_sites & members
    if not reached:
        return ()
    if root_rva != KAGE_PC_LOOP_STAGE_ROOT:
        raise RuntimeError(
            "unexpected loop heartbeat membership at root %08x" % root_rva)
    machine_windows = (
        (KAGE_PC_LOOP_HEAD_RVA, KAGE_PC_LOOP_HEAD_MACHINE, "loop head"),
        (KAGE_PC_LOOP_BACKEDGE_1_RVA,
         KAGE_PC_LOOP_BACKEDGE_1_MACHINE, "conditional backedge"),
        (KAGE_PC_LOOP_BACKEDGE_2_RVA,
         KAGE_PC_LOOP_BACKEDGE_2_MACHINE, "terminal backedge"),
        (KAGE_PC_LIMITER_ENTRY_RVA,
         KAGE_PC_LIMITER_ENTRY_MACHINE, "software limiter entry"),
        (KAGE_PC_FRAME_STAGES_MACHINE_RVA,
         KAGE_PC_FRAME_STAGES_MACHINE, "Update/Render/return"),
    )
    for address, expected, description in machine_windows:
        if img.code_at(address, len(expected)) != expected:
            raise RuntimeError(
                "loop heartbeat %s machine window changed" % description)

    call_targets = (
        (KAGE_PC_LOOP_HEAD_RVA, KAGE_PC_LOOP_HEAD_TARGET_RVA),
        (KAGE_PC_SERVICE_ENTRY_RVA, KAGE_PC_SERVICE_TARGET_RVA),
        (KAGE_PC_UPDATE_ENTRY_RVA, KAGE_PC_UPDATE_TARGET_RVA),
        (KAGE_PC_RENDER_ENTRY_RVA, KAGE_PC_RENDER_TARGET_RVA),
        (KAGE_PC_LIMITER_ENTRY_RVA,
         KAGE_PC_LIMITER_ENTRY_TARGET_RVA),
    )
    for site, expected_target in call_targets:
        call = img.code_at(site, 5)
        target = (site + 5 + int.from_bytes(
            call[1:], "little", signed=True)) & 0xFFFFFFFF
        if call[0] != 0xE8 or target != expected_target:
            raise RuntimeError(
                "loop heartbeat call target changed at %08x" % site)

    required = {
        KAGE_PC_LOOP_BACKEDGE_1_RVA, 0x0048BE38,
        KAGE_PC_LOOP_BACKEDGE_2_RVA,
        0x0048BE06, LUA_PC_TICK_BYPASS_SITE_RVA,
        LUA_PC_TICK_BYPASS_TARGET_RVA,
    } | stage_sites
    if not required.issubset(members):
        raise RuntimeError("loop heartbeat body is missing pinned instructions")
    required_labels = {
        KAGE_PC_LOOP_HEAD_RVA, KAGE_PC_LIMITER_ENTRY_RVA,
    }
    if not required_labels.issubset(em.labels):
        raise RuntimeError("loop timing seam lost a required local label")
    # 0048be3e is intentionally both fall-through and the slow-frame branch;
    # either predecessor enters the same software limiter before our hook.
    alternate_entries = (stage_sites - required_labels) & em.labels
    if alternate_entries:
        raise RuntimeError(
            "loop heartbeat stages acquired alternate entries: %s"
            % ",".join("%08x" % r for r in sorted(alternate_entries)))
    return KAGE_PC_LOOP_STAGES


def vita_fullspeed_cadence_seams_for_body(
        img, root_rva, em, insns, order, body,
        extra_entries, indirect_edges):
    """Validate read-only Manager/Game lifecycle/Render observations."""
    members = frozenset(order)
    manager_sites = frozenset((
        VITA_FULLSPEED_MANAGER_ENTRY_OBSERVE_RVA,
        VITA_FULLSPEED_GAME_UPDATE_CALL_RVA,
        VITA_FULLSPEED_GAME_UPDATE_RETURN_RVA,
    ))
    render_sites = frozenset((VITA_FULLSPEED_RENDER_PARITY_OBSERVE_RVA,))
    publish_sites = frozenset((
        VITA_FULLSPEED_MANAGER_REBASE_OBSERVE_RVA,
        VITA_FULLSPEED_GAME_PUBLISH_OBSERVE_RVA,
    ))
    game_return_sites = frozenset(VITA_FULLSPEED_GAME_UPDATE_RETURN_RVAS)
    game_early_return_sites = frozenset(
        VITA_FULLSPEED_GAME_UPDATE_EARLY_RETURN_RVAS)
    if root_rva == VITA_FULLSPEED_MANAGER_ROOT_RVA:
        sites = manager_sites
        windows = (
            (VITA_FULLSPEED_MANAGER_ENTRY_MACHINE_RVA,
             VITA_FULLSPEED_MANAGER_ENTRY_MACHINE,
             "Manager entry/parity"),
            (VITA_STABLE30_MANAGER_GUARD_CHAIN_RVA,
             VITA_STABLE30_MANAGER_GUARD_CHAIN_MACHINE,
             "stable30 Manager native guards"),
            (VITA_FULLSPEED_MANAGER_FAST_INCREMENT_RVA,
             VITA_FULLSPEED_MANAGER_FAST_INCREMENT_MACHINE,
             "Manager fast increment"),
            (VITA_FULLSPEED_GAME_CALL_MACHINE_RVA,
             VITA_FULLSPEED_GAME_CALL_MACHINE,
             "Game::Update call"),
            (VITA_FULLSPEED_MANAGER_FINAL_INCREMENT_RVA,
             VITA_FULLSPEED_MANAGER_FINAL_INCREMENT_MACHINE,
             "Manager final increment"),
            (VITA_FULLSPEED_GAME_FRAME_MACHINE_RVA,
             VITA_FULLSPEED_GAME_FRAME_MACHINE,
             "Game frame increment"),
            (VITA_FULLSPEED_CONTINUE_CALL_MACHINE_RVA,
             VITA_FULLSPEED_CONTINUE_CALL_MACHINE,
             "Continue helper call"),
        )
    elif root_rva == VITA_FULLSPEED_RENDER_ROOT_RVA:
        sites = render_sites
        windows = ((
            VITA_FULLSPEED_RENDER_PARITY_MACHINE_RVA,
            VITA_FULLSPEED_RENDER_PARITY_MACHINE,
            "Render parity/interpolation",
        ),)
    elif root_rva == VITA_FULLSPEED_GAME_PUBLISH_ROOT_RVA:
        sites = publish_sites
        windows = ((
            VITA_FULLSPEED_GAME_PUBLISH_MACHINE_RVA,
            VITA_FULLSPEED_GAME_PUBLISH_MACHINE,
            "Game publication chain",
        ),)
    elif root_rva == VITA_FULLSPEED_GAME_UPDATE_ROOT_RVA:
        sites = game_early_return_sites
        windows = ((
            VITA_FULLSPEED_GAME_FRAME_MACHINE_RVA,
            VITA_FULLSPEED_GAME_FRAME_MACHINE,
            "Game frame increment",
        ),)
    else:
        reached = (
            manager_sites | render_sites | publish_sites |
            game_return_sites) & members
        if reached:
            raise RuntimeError(
                "fullspeed cadence seam acquired unexpected owner %08x"
                % root_rva)
        return ()

    if not sites.issubset(members):
        raise RuntimeError(
            "fullspeed cadence owner %08x is missing pinned instructions: %s"
            % (root_rva, ",".join(
                "%08x" % site for site in sorted(sites - members))))
    for address, expected, description in windows:
        if img.code_at(address, len(expected)) != expected:
            raise RuntimeError(
                "fullspeed cadence %s machine window changed" % description)

    if root_rva == VITA_FULLSPEED_MANAGER_ROOT_RVA:
        call = img.code_at(VITA_FULLSPEED_GAME_UPDATE_CALL_RVA, 5)
        target = (VITA_FULLSPEED_GAME_UPDATE_CALL_RVA + 5 + int.from_bytes(
            call[1:], "little", signed=True)) & 0xFFFFFFFF
        if call[0] != 0xE8 or target != 0x002CDCF0:
            raise RuntimeError("fullspeed cadence Game::Update target changed")
        if VITA_FULLSPEED_GAME_UPDATE_RETURN_RVA in em.labels:
            raise RuntimeError(
                "fullspeed cadence Game::Update return acquired alternate entry")
        continue_call = img.code_at(0x004B0079, 5)
        continue_target = (0x004B0079 + 5 + int.from_bytes(
            continue_call[1:], "little", signed=True)) & 0xFFFFFFFF
        if continue_call[0] != 0xE8 or \
                continue_target != VITA_FULLSPEED_GAME_PUBLISH_ROOT_RVA:
            raise RuntimeError(
                "fullspeed cadence Continue helper target changed")
    elif root_rva == VITA_FULLSPEED_GAME_PUBLISH_ROOT_RVA:
        for site, expected_target, description in (
                (0x004B404A, 0x005EACF8, "allocation"),
                (0x004B4061, 0x002C5AA0, "Game constructor"),
                (0x004B4072, 0x002C8C90, "Game initialization")):
            call = img.code_at(site, 5)
            target = (site + 5 + int.from_bytes(
                call[1:], "little", signed=True)) & 0xFFFFFFFF
            if call[0] != 0xE8 or target != expected_target:
                raise RuntimeError(
                    "fullspeed cadence %s target changed" % description)
    elif root_rva == VITA_FULLSPEED_GAME_UPDATE_ROOT_RVA:
        owner = img.code_at(
            root_rva, VITA_FULLSPEED_GAME_UPDATE_END_RVA - root_rva)
        order_sha256 = hashlib.sha256(b"".join(
            site.to_bytes(4, "little") for site in order)).hexdigest()
        actual_edges = {
            site: tuple(targets)
            for site, targets in indirect_edges.items()
        }
        actual_returns = tuple(
            site for site in order if insns[site].mnemonic == "ret")
        emitted_by_rva = {
            instruction.address: legacy_statements(statements)
            for instruction, statements in body
        }
        expected_return_statements = (
            "(void)gpop_generated(c);",
            "GUEST_STACK_CALLSITE_BARRIER();",
            "return;",
        )
        if (hashlib.sha256(owner).hexdigest() !=
                VITA_FULLSPEED_GAME_UPDATE_BODY_SHA256 or
                len(order) != VITA_FULLSPEED_GAME_UPDATE_INSNS or
                not order or order[0] != root_rva or
                order[-1] != VITA_FULLSPEED_GAME_UPDATE_NORMAL_RETURN_RVA or
                order_sha256 != VITA_FULLSPEED_GAME_UPDATE_ORDER_SHA256 or
                tuple(extra_entries) !=
                VITA_FULLSPEED_GAME_UPDATE_SWITCH_ENTRIES or
                actual_edges != VITA_FULLSPEED_GAME_UPDATE_SWITCH_EDGES or
                actual_returns != VITA_FULLSPEED_GAME_UPDATE_RETURN_RVAS or
                any(insns[site].size != 1 or
                    bytes(insns[site].bytes) != b"\xc3" or
                    insns[site].op_str or
                    emitted_by_rva.get(site) != expected_return_statements
                    for site in actual_returns) or
                game_return_sites & em.labels or
                VITA_FULLSPEED_GAME_FRAME_MACHINE_RVA not in members or
                any(site >= VITA_FULLSPEED_GAME_FRAME_MACHINE_RVA
                    for site in game_early_return_sites) or
                VITA_FULLSPEED_GAME_UPDATE_NORMAL_RETURN_RVA <=
                VITA_FULLSPEED_GAME_FRAME_MACHINE_RVA or
                owner.count(VITA_FULLSPEED_GAME_FRAME_MACHINE) != 1):
            raise RuntimeError(
                "fullspeed cadence Game::Update body/order/return set changed")
    return tuple(sorted(sites))


def vita_sim_cadence_receipt_for_body(
        img, root_rva, em, insns, order, body,
        extra_entries, indirect_edges):
    """Authenticate the one default-off Game::Update entry receipt seam."""
    members = frozenset(order)
    site = VITA_SIM_CADENCE_GAME_UPDATE_ROOT_RVA
    if root_rva != site:
        if site in members:
            raise RuntimeError(
                "simulation cadence seam acquired unexpected owner %08x" %
                root_rva)
        return False

    owner = img.code_at(
        site, VITA_SIM_CADENCE_GAME_UPDATE_END_RVA - site)
    order_sha256 = hashlib.sha256(b"".join(
        address.to_bytes(4, "little") for address in order)).hexdigest()
    actual_edges = {
        address: tuple(targets)
        for address, targets in indirect_edges.items()
    }
    actual_returns = tuple(
        address for address in order if insns[address].mnemonic == "ret")
    emitted_by_rva = {
        instruction.address: legacy_statements(statements)
        for instruction, statements in body
    }
    expected_return_statements = (
        "(void)gpop_generated(c);",
        "GUEST_STACK_CALLSITE_BARRIER();",
        "return;",
    )
    manager_call = img.code_at(
        VITA_SIM_CADENCE_MANAGER_CALL_RVA,
        len(VITA_SIM_CADENCE_MANAGER_CALL_MACHINE))
    manager_target = (
        VITA_SIM_CADENCE_MANAGER_CALL_RVA + len(manager_call) +
        int.from_bytes(manager_call[1:], "little", signed=True)
    ) & 0xFFFFFFFF
    if (hashlib.sha256(owner).hexdigest() !=
            VITA_SIM_CADENCE_GAME_UPDATE_BODY_SHA256 or
            img.code_at(site,
                        len(VITA_SIM_CADENCE_GAME_UPDATE_PREFIX_MACHINE)) !=
            VITA_SIM_CADENCE_GAME_UPDATE_PREFIX_MACHINE or
            len(order) != VITA_SIM_CADENCE_GAME_UPDATE_INSNS or
            not order or order[0] != site or
            order[-1] != VITA_FULLSPEED_GAME_UPDATE_NORMAL_RETURN_RVA or
            order_sha256 != VITA_SIM_CADENCE_GAME_UPDATE_ORDER_SHA256 or
            tuple(extra_entries) !=
            VITA_FULLSPEED_GAME_UPDATE_SWITCH_ENTRIES or
            actual_edges != VITA_FULLSPEED_GAME_UPDATE_SWITCH_EDGES or
            actual_returns != VITA_FULLSPEED_GAME_UPDATE_RETURN_RVAS or
            any(insns[address].size != 1 or
                bytes(insns[address].bytes) != b"\xc3" or
                insns[address].op_str or
                emitted_by_rva.get(address) != expected_return_statements
                for address in actual_returns) or
            frozenset(actual_returns) & em.labels or
            manager_call != VITA_SIM_CADENCE_MANAGER_CALL_MACHINE or
            manager_call[:1] != b"\xe8" or manager_target != site):
        raise RuntimeError(
            "simulation cadence Game::Update body/caller identity changed")
    return True


def vita_audio_cooperative_poll_for_body(img, root_rva, order):
    """Pin the one owner-thread audio safe point in room instantiation."""
    owner = ROOM_FIX_SPAWN_ENTRY_REMAP_OWNER
    site = VITA_AUDIO_COOPERATIVE_POLL_SITE_RVA
    if site not in frozenset(order):
        return False
    if root_rva not in VITA_AUDIO_COOPERATIVE_POLL_ROOTS:
        raise RuntimeError(
            "unexpected cooperative audio poll membership at root %08x" %
            root_rva)
    activation = img.code_at(site, owner["activation_size"])
    call_rva = owner["activation_call_rva"]
    call = img.code_at(call_rva, len(owner["activation_call"]))
    call_target = (call_rva + len(call) +
                   int.from_bytes(call[1:], "little", signed=True))
    if (hashlib.sha256(activation).hexdigest() !=
            owner["activation_sha256"] or
            call != owner["activation_call"] or call[:1] != b"\xe8" or
            call_target != owner["logical_root"]):
        raise RuntimeError(
            "cooperative audio poll activation identity changed")
    return True


def kage_pc_menu_init_probes_for_body(img, root_rva, em, order):
    """Validate the exact PC-only MenuManager/Update progress probes."""
    members = frozenset(order)
    all_sites = frozenset(
        spec["site"] for spec in KAGE_PC_MENU_INIT_PROBES)
    reached = all_sites & members
    expected = tuple(
        spec for spec in KAGE_PC_MENU_INIT_PROBES
        if spec["root"] == root_rva)
    if not reached and not expected:
        return ()
    expected_sites = frozenset(spec["site"] for spec in expected)
    if reached != expected_sites:
        raise RuntimeError(
            "unexpected menu-init probe membership at root %08x: %s != %s"
            % (root_rva,
               ",".join("%08x" % r for r in sorted(reached)),
               ",".join("%08x" % r for r in sorted(expected_sites))))

    body_spec = next(
        (spec for spec in KAGE_PC_MENU_INIT_ROOT_BODIES
         if spec["root"] == root_rva), None)
    if body_spec is None:
        raise RuntimeError(
            "menu-init probe body identity is missing at root %08x" %
            root_rva)
    body = img.code_at(root_rva, body_spec["end"] - root_rva)
    if hashlib.sha256(body).hexdigest() != body_spec["body_sha256"]:
        raise RuntimeError(
            "menu-init probe body identity changed at root %08x" % root_rva)

    for spec in expected:
        site = spec["site"]
        machine = spec["machine"]
        decoded = tuple(T.CS.disasm(machine, site))
        if (img.code_at(site, len(machine)) != machine or
                len(decoded) != 1 or decoded[0].address != site or
                decoded[0].size != len(machine)):
            raise RuntimeError(
                "menu-init probe instruction changed at %08x" % site)
        if (site in em.labels) != spec["label"]:
            raise RuntimeError(
                "menu-init probe label status changed at %08x" % site)
    return expected


def kage_pc_menu_render_probes_for_body(img, root_rva, em, order):
    """Validate the bounded PC-only first state-1 menu Render trace."""
    members = frozenset(order)
    all_sites = frozenset(
        spec["site"] for spec in KAGE_PC_MENU_RENDER_PROBES)
    reached = all_sites & members
    expected = tuple(
        spec for spec in KAGE_PC_MENU_RENDER_PROBES
        if spec["root"] == root_rva)
    if not reached and not expected:
        return ()
    body_spec = next(
        (spec for spec in KAGE_PC_MENU_RENDER_ROOT_BODIES
         if spec["root"] == root_rva), None)
    if body_spec is None:
        raise RuntimeError(
            "menu-render probe body identity is missing at root %08x" %
            root_rva)
    body = img.code_at(root_rva, body_spec["end"] - root_rva)
    if (len(order) not in body_spec["insn_counts"] or
            hashlib.sha256(body).hexdigest() != body_spec["body_sha256"]):
        raise RuntimeError(
            "menu-render probe body/CFG identity changed at root %08x" %
            root_rva)

    expected_sites = frozenset(spec["site"] for spec in expected)
    probe_insn_counts = body_spec.get(
        "probe_insn_counts", body_spec["insn_counts"])
    if len(order) not in probe_insn_counts:
        if reached:
            raise RuntimeError(
                "menu-render probes reached by a non-probe CFG at root %08x" %
                root_rva)
        return ()
    if reached != expected_sites:
        raise RuntimeError(
            "unexpected menu-render probe membership at root %08x: %s != %s"
            % (root_rva,
               ",".join("%08x" % r for r in sorted(reached)),
               ",".join("%08x" % r for r in sorted(expected_sites))))

    for spec in expected:
        site = spec["site"]
        machine = spec["machine"]
        decoded = tuple(T.CS.disasm(machine, site))
        if (img.code_at(site, len(machine)) != machine or
                len(decoded) != 1 or decoded[0].address != site or
                decoded[0].size != len(machine)):
            raise RuntimeError(
                "menu-render probe instruction changed at %08x" % site)
        if (site in em.labels) != spec["label"]:
            raise RuntimeError(
                "menu-render probe label status changed at %08x" % site)
    return expected


