def validate_pc_glfw_guard_census(img):
    """Freeze every physical GLFW initialized guard and classify clocks.

    The guard bytes occur in many unrelated GLFW APIs.  Only an exact
    `double` zero-return/error-path shape is an inlined glfwGetTime clone;
    treating every guard as a clock would silently change window/input ABIs.
    """
    expected_sites = tuple(row[0] for row in PC_GLFW_GUARD_CENSUS)
    actual_sites = []
    cursor = img.text_rva
    while True:
        cursor = img.mem.find(
            PC_CLOCK_INLINE_GUARD_MACHINE, cursor, img.text_end)
        if cursor < 0:
            break
        actual_sites.append(cursor)
        cursor += 1
    if tuple(actual_sites) != expected_sites:
        raise RuntimeError(
            "GLFW initialized-guard physical census changed: %s != %s"
            % (",".join("%08x" % site for site in actual_sites),
               ",".join("%08x" % site for site in expected_sites)))

    clock_shaped = []
    for site, owners, branch_rva, zero_next, nonzero_next in \
            PC_GLFW_GUARD_CENSUS:
        if not owners or tuple(sorted(set(owners))) != owners:
            raise RuntimeError(
                "GLFW initialized-guard owner census malformed at %08x"
                % site)
        decoded = tuple(T.CS.disasm(img.code_at(site, 0x50), site))
        branch = next(
            (ins for ins in decoded if ins.address == branch_rva), None)
        operand = (branch.operands[0] if branch is not None and
                   len(branch.operands) == 1 else None)
        if (branch is None or branch.mnemonic not in ("je", "jne") or
                operand is None or operand.type != T.cx.X86_OP_IMM):
            raise RuntimeError(
                "GLFW initialized-guard branch changed at %08x" % site)
        target = operand.imm & 0xFFFFFFFF
        fallthrough = branch.address + branch.size
        observed_zero = target if branch.mnemonic == "je" else fallthrough
        observed_nonzero = fallthrough if branch.mnemonic == "je" else target
        if (observed_zero != zero_next or
                observed_nonzero != nonzero_next):
            raise RuntimeError(
                "GLFW initialized-guard continuations changed at %08x"
                % site)

        head = decoded[:8]
        if (len(head) == 8 and
                tuple(ins.mnemonic for ins in head) ==
                ("cmp", "jne", "push", "push", "call", "add",
                 "xorps", "jmp") and
                head[2].op_str == "0" and
                head[3].op_str == "0x%x" % PC_CLOCK_INLINE_ERROR_CODE and
                len(head[4].operands) == 1 and
                head[4].operands[0].type == T.cx.X86_OP_IMM and
                (head[4].operands[0].imm & 0xFFFFFFFF) ==
                PC_CLOCK_INLINE_ERROR_LOGGER_RVA and
                head[5].op_str == "esp, 8" and
                head[6].op_str == "xmm0, xmm0"):
            clock_shaped.append(site)

    if tuple(clock_shaped) != PC_CLOCK_KNOWN_INLINE_COPIES:
        raise RuntimeError(
            "unhandled inlined glfwGetTime family changed: %s != %s"
            % (",".join("%08x" % site for site in clock_shaped),
               ",".join("%08x" % site
                        for site in PC_CLOCK_KNOWN_INLINE_COPIES)))
    if PC_CLOCK_ROOT_RVA + 6 not in expected_sites:
        raise RuntimeError("public glfwGetTime guard absent from GLFW census")


def pc_glfw_guard_census_for_body(root_rva, order):
    """Return and validate this rendered body's physical guard memberships."""
    members = frozenset(order)
    expected = tuple(
        site for site, owners, _branch, _zero, _nonzero in
        PC_GLFW_GUARD_CENSUS if root_rva in owners)
    reached = tuple(
        site for site, _owners, _branch, _zero, _nonzero in
        PC_GLFW_GUARD_CENSUS if site in members)
    if reached != expected:
        raise RuntimeError(
            "GLFW initialized-guard body census changed at root %08x: %s != %s"
            % (root_rva,
               ",".join("%08x" % site for site in reached),
               ",".join("%08x" % site for site in expected)))
    return reached


def vita_glfw_hot_seams_for_body(img, root_rva, em, order):
    """Select three machine-pinned Vita policies at their GLFW fallbacks.

    These are deliberately not a replacement for `_glfwInputError`: only the
    exact uninitialized continuations of one popup query, one PollEvents copy
    and one WindowShouldClose copy gain Vita edges.  The original guarded
    paths remain rendered immediately afterwards for every non-Vita target.
    """
    members = frozenset(order)
    expected = tuple(
        spec for spec in VITA_GLFW_HOT_SEAM_SPECS
        if spec["root"] == root_rva)
    reached = tuple(
        spec for spec in VITA_GLFW_HOT_SEAM_SPECS
        if spec["site"] in members)
    if not expected:
        if reached:
            raise RuntimeError(
                "Vita GLFW hot seam reached by unexpected root %08x" %
                root_rva)
        return ()
    if len(expected) != 1 or reached != expected:
        raise RuntimeError(
            "Vita GLFW hot seam membership changed at root %08x" % root_rva)

    spec = expected[0]
    owner = img.code_at(
        spec["root"], spec["owner_end"] - spec["root"])
    window = img.code_at(
        spec["window_rva"], spec["window_end"] - spec["window_rva"])
    semantic = img.code_at(
        spec["semantic_rva"], len(spec["semantic_machine"]))
    row = next(
        (row for row in PC_GLFW_GUARD_CENSUS
         if row[0] == spec["guard"]), None)
    expected_row = (
        spec["guard"], (spec["root"],), spec["branch"],
        spec["site"], spec["nonzero"])
    if (hashlib.sha256(owner).hexdigest() != spec["owner_sha256"] or
            window != spec["window_machine"] or
            hashlib.sha256(window).hexdigest() != spec["window_sha256"] or
            semantic != spec["semantic_machine"] or row != expected_row):
        raise RuntimeError(
            "Vita GLFW hot seam owner/ABI changed at %08x" % spec["site"])

    decoded = tuple(T.CS.disasm(window, spec["window_rva"]))
    by_rva = {ins.address: ins for ins in decoded}
    branch = by_rva.get(spec["branch"])
    null_arg = by_rva.get(spec["site"])
    error_arg = by_rva.get(spec["site"] + 2)
    error_call = by_rva.get(spec["error_call"])
    cleanup = by_rva.get(spec["cleanup"])
    branch_operand = (branch.operands[0] if branch is not None and
                      len(branch.operands) == 1 else None)
    null_operand = (null_arg.operands[0] if null_arg is not None and
                    len(null_arg.operands) == 1 else None)
    error_operand = (error_arg.operands[0] if error_arg is not None and
                     len(error_arg.operands) == 1 else None)
    call_operand = (error_call.operands[0] if error_call is not None and
                    len(error_call.operands) == 1 else None)
    if (branch is None or branch.mnemonic != "jne" or
            branch_operand is None or
            branch_operand.type != T.cx.X86_OP_IMM or
            (branch_operand.imm & 0xFFFFFFFF) != spec["nonzero"] or
            null_arg is None or null_arg.mnemonic != "push" or
            null_operand is None or null_operand.type != T.cx.X86_OP_IMM or
            (null_operand.imm & 0xFFFFFFFF) != 0 or null_arg.size != 2 or
            error_arg is None or error_arg.mnemonic != "push" or
            error_operand is None or error_operand.type != T.cx.X86_OP_IMM or
            (error_operand.imm & 0xFFFFFFFF) != PC_CLOCK_INLINE_ERROR_CODE or
            error_call is None or error_call.mnemonic != "call" or
            call_operand is None or call_operand.type != T.cx.X86_OP_IMM or
            (call_operand.imm & 0xFFFFFFFF) !=
            PC_CLOCK_INLINE_ERROR_LOGGER_RVA or
            cleanup is None or cleanup.mnemonic != "add" or
            cleanup.op_str != "esp, 8"):
        raise RuntimeError(
            "Vita GLFW hot seam error path changed at %08x" % spec["site"])

    semantic_decoded = tuple(T.CS.disasm(
        semantic, spec["semantic_rva"]))
    kind = spec["kind"]
    if kind == "window-popup-false":
        if dict(read_imports(EXE)).get(0x006063B8) != \
                "USER32.dll!GetWindowLongA":
            raise RuntimeError("KAGE popup GetWindowLongA import changed")
        if (len(semantic_decoded) != 6 or
                tuple(ins.mnemonic for ins in semantic_decoded) !=
                ("push", "push", "call", "test", "js", "xor") or
                semantic_decoded[0].operands[0].imm & 0xFFFFFFFF !=
                0xFFFFFFF0 or
                semantic_decoded[1].operands[0].reg != T.cx.X86_REG_EAX or
                semantic_decoded[2].operands[0].type != T.cx.X86_OP_MEM or
                semantic_decoded[2].operands[0].mem.disp & 0xFFFFFFFF !=
                img.va(0x006063B8) or
                semantic_decoded[-1].op_str != "al, al"):
            raise RuntimeError("KAGE popup bool-return ABI changed")
        for caller, machine in VITA_GLFW_POPUP_CALLER_ABI_WINDOWS:
            caller_code = img.code_at(caller, len(machine))
            caller_decoded = tuple(T.CS.disasm(caller_code, caller))
            caller_operand = (
                caller_decoded[0].operands[0]
                if caller_decoded and len(caller_decoded[0].operands) == 1
                else None)
            if (caller_code != machine or len(caller_decoded) != 2 or
                    caller_decoded[0].mnemonic != "call" or
                    caller_operand is None or
                    caller_operand.type != T.cx.X86_OP_IMM or
                    (caller_operand.imm & 0xFFFFFFFF) != spec["root"] or
                    "al" not in caller_decoded[1].op_str):
                raise RuntimeError(
                    "KAGE popup caller AL contract changed at %08x" % caller)
    elif kind == "poll-events-noop":
        if (len(semantic_decoded) != 3 or
                tuple(ins.mnemonic for ins in semantic_decoded) !=
                ("jmp", "call", "call") or
                tuple(ins.operands[0].imm & 0xFFFFFFFF
                      for ins in semantic_decoded) !=
                (spec["continuation"], 0x005984B0, 0x0059D720)):
            raise RuntimeError("glfwPollEvents/XInput continuation changed")
    elif kind == "window-should-close-false":
        closed = semantic_decoded[0] if semantic_decoded else None
        closed_branch = semantic_decoded[1] if len(semantic_decoded) > 1 else None
        closed_mem = (closed.operands[0].mem if closed is not None and
                      len(closed.operands) == 2 and
                      closed.operands[0].type == T.cx.X86_OP_MEM else None)
        if (len(semantic_decoded) != 2 or closed.mnemonic != "cmp" or
                closed_mem is None or closed_mem.base != T.cx.X86_REG_EAX or
                closed_mem.disp != 8 or
                closed.operands[1].type != T.cx.X86_OP_IMM or
                closed.operands[1].imm != 1 or
                closed_branch.mnemonic != "jne" or
                closed_branch.operands[0].type != T.cx.X86_OP_IMM or
                (closed_branch.operands[0].imm & 0xFFFFFFFF) !=
                spec["continuation"]):
            raise RuntimeError("glfwWindowShouldClose closed-byte ABI changed")
    else:  # pragma: no cover - constant inventory is checked above
        raise RuntimeError("unknown Vita GLFW hot seam kind %s" % kind)

    if spec["continuation"] is not None:
        em.labels.add(spec["continuation"])
    return expected


def vita_glfw_error_attribution_for_body(img, root_rva, order):
    """Select the one machine-pinned `_glfwInputError` entry trace.

    This is diagnostic attribution, not a GLFW semantic replacement.  It
    reads the guest CALL return and first argument before the original
    prologue, writes no CPU or guest-memory state, and the original body
    always follows.  A raw caller census proves that every physical reference
    is a five-byte rel32 CALL, so the captured word is an exact return RVA.
    """
    members = frozenset(order)
    if VITA_GLFW_ERROR_ATTR_ROOT_RVA not in members:
        return False
    if root_rva != VITA_GLFW_ERROR_ATTR_ROOT_RVA:
        raise RuntimeError(
            "unexpected Vita GLFW error-attribution membership at root %08x"
            % root_rva)

    start = VITA_GLFW_ERROR_ATTR_ROOT_RVA
    end = VITA_GLFW_ERROR_ATTR_END_RVA
    body = img.code_at(start, end - start)
    code_end = GLFW_ERROR_SWITCH_RVA + 0x61
    decoded = tuple(T.CS.disasm(img.code_at(start, code_end - start), start))
    by_rva = {ins.address: ins for ins in decoded}
    first = by_rva.get(start)
    frame = by_rva.get(start + 1)
    code_argument = by_rva.get(0x0059B7BE)
    final_ret = by_rva.get(VITA_GLFW_ERROR_ATTR_LAST_RVA)
    order_sha256 = hashlib.sha256(b"".join(
        site.to_bytes(4, "little") for site in order)).hexdigest()

    if (hashlib.sha256(body).hexdigest() !=
            VITA_GLFW_ERROR_ATTR_BODY_SHA256 or
            body[:len(VITA_GLFW_ERROR_ATTR_ENTRY_MACHINE)] !=
            VITA_GLFW_ERROR_ATTR_ENTRY_MACHINE or
            len(order) != VITA_GLFW_ERROR_ATTR_INSNS or
            order[0] != start or
            order[-1] != VITA_GLFW_ERROR_ATTR_LAST_RVA or
            order_sha256 != VITA_GLFW_ERROR_ATTR_ORDER_SHA256 or
            len(decoded) != VITA_GLFW_ERROR_ATTR_INSNS or
            sum(ins.size for ins in decoded) != code_end - start or
            first is None or first.mnemonic != "push" or
            first.op_str != "ebp" or
            frame is None or frame.mnemonic != "mov" or
            frame.op_str != "ebp, esp" or
            code_argument is None or code_argument.mnemonic != "mov" or
            code_argument.op_str != "esi, dword ptr [ebp + 8]" or
            final_ret is None or final_ret.mnemonic != "ret" or
            final_ret.size != 1 or final_ret.op_str):
        raise RuntimeError("Vita GLFW error-attribution body/ABI changed")

    direct_xrefs = []
    for site in range(img.text_rva, img.text_end - 4):
        if img.mem[site] != 0xE8:
            continue
        displacement = int.from_bytes(
            img.code_at(site + 1, 4), "little", signed=True)
        if ((site + 5 + displacement) & 0xFFFFFFFF) == start:
            direct_xrefs.append(site)
    address_refs = tuple(
        site for site in sorted(img.reloc_rvas)
        if int.from_bytes(img.code_at(site, 4), "little") == img.va(start)
    )
    xrefs_sha256 = hashlib.sha256(b"".join(
        site.to_bytes(4, "little") for site in direct_xrefs)).hexdigest()
    if (len(direct_xrefs) != VITA_GLFW_ERROR_ATTR_DIRECT_XREFS or
            direct_xrefs[0] != VITA_GLFW_ERROR_ATTR_FIRST_XREF or
            direct_xrefs[-1] != VITA_GLFW_ERROR_ATTR_LAST_XREF or
            xrefs_sha256 != VITA_GLFW_ERROR_ATTR_XREFS_SHA256 or
            address_refs):
        raise RuntimeError(
            "Vita GLFW error-attribution caller/address census changed")
    return True


def vita_sfx_trace_for_body(img, root_rva, order, extra_entries):
    """Select the exact three-phase Vita SFX-slider diagnostic trace.

    The injected code observes the branch immediately before its original
    first instruction, the return from ClearVolumeModifier, and the return
    from the preview Play call.  Full owner/callee hashes and instruction
    windows keep this diagnostic attached to those semantics rather than to
    three remembered addresses.
    """
    members = frozenset(order)
    trace_sites = frozenset((
        VITA_SFX_TRACE_BEGIN_RVA,
        VITA_SFX_TRACE_POST_CLEAR_RVA,
        VITA_SFX_TRACE_END_SITE_RVA,
    ))
    if not trace_sites & members:
        return False
    if root_rva != VITA_SFX_TRACE_ROOT_RVA or not trace_sites <= members:
        raise RuntimeError(
            "unexpected Vita SFX trace membership at root %08x" % root_rva)

    start = VITA_SFX_TRACE_ROOT_RVA
    end = VITA_SFX_TRACE_END_RVA
    body = img.code_at(start, end - start)
    dispatch = img.code_at(
        VITA_SFX_TRACE_DISPATCH_RVA,
        VITA_SFX_TRACE_DISPATCH_END_RVA - VITA_SFX_TRACE_DISPATCH_RVA)
    window = img.code_at(
        VITA_SFX_TRACE_BEGIN_RVA,
        VITA_SFX_TRACE_WINDOW_END_RVA - VITA_SFX_TRACE_BEGIN_RVA)
    decoded = tuple(T.CS.disasm(window, VITA_SFX_TRACE_BEGIN_RVA))
    by_rva = {ins.address: ins for ins in decoded}
    order_sha256 = hashlib.sha256(b"".join(
        site.to_bytes(4, "little") for site in order)).hexdigest()

    table_size = 4 * len(VITA_SFX_TRACE_SWITCH_TARGETS)
    table = img.code_at(VITA_SFX_TRACE_SWITCH_TABLE_RVA, table_size)
    table_targets = tuple(
        img.rva_of(int.from_bytes(table[offset:offset + 4], "little"))
        for offset in range(0, len(table), 4)
    )
    unique_targets = tuple(dict.fromkeys(table_targets))
    table_slots = tuple(
        VITA_SFX_TRACE_SWITCH_TABLE_RVA + offset
        for offset in range(0, table_size, 4)
    )

    begin = by_rva.get(VITA_SFX_TRACE_BEGIN_RVA)
    manager = by_rva.get(0x00513677)
    volume_store = by_rva.get(0x0051367D)
    clear_call = by_rva.get(VITA_SFX_TRACE_CLEAR_CALL_RVA)
    post_clear = by_rva.get(VITA_SFX_TRACE_POST_CLEAR_RVA)
    preview_manager = by_rva.get(0x005136BD)
    preview_call = by_rva.get(VITA_SFX_TRACE_PREVIEW_CALL_RVA)
    finish = by_rva.get(VITA_SFX_TRACE_END_SITE_RVA)
    clear_target = (clear_call.operands[0].imm
                    if clear_call is not None and
                    len(clear_call.operands) == 1 and
                    clear_call.operands[0].type == T.cx.X86_OP_IMM else None)
    preview_target = (preview_call.operands[0].imm
                      if preview_call is not None and
                      len(preview_call.operands) == 1 and
                      preview_call.operands[0].type == T.cx.X86_OP_IMM
                      else None)

    clear_body = img.code_at(
        VITA_SFX_TRACE_CLEAR_ROOT_RVA,
        VITA_SFX_TRACE_CLEAR_END_RVA - VITA_SFX_TRACE_CLEAR_ROOT_RVA)
    clear_decoded = {
        ins.address: ins for ins in T.CS.disasm(
            clear_body, VITA_SFX_TRACE_CLEAR_ROOT_RVA)
    }
    clear_vector_end = clear_decoded.get(0x004894D1)
    clear_vector_begin = clear_decoded.get(0x004894D4)
    clear_stride = clear_decoded.get(0x004895C8)
    preview_body = img.code_at(
        VITA_SFX_TRACE_PREVIEW_ROOT_RVA,
        VITA_SFX_TRACE_PREVIEW_END_RVA - VITA_SFX_TRACE_PREVIEW_ROOT_RVA)

    if (hashlib.sha256(body).hexdigest() !=
            VITA_SFX_TRACE_BODY_SHA256 or
            len(order) != VITA_SFX_TRACE_INSNS or order[0] != start or
            order[-1] != VITA_SFX_TRACE_LAST_RVA or
            order_sha256 != VITA_SFX_TRACE_ORDER_SHA256 or
            hashlib.sha256(dispatch).hexdigest() !=
            VITA_SFX_TRACE_DISPATCH_SHA256 or
            hashlib.sha256(window).hexdigest() !=
            VITA_SFX_TRACE_WINDOW_SHA256 or
            len(decoded) != VITA_SFX_TRACE_WINDOW_INSNS or
            sum(ins.size for ins in decoded) != len(window) or
            begin is None or begin.mnemonic != "movd" or
            begin.op_str != "xmm0, edi" or
            manager is None or manager.mnemonic != "lea" or
            manager.op_str != "ecx, [esi + 0x29de0]" or
            volume_store is None or volume_store.mnemonic != "movss" or
            volume_store.op_str !=
            "dword ptr [esi + 0x29e14], xmm0" or
            clear_call is None or clear_call.mnemonic != "call" or
            clear_target != VITA_SFX_TRACE_CLEAR_ROOT_RVA or
            post_clear is None or post_clear.mnemonic != "mov" or
            post_clear.op_str != "esi, dword ptr [0x307fd680]" or
            preview_manager is None or preview_manager.mnemonic != "lea" or
            preview_manager.op_str != "ecx, [esi + 0x29de0]" or
            preview_call is None or preview_call.mnemonic != "call" or
            preview_target != VITA_SFX_TRACE_PREVIEW_ROOT_RVA or
            finish is None or finish.mnemonic != "jmp" or
            finish.op_str != "0x513d11" or
            table_targets != VITA_SFX_TRACE_SWITCH_TARGETS or
            len(unique_targets) != 17 or
            frozenset(extra_entries) != frozenset(unique_targets) or
            len(extra_entries) != len(unique_targets) or
            not all(slot in img.reloc_rvas for slot in table_slots) or
            VITA_SFX_TRACE_SWITCH_TABLE_RVA + table_size != end or
            hashlib.sha256(clear_body).hexdigest() !=
            VITA_SFX_TRACE_CLEAR_BODY_SHA256 or
            clear_vector_end is None or clear_vector_end.mnemonic != "mov" or
            clear_vector_end.op_str != "edx, dword ptr [eax + 4]" or
            clear_vector_begin is None or
            clear_vector_begin.mnemonic != "mov" or
            clear_vector_begin.op_str != "esi, dword ptr [eax]" or
            clear_stride is None or clear_stride.mnemonic != "add" or
            clear_stride.op_str != "ebx, 0x1b8" or
            hashlib.sha256(preview_body).hexdigest() !=
            VITA_SFX_TRACE_PREVIEW_BODY_SHA256):
        raise RuntimeError("Vita SFX trace body/call/layout changed")
    return True


def _vita_sfx_lazy_validate_advisory_owners(img):
    """Fail closed unless all 21 advisory pairs retain their exact owners."""
    observed = []
    expected_roots = tuple(
        spec["root"] for spec in VITA_SFX_LAZY_ADVISORY_OWNER_SPECS)
    if len(set(expected_roots)) != len(expected_roots):
        raise RuntimeError("Vita lazy-SFX duplicate advisory owner pin")

    for spec in VITA_SFX_LAZY_ADVISORY_OWNER_SPECS:
        root = spec["root"]
        end = spec["end"]
        owner = img.code_at(root, end - root)
        em, insns, order, _body, unsupported, indirect, _members = \
            B.translate(img, root, "vita_sfx_advisory_owner_pin", None)
        order_sha256 = hashlib.sha256(b"".join(
            site.to_bytes(4, "little") for site in order)).hexdigest()
        relocations = tuple(sorted(
            site for site in img.reloc_rvas if root <= site < end))
        relocations_sha256 = hashlib.sha256(b"".join(
            site.to_bytes(4, "little")
            for site in relocations)).hexdigest()
        members = frozenset(order)

        if (unsupported or indirect or
                hashlib.sha256(owner).hexdigest() != spec["body_sha256"] or
                len(order) != spec["insns"] or not order or
                order[0] != root or order[-1] != spec["last"] or
                order_sha256 != spec["order_sha256"] or
                len(relocations) != spec["relocations"] or
                relocations_sha256 != spec["relocations_sha256"]):
            raise RuntimeError(
                "Vita lazy-SFX advisory owner/CFG/relocations changed at "
                "%08x" % root)

        for call_rva, count_rva, count_machine, count_op_str in spec["pairs"]:
            call = insns.get(call_rva)
            count = insns.get(count_rva)
            call_target = (
                call.operands[0].imm & 0xFFFFFFFF
                if call is not None and len(call.operands) == 1 and
                call.operands[0].type == T.cx.X86_OP_IMM else None)
            if (call_rva not in members or count_rva not in members or
                    call is None or call.mnemonic != "call" or
                    call.size != 5 or call_target != VITA_SFX_LAZY_LOAD_ROOT_RVA or
                    count is None or count.mnemonic != "inc" or
                    bytes(count.bytes) != count_machine or
                    count.op_str != count_op_str or
                    {call_rva, count_rva} & em.labels or
                    call_rva >= count_rva):
                raise RuntimeError(
                    "Vita lazy-SFX advisory pair changed at %08x/%08x" %
                    (call_rva, count_rva))
            observed.append((call_rva, count_rva))

    expected = tuple(
        (pair[0], pair[1]) for pair in VITA_SFX_LAZY_ADVISORY_PAIRS)
    if (tuple(observed) != expected or
            len(observed) != VITA_SFX_LAZY_ADVISORY_PAIR_COUNT or
            len(set(observed)) != len(observed)):
        raise RuntimeError("Vita lazy-SFX advisory pair census changed")


def vita_sfx_lazy_advisory_pairs_for_body(img, root_rva, em, order):
    """Return exact Load+count pairs owned by one of five advisory bodies."""
    members = frozenset(order)
    reached = tuple(
        pair for pair in VITA_SFX_LAZY_ADVISORY_PAIRS
        if pair[0] in members or pair[1] in members)
    if not reached:
        return ()

    specs = tuple(
        spec for spec in VITA_SFX_LAZY_ADVISORY_OWNER_SPECS
        if spec["root"] == root_rva)
    if len(specs) != 1:
        raise RuntimeError(
            "unexpected Vita lazy-SFX advisory membership at root %08x" %
            root_rva)
    expected = specs[0]["pairs"]
    if (tuple((pair[0], pair[1]) for pair in reached) !=
            tuple((pair[0], pair[1]) for pair in expected) or
            any(not {pair[0], pair[1]} <= members for pair in expected) or
            any({pair[0], pair[1]} & em.labels for pair in expected)):
        raise RuntimeError(
            "partial Vita lazy-SFX advisory membership at root %08x" %
            root_rva)

    _vita_sfx_lazy_validate_advisory_owners(img)
    return tuple((pair[0], pair[1]) for pair in expected)


def vita_sfx_lazy_loadconfig_for_body(img, root_rva, em, order):
    """Validate the complete Vita first-Play materialisation package.

    This is intentionally a caller seam, not a replacement for
    SoundEffect::Load.  All 21 advisory pairs are pinned and Play remains the
    sole eager-on-first-use path.  The complete owners, Load callee, original
    zero/live branch, relocation inventories and direct-xref partition are
    proved before any source renderer may wrap an instruction.
    """
    members = frozenset(order)
    pair = frozenset((
        VITA_SFX_LAZY_LOADCONFIG_CALL_RVA,
        VITA_SFX_LAZY_LOADCONFIG_COUNT_RVA,
    ))
    if not pair & members:
        return False
    if root_rva != VITA_SFX_LAZY_LOADCONFIG_ROOT_RVA or not pair <= members:
        raise RuntimeError(
            "unexpected Vita lazy-SFX membership at root %08x" % root_rva)

    owner = img.code_at(
        VITA_SFX_LAZY_LOADCONFIG_ROOT_RVA,
        VITA_SFX_LAZY_LOADCONFIG_END_RVA -
        VITA_SFX_LAZY_LOADCONFIG_ROOT_RVA)
    window = img.code_at(
        VITA_SFX_LAZY_LOADCONFIG_WINDOW_RVA,
        VITA_SFX_LAZY_LOADCONFIG_WINDOW_END_RVA -
        VITA_SFX_LAZY_LOADCONFIG_WINDOW_RVA)
    load_body = img.code_at(
        VITA_SFX_LAZY_LOAD_ROOT_RVA,
        VITA_SFX_LAZY_LOAD_END_RVA - VITA_SFX_LAZY_LOAD_ROOT_RVA)
    audio_window = img.code_at(
        VITA_SFX_LAZY_LOAD_AUDIO_WINDOW_RVA,
        VITA_SFX_LAZY_LOAD_AUDIO_WINDOW_END_RVA -
        VITA_SFX_LAZY_LOAD_AUDIO_WINDOW_RVA)
    preload_body = img.code_at(
        VITA_SFX_LAZY_PRELOAD_ROOT_RVA,
        VITA_SFX_LAZY_PRELOAD_END_RVA - VITA_SFX_LAZY_PRELOAD_ROOT_RVA)
    play_body = img.code_at(
        VITA_SFX_LAZY_PLAY_ROOT_RVA,
        VITA_SFX_LAZY_PLAY_END_RVA - VITA_SFX_LAZY_PLAY_ROOT_RVA)
    decoded = tuple(T.CS.disasm(
        window, VITA_SFX_LAZY_LOADCONFIG_WINDOW_RVA))
    by_rva = {ins.address: ins for ins in decoded}
    audio_decoded = {
        ins.address: ins for ins in T.CS.disasm(
            audio_window, VITA_SFX_LAZY_LOAD_AUDIO_WINDOW_RVA)
    }
    order_sha256 = hashlib.sha256(b"".join(
        site.to_bytes(4, "little") for site in order)).hexdigest()

    call = by_rva.get(VITA_SFX_LAZY_LOADCONFIG_CALL_RVA)
    count = by_rva.get(VITA_SFX_LAZY_LOADCONFIG_COUNT_RVA)
    continuation = by_rva.get(VITA_SFX_LAZY_LOADCONFIG_CONTINUATION_RVA)
    load_target = (call.operands[0].imm & 0xFFFFFFFF
                   if call is not None and len(call.operands) == 1 and
                   call.operands[0].type == T.cx.X86_OP_IMM else None)
    audio_cmp = audio_decoded.get(VITA_SFX_LAZY_LOAD_AUDIO_BRANCH_RVA)
    audio_jump = audio_decoded.get(VITA_SFX_LAZY_LOAD_AUDIO_JUMP_RVA)
    zero_call = audio_decoded.get(VITA_SFX_LAZY_LOAD_AUDIO_ZERO_CALL_RVA)
    live_call = audio_decoded.get(VITA_SFX_LAZY_LOAD_AUDIO_LIVE_CALL_RVA)
    audio_target = (audio_jump.operands[0].imm & 0xFFFFFFFF
                    if audio_jump is not None and
                    len(audio_jump.operands) == 1 and
                    audio_jump.operands[0].type == T.cx.X86_OP_IMM else None)
    zero_target = (zero_call.operands[0].imm & 0xFFFFFFFF
                   if zero_call is not None and len(zero_call.operands) == 1 and
                   zero_call.operands[0].type == T.cx.X86_OP_IMM else None)

    def direct_call(site, machine):
        raw = img.code_at(site, len(machine))
        instructions = tuple(T.CS.disasm(raw, site))
        ins = instructions[0] if len(instructions) == 1 else None
        target = (ins.operands[0].imm & 0xFFFFFFFF
                  if ins is not None and len(ins.operands) == 1 and
                  ins.operands[0].type == T.cx.X86_OP_IMM else None)
        return raw, ins, target

    preload_raw, preload_call, preload_target = direct_call(
        VITA_SFX_LAZY_PRELOAD_CALL_RVA,
        VITA_SFX_LAZY_PRELOAD_CALL_MACHINE)
    play_raw, play_call, play_target = direct_call(
        VITA_SFX_LAZY_PLAY_CALL_RVA,
        VITA_SFX_LAZY_PLAY_CALL_MACHINE)
    play_count_raw = img.code_at(
        VITA_SFX_LAZY_PLAY_COUNT_RVA,
        len(VITA_SFX_LAZY_PLAY_COUNT_MACHINE))
    play_count_decoded = tuple(T.CS.disasm(
        play_count_raw, VITA_SFX_LAZY_PLAY_COUNT_RVA))
    play_count = (play_count_decoded[0]
                  if len(play_count_decoded) == 1 else None)

    direct_xrefs = []
    for site in range(img.text_rva, img.text_end - 4):
        if img.mem[site] != 0xE8:
            continue
        displacement = int.from_bytes(
            img.code_at(site + 1, 4), "little", signed=True)
        if ((site + 5 + displacement) & 0xFFFFFFFF) == \
                VITA_SFX_LAZY_LOAD_ROOT_RVA:
            direct_xrefs.append(site)
    xrefs_sha256 = hashlib.sha256(b"".join(
        site.to_bytes(4, "little") for site in direct_xrefs)).hexdigest()
    address_refs = tuple(
        site for site in sorted(img.reloc_rvas)
        if int.from_bytes(img.code_at(site, 4), "little") ==
        img.va(VITA_SFX_LAZY_LOAD_ROOT_RVA)
    )

    _vita_sfx_lazy_validate_advisory_owners(img)
    xref_partition = tuple(sorted(
        VITA_SFX_LAZY_ADVISORY_CALL_RVAS +
        (VITA_SFX_LAZY_PLAY_CALL_RVA,)))

    if (hashlib.sha256(owner).hexdigest() !=
            VITA_SFX_LAZY_LOADCONFIG_BODY_SHA256 or
            len(order) != VITA_SFX_LAZY_LOADCONFIG_INSNS or
            not order or order[0] != VITA_SFX_LAZY_LOADCONFIG_ROOT_RVA or
            order[-1] != VITA_SFX_LAZY_LOADCONFIG_LAST_RVA or
            order_sha256 != VITA_SFX_LAZY_LOADCONFIG_ORDER_SHA256 or
            hashlib.sha256(window).hexdigest() !=
            VITA_SFX_LAZY_LOADCONFIG_WINDOW_SHA256 or
            len(decoded) != VITA_SFX_LAZY_LOADCONFIG_WINDOW_INSNS or
            sum(ins.size for ins in decoded) != len(window) or
            call is None or call.mnemonic != "call" or
            bytes(call.bytes) != VITA_SFX_LAZY_LOADCONFIG_CALL_MACHINE or
            load_target != VITA_SFX_LAZY_LOAD_ROOT_RVA or
            count is None or count.mnemonic != "inc" or
            bytes(count.bytes) != VITA_SFX_LAZY_LOADCONFIG_COUNT_MACHINE or
            count.op_str != "dword ptr [esi + 0xc]" or
            continuation is None or continuation.mnemonic != "mov" or
            bytes(continuation.bytes) !=
            VITA_SFX_LAZY_LOADCONFIG_CONTINUATION_MACHINE or
            VITA_SFX_LAZY_LOADCONFIG_CALL_RVA + call.size !=
            VITA_SFX_LAZY_LOADCONFIG_COUNT_RVA or
            VITA_SFX_LAZY_LOADCONFIG_COUNT_RVA + count.size !=
            VITA_SFX_LAZY_LOADCONFIG_CONTINUATION_RVA or
            pair & em.labels or
            hashlib.sha256(load_body).hexdigest() !=
            VITA_SFX_LAZY_LOAD_BODY_SHA256 or
            hashlib.sha256(audio_window).hexdigest() !=
            VITA_SFX_LAZY_LOAD_AUDIO_WINDOW_SHA256 or
            img.code_at(VITA_SFX_LAZY_LOAD_AUDIO_BRANCH_RVA,
                        len(VITA_SFX_LAZY_LOAD_AUDIO_BRANCH_MACHINE)) !=
            VITA_SFX_LAZY_LOAD_AUDIO_BRANCH_MACHINE or
            audio_cmp is None or audio_cmp.mnemonic != "cmp" or
            audio_cmp.op_str != "byte ptr [0x307e7d44], 0" or
            audio_jump is None or audio_jump.mnemonic != "jne" or
            audio_target != VITA_SFX_LAZY_LOAD_AUDIO_LIVE_RVA or
            zero_call is None or zero_call.mnemonic != "call" or
            bytes(zero_call.bytes) !=
            VITA_SFX_LAZY_LOAD_AUDIO_ZERO_CALL_MACHINE or
            zero_target != 0x0056F970 or
            live_call is None or live_call.mnemonic != "call" or
            bytes(live_call.bytes) !=
            VITA_SFX_LAZY_LOAD_AUDIO_LIVE_CALL_MACHINE or
            live_call.op_str != "dword ptr [eax + 0x20]" or
            hashlib.sha256(preload_body).hexdigest() !=
            VITA_SFX_LAZY_PRELOAD_BODY_SHA256 or
            preload_raw != VITA_SFX_LAZY_PRELOAD_CALL_MACHINE or
            preload_call is None or preload_call.mnemonic != "call" or
            preload_target != VITA_SFX_LAZY_LOAD_ROOT_RVA or
            hashlib.sha256(play_body).hexdigest() !=
            VITA_SFX_LAZY_PLAY_BODY_SHA256 or
            play_raw != VITA_SFX_LAZY_PLAY_CALL_MACHINE or
            play_call is None or play_call.mnemonic != "call" or
            play_target != VITA_SFX_LAZY_LOAD_ROOT_RVA or
            play_count_raw != VITA_SFX_LAZY_PLAY_COUNT_MACHINE or
            play_count is None or play_count.mnemonic != "inc" or
            play_count.op_str != "dword ptr [ebx + 0xc]" or
            len(VITA_SFX_LAZY_ADVISORY_PAIRS) !=
            VITA_SFX_LAZY_ADVISORY_PAIR_COUNT or
            xref_partition != VITA_SFX_LAZY_LOAD_DIRECT_XREF_RVAS or
            tuple(direct_xrefs) != VITA_SFX_LAZY_LOAD_DIRECT_XREF_RVAS or
            len(direct_xrefs) != VITA_SFX_LAZY_LOAD_DIRECT_XREFS or
            xrefs_sha256 != VITA_SFX_LAZY_LOAD_XREFS_SHA256 or
            address_refs):
        raise RuntimeError(
            "Vita lazy-SFX owner/window/callee/fallback changed")
    return True


def vita_sfx_lazy_preload_for_body(img, root_rva, em, order):
    """Select the exact Vita audio-ready Preload materialisation pair.

    Preload is advisory for the live Vita backend: leave the SoundEffect
    unloaded and let the independently pinned Play caller materialise it on
    first use.  PC and the measured Audio-OFF fallback retain the original
    call/count pair.  Revalidate the complete lazy-audio package here so this
    owner cannot inherit a policy proved only while rendering LoadConfig.
    """
    members = frozenset(order)
    pair = frozenset((
        VITA_SFX_LAZY_PRELOAD_CALL_RVA,
        VITA_SFX_LAZY_PRELOAD_COUNT_RVA,
    ))
    if not pair & members:
        return False
    if root_rva != VITA_SFX_LAZY_PRELOAD_ROOT_RVA or not pair <= members:
        raise RuntimeError(
            "unexpected Vita lazy-Preload membership at root %08x" %
            root_rva)

    loadconfig_em, _insns, loadconfig_order, _body, unsupported, indirect, \
        _members = B.translate(
            img, VITA_SFX_LAZY_LOADCONFIG_ROOT_RVA,
            "vita_sfx_lazy_preload_package_pin", None)
    if (unsupported or indirect or
            not vita_sfx_lazy_loadconfig_for_body(
                img, VITA_SFX_LAZY_LOADCONFIG_ROOT_RVA,
                loadconfig_em, loadconfig_order)):
        raise RuntimeError("Vita lazy-Preload package proof changed")

    owner = img.code_at(
        VITA_SFX_LAZY_PRELOAD_ROOT_RVA,
        VITA_SFX_LAZY_PRELOAD_END_RVA - VITA_SFX_LAZY_PRELOAD_ROOT_RVA)
    window = img.code_at(
        VITA_SFX_LAZY_PRELOAD_WINDOW_RVA,
        VITA_SFX_LAZY_PRELOAD_WINDOW_END_RVA -
        VITA_SFX_LAZY_PRELOAD_WINDOW_RVA)
    decoded = tuple(T.CS.disasm(
        window, VITA_SFX_LAZY_PRELOAD_WINDOW_RVA))
    by_rva = {ins.address: ins for ins in decoded}
    order_sha256 = hashlib.sha256(b"".join(
        site.to_bytes(4, "little") for site in order)).hexdigest()

    loaded_cmp = by_rva.get(VITA_SFX_LAZY_PRELOAD_LOADED_CMP_RVA)
    branch = by_rva.get(VITA_SFX_LAZY_PRELOAD_BRANCH_RVA)
    call = by_rva.get(VITA_SFX_LAZY_PRELOAD_CALL_RVA)
    count = by_rva.get(VITA_SFX_LAZY_PRELOAD_COUNT_RVA)
    continuation = by_rva.get(VITA_SFX_LAZY_PRELOAD_CONTINUATION_RVA)
    clear = by_rva.get(VITA_SFX_LAZY_PRELOAD_CLEAR_RVA)
    branch_target = (branch.operands[0].imm & 0xFFFFFFFF
                     if branch is not None and len(branch.operands) == 1 and
                     branch.operands[0].type == T.cx.X86_OP_IMM else None)
    call_target = (call.operands[0].imm & 0xFFFFFFFF
                   if call is not None and len(call.operands) == 1 and
                   call.operands[0].type == T.cx.X86_OP_IMM else None)

    if (hashlib.sha256(owner).hexdigest() !=
            VITA_SFX_LAZY_PRELOAD_BODY_SHA256 or
            len(order) != VITA_SFX_LAZY_PRELOAD_INSNS or
            not order or order[0] != VITA_SFX_LAZY_PRELOAD_ROOT_RVA or
            order[-1] != VITA_SFX_LAZY_PRELOAD_LAST_RVA or
            order_sha256 != VITA_SFX_LAZY_PRELOAD_ORDER_SHA256 or
            hashlib.sha256(window).hexdigest() !=
            VITA_SFX_LAZY_PRELOAD_WINDOW_SHA256 or
            len(decoded) != VITA_SFX_LAZY_PRELOAD_WINDOW_INSNS or
            sum(ins.size for ins in decoded) != len(window) or
            loaded_cmp is None or loaded_cmp.mnemonic != "cmp" or
            bytes(loaded_cmp.bytes) !=
            VITA_SFX_LAZY_PRELOAD_LOADED_CMP_MACHINE or
            loaded_cmp.op_str != "byte ptr [esi + 0x198], 0" or
            branch is None or branch.mnemonic != "jne" or
            bytes(branch.bytes) != VITA_SFX_LAZY_PRELOAD_BRANCH_MACHINE or
            branch_target != VITA_SFX_LAZY_PRELOAD_CONTINUATION_RVA or
            call is None or call.mnemonic != "call" or
            bytes(call.bytes) != VITA_SFX_LAZY_PRELOAD_CALL_MACHINE or
            call_target != VITA_SFX_LAZY_LOAD_ROOT_RVA or
            count is None or count.mnemonic != "inc" or
            bytes(count.bytes) != VITA_SFX_LAZY_PRELOAD_COUNT_MACHINE or
            count.op_str != "dword ptr [edi + 0xc]" or
            continuation is None or continuation.mnemonic != "pop" or
            bytes(continuation.bytes) !=
            VITA_SFX_LAZY_PRELOAD_CONTINUATION_MACHINE or
            continuation.op_str != "edi" or
            clear is None or clear.mnemonic != "mov" or
            bytes(clear.bytes) != VITA_SFX_LAZY_PRELOAD_CLEAR_MACHINE or
            clear.op_str != "byte ptr [esi + 0x199], 0" or
            VITA_SFX_LAZY_PRELOAD_CALL_RVA + call.size !=
            VITA_SFX_LAZY_PRELOAD_COUNT_RVA or
            VITA_SFX_LAZY_PRELOAD_COUNT_RVA + count.size !=
            VITA_SFX_LAZY_PRELOAD_CONTINUATION_RVA or
            VITA_SFX_LAZY_PRELOAD_CONTINUATION_RVA + continuation.size !=
            VITA_SFX_LAZY_PRELOAD_CLEAR_RVA or
            pair & em.labels):
        raise RuntimeError(
            "Vita lazy-Preload owner/window/branch/pair changed")
    return True


def vita_steam_time_fallback_for_body(img, root_rva, em, order):
    """Select the exact unavailable-Steam Unix-time fallback.

    ContextInit and the real ISteamUtils path remain untouched.  The seam is
    placed after the original `mov eax,1` and before its unconditional jump,
    so only the already-selected NULL-interface branch can reach target code.
    Full-owner, translated-order, critical-window and operand pins make a
    shifted SDK/context layout fail closed rather than inherit this policy.
    """
    members = frozenset(order)
    if VITA_STEAM_TIME_SEAM_RVA not in members:
        return False
    if root_rva != VITA_STEAM_TIME_ROOT_RVA:
        raise RuntimeError(
            "unexpected Vita Steam-time membership at root %08x" % root_rva)

    owner = img.code_at(
        VITA_STEAM_TIME_ROOT_RVA,
        VITA_STEAM_TIME_END_RVA - VITA_STEAM_TIME_ROOT_RVA)
    window = img.code_at(
        VITA_STEAM_TIME_FALLBACK_WINDOW_RVA,
        VITA_STEAM_TIME_FALLBACK_WINDOW_END_RVA -
        VITA_STEAM_TIME_FALLBACK_WINDOW_RVA)
    decoded = tuple(T.CS.disasm(owner, VITA_STEAM_TIME_ROOT_RVA))
    by_rva = {ins.address: ins for ins in decoded}
    order_sha256 = hashlib.sha256(b"".join(
        site.to_bytes(4, "little") for site in order)).hexdigest()

    context_load = by_rva.get(0x004B3594)
    descriptor = by_rva.get(0x004B359A)
    context_call = by_rva.get(0x004B359F)
    utils_test = by_rva.get(VITA_STEAM_TIME_FALLBACK_WINDOW_RVA)
    real_branch = by_rva.get(0x004B35A8)
    fallback = by_rva.get(VITA_STEAM_TIME_FALLBACK_MOV_RVA)
    seam = by_rva.get(VITA_STEAM_TIME_SEAM_RVA)
    real_utils = by_rva.get(0x004B35C0)
    final_ret = by_rva.get(VITA_STEAM_TIME_LAST_RVA)

    if (hashlib.sha256(owner).hexdigest() !=
            VITA_STEAM_TIME_BODY_SHA256 or
            len(order) != VITA_STEAM_TIME_INSNS or not order or
            order[0] != VITA_STEAM_TIME_ROOT_RVA or
            order[-1] != VITA_STEAM_TIME_LAST_RVA or
            order_sha256 != VITA_STEAM_TIME_ORDER_SHA256 or
            len(decoded) != VITA_STEAM_TIME_INSNS or
            sum(ins.size for ins in decoded) != len(owner) or
            window != VITA_STEAM_TIME_FALLBACK_WINDOW_MACHINE or
            context_load is None or context_load.mnemonic != "mov" or
            context_load.op_str != "esi, dword ptr [0x%08x]" %
            img.va(VITA_STEAM_TIME_CONTEXT_INIT_IAT_RVA) or
            descriptor is None or descriptor.mnemonic != "push" or
            descriptor.op_str != "0x%x" %
            img.va(VITA_STEAM_TIME_CONTEXT_DESCRIPTOR_RVA) or
            context_call is None or context_call.mnemonic != "call" or
            context_call.op_str != "esi" or
            utils_test is None or utils_test.mnemonic != "cmp" or
            utils_test.op_str != "dword ptr [eax + 0xc], 0" or
            real_branch is None or real_branch.mnemonic != "jne" or
            real_branch.op_str != "0x%x" % VITA_STEAM_TIME_REAL_PATH_RVA or
            fallback is None or fallback.mnemonic != "mov" or
            bytes(fallback.bytes) != bytes.fromhex("b801000000") or
            fallback.op_str != "eax, 1" or
            seam is None or seam.mnemonic != "jmp" or
            seam.op_str != "0x%x" % VITA_STEAM_TIME_CONTINUATION_RVA or
            real_utils is None or real_utils.mnemonic != "call" or
            real_utils.op_str != "dword ptr [eax + 0xc]" or
            final_ret is None or final_ret.mnemonic != "ret" or
            final_ret.op_str != "4" or
            VITA_STEAM_TIME_CONTINUATION_RVA not in em.labels):
        raise RuntimeError("Vita Steam-time owner/context/fallback changed")
    return True


def _vita_original_effects_profile_file_sha256(path):
    digest = hashlib.sha256()
    with open(path, "rb") as stream:
        for chunk in iter(lambda: stream.read(1024 * 1024), b""):
            digest.update(chunk)
    return digest.hexdigest()


def vita_original_effects_profile_for_body(
        img, root_rva, em, insns, order, body):
    """Select the exact OptionsConfig post-load seam for Vita effects."""
    members = frozenset(order)
    if VITA_ORIGINAL_EFFECTS_PROFILE_SITE_RVA not in members:
        return False
    if root_rva != VITA_ORIGINAL_EFFECTS_PROFILE_ROOT_RVA:
        raise RuntimeError(
            "unexpected original-Vita effects membership at root %08x" %
            root_rva)
    if (img.base != DEFAULT_BASE or
            os.path.getsize(img.path) !=
            VITA_ORIGINAL_EFFECTS_PROFILE_PE_SIZE or
            _vita_original_effects_profile_file_sha256(img.path) !=
            VITA_ORIGINAL_EFFECTS_PROFILE_PE_SHA256):
        raise RuntimeError("original-Vita effects input PE identity changed")

    owner = img.code_at(
        VITA_ORIGINAL_EFFECTS_PROFILE_ROOT_RVA,
        VITA_ORIGINAL_EFFECTS_PROFILE_END_RVA -
        VITA_ORIGINAL_EFFECTS_PROFILE_ROOT_RVA)
    decoded = tuple(T.CS.disasm(
        owner, VITA_ORIGINAL_EFFECTS_PROFILE_ROOT_RVA))
    by_rva = {ins.address: ins for ins in decoded}
    emitted_by_rva = {
        ins.address: legacy_statements(statements) for ins, statements in body
    }
    site = insns.get(VITA_ORIGINAL_EFFECTS_PROFILE_SITE_RVA)
    default_site = insns.get(VITA_ORIGINAL_EFFECTS_PROFILE_DEFAULT_SITE_RVA)
    early_exit = by_rva.get(VITA_ORIGINAL_EFFECTS_PROFILE_EARLY_EXIT_RVA)
    stores = {
        VITA_ORIGINAL_EFFECTS_PROFILE_CAUSTICS_OFFSET: by_rva.get(0x0047FD93),
        VITA_ORIGINAL_EFFECTS_PROFILE_SHOCKWAVE_OFFSET: by_rva.get(0x0047FDA5),
        VITA_ORIGINAL_EFFECTS_PROFILE_FILTER_OFFSET: by_rva.get(0x0047FDC9),
        VITA_ORIGINAL_EFFECTS_PROFILE_WATER_OFFSET: by_rva.get(0x0047FE08),
        VITA_ORIGINAL_EFFECTS_PROFILE_WATER_LATCH_OFFSET:
            by_rva.get(0x0047FE31),
        VITA_ORIGINAL_EFFECTS_PROFILE_COLOR_MODIFIER_OFFSET:
            by_rva.get(0x0047FE25),
    }
    store_operands = {
        offset: "byte ptr [ebx + 0x%x], al" % offset
        for offset in VITA_ORIGINAL_EFFECTS_PROFILE_FIELDS
    }
    if (hashlib.sha256(owner).hexdigest() !=
            VITA_ORIGINAL_EFFECTS_PROFILE_BODY_SHA256 or
            len(order) != VITA_ORIGINAL_EFFECTS_PROFILE_INSNS or not order or
            order[0] != VITA_ORIGINAL_EFFECTS_PROFILE_ROOT_RVA or
            order[-1] != VITA_ORIGINAL_EFFECTS_PROFILE_LAST_RVA or
            max(order) != VITA_ORIGINAL_EFFECTS_PROFILE_LAST_RVA or
            rva_sequence_sha256(order) !=
            VITA_ORIGINAL_EFFECTS_PROFILE_ORDER_SHA256 or
            len(decoded) != VITA_ORIGINAL_EFFECTS_PROFILE_INSNS or
            sum(ins.size for ins in decoded) != len(owner) or
            site is None or site.mnemonic != "mov" or
            site.op_str != store_operands[
                VITA_ORIGINAL_EFFECTS_PROFILE_WATER_LATCH_OFFSET] or
            bytes(site.bytes) != VITA_ORIGINAL_EFFECTS_PROFILE_SITE_MACHINE or
            emitted_by_rva.get(VITA_ORIGINAL_EFFECTS_PROFILE_SITE_RVA) !=
            (VITA_ORIGINAL_EFFECTS_PROFILE_SITE_STATEMENT,) or
            default_site is None or default_site.mnemonic != "mov" or
            default_site.op_str != "word ptr [ebx + 0x84], 0x101" or
            bytes(default_site.bytes) !=
            VITA_ORIGINAL_EFFECTS_PROFILE_DEFAULT_SITE_MACHINE or
            emitted_by_rva.get(
                VITA_ORIGINAL_EFFECTS_PROFILE_DEFAULT_SITE_RVA) !=
            (VITA_ORIGINAL_EFFECTS_PROFILE_DEFAULT_SITE_STATEMENT,) or
            early_exit is None or early_exit.mnemonic != "je" or
            bytes(early_exit.bytes[:2]) !=
            VITA_ORIGINAL_EFFECTS_PROFILE_EARLY_EXIT_MACHINE or
            int(early_exit.op_str, 16) !=
            VITA_ORIGINAL_EFFECTS_PROFILE_EARLY_EXIT_TARGET_RVA or
            hashlib.sha256(img.code_at(
                VITA_ORIGINAL_EFFECTS_PROFILE_WINDOW_RVA,
                VITA_ORIGINAL_EFFECTS_PROFILE_WINDOW_END_RVA -
                VITA_ORIGINAL_EFFECTS_PROFILE_WINDOW_RVA)).hexdigest() !=
            VITA_ORIGINAL_EFFECTS_PROFILE_WINDOW_SHA256 or
            any(store is None or store.mnemonic != "mov" or
                store.op_str != store_operands[offset]
                for offset, store in stores.items()) or
            any(img.code_at(rva, len(value)) != value
                for rva, value in
                VITA_ORIGINAL_EFFECTS_PROFILE_STRING_RVAS.values())):
        raise RuntimeError(
            "original-Vita OptionsConfig owner/seam/fields changed")
    return True


def render_vita_original_effects_profile():
    """Render register-neutral target values at both OptionsConfig seams.

    Emitted after the last default store (0x47fc22, reached on every path)
    and after the last GetBool store (0x47fe31, reached only when
    resources/config.ini exists).  Identical stores at both seams keep the
    result independent of whether the file is present.
    """
    return (
        "#if defined(__vita__) && "
        "defined(ISAAC_VITA_ORIGINAL_EFFECTS_PROFILE)",
        "    /* PCSB00676 effects plus no Repentance water/ColorModifier paths. */",
        "    st8((uint32_t)(c->ebx + 0x7fU), (uint8_t)(0U));",
        "    st8((uint32_t)(c->ebx + 0x7eU), (uint8_t)(0U));",
        "    st8((uint32_t)(c->ebx + 0x80U), (uint8_t)(0U));",
        "    st8((uint32_t)(c->ebx + 0x83U), (uint8_t)(0U));",
        "    st8((uint32_t)(c->ebx + 0x84U), (uint8_t)(0U));",
        "    st8((uint32_t)(c->ebx + 0x85U), (uint8_t)(0U));",
        "#endif",
    )


def vita_original_effects_profile_host_oracle(options):
    """Pure host model used to prove that only the six target bytes move."""
    result = bytearray(options)
    if len(result) <= max(VITA_ORIGINAL_EFFECTS_PROFILE_FIELDS):
        raise ValueError("OptionsConfig host image is too small")
    for offset in VITA_ORIGINAL_EFFECTS_PROFILE_FIELDS:
        result[offset] = 0
    return bytes(result)


def vita_world_seam_diag_for_body(
        img, root_rva, em, insns, order, body, emit_base=None):
    """Select and authenticate the four Game::Render diagnostic joins."""
    if emit_base is None:
        emit_base = img.base
    members = frozenset(order)
    reached = members & VITA_WORLD_SEAM_DIAG_SITES
    if not reached:
        return False
    if (root_rva != VITA_WORLD_SEAM_DIAG_ROOT_RVA or
            reached != VITA_WORLD_SEAM_DIAG_SITES):
        raise RuntimeError(
            "unexpected or partial world-seam membership at root %08x" %
            root_rva)
    if (img.base != DEFAULT_BASE or
            os.path.getsize(img.path) != VITA_WORLD_SEAM_DIAG_PE_SIZE or
            _vita_original_effects_profile_file_sha256(img.path) !=
            VITA_WORLD_SEAM_DIAG_PE_SHA256):
        raise RuntimeError("world-seam diagnostic input PE identity changed")

    owner = img.code_at(
        VITA_WORLD_SEAM_DIAG_ROOT_RVA,
        VITA_WORLD_SEAM_DIAG_END_RVA - VITA_WORLD_SEAM_DIAG_ROOT_RVA)
    decoded = tuple(T.CS.disasm(owner, VITA_WORLD_SEAM_DIAG_ROOT_RVA))
    by_rva = {instruction.address: instruction for instruction in decoded}
    emitted_by_rva = {
        instruction.address: legacy_statements(statements)
        for instruction, statements in body
    }

    def instruction(rva, mnemonic, operand, machine=None):
        value = by_rva.get(rva)
        return (value is not None and value.mnemonic == mnemonic and
                value.op_str == operand and
                (machine is None or bytes(value.bytes) == machine))

    def window(spec):
        start, end, expected = spec
        return hashlib.sha256(img.code_at(start, end - start)).hexdigest() == \
            expected

    lua_insns, lua_order, _lua_indirect = T.decode(
        img, VITA_WORLD_SEAM_DIAG_LUA_ROOT_RVA)
    lua_helper_insns, lua_helper_order, _lua_helper_indirect = T.decode(
        img, VITA_WORLD_SEAM_DIAG_LUA_CALL_HELPER_RVA)
    lua_calls = tuple(sorted((
        instruction for instruction in lua_insns.values()
        if instruction.address in lua_order and instruction.mnemonic == "call"
    ), key=lambda instruction: instruction.address))
    helper_calls = tuple(sorted((
        instruction for instruction in lua_helper_insns.values()
        if instruction.address in lua_helper_order and
        instruction.mnemonic == "call"
    ), key=lambda instruction: instruction.address))
    helper_iat_operands = frozenset(
        "dword ptr [0x%08x]" % img.va(rva)
        for rva in VITA_WORLD_SEAM_DIAG_LUA_IAT_RVAS)
    helper_observed_iats = frozenset(
        instruction.op_str for instruction in helper_calls
        if instruction.op_str.startswith("dword ptr ["))
    # lua_pushinteger is loaded once and called twice through ESI, so its IAT
    # slot is authenticated by the exact helper body rather than two direct
    # call operands.
    helper_direct_iats = helper_iat_operands - {
        "dword ptr [0x%08x]" % img.va(0x00606240),
        "dword ptr [0x%08x]" % img.va(0x00606248),
    }
    if (hashlib.sha256(owner).hexdigest() !=
            VITA_WORLD_SEAM_DIAG_BODY_SHA256 or
            len(order) != VITA_WORLD_SEAM_DIAG_INSNS or not order or
            order[0] != VITA_WORLD_SEAM_DIAG_ROOT_RVA or
            order[-1] != VITA_WORLD_SEAM_DIAG_LAST_RVA or
            max(order) != VITA_WORLD_SEAM_DIAG_LAST_RVA or
            rva_sequence_sha256(order) !=
            VITA_WORLD_SEAM_DIAG_ORDER_SHA256 or
            len(decoded) != VITA_WORLD_SEAM_DIAG_INSNS or
            sum(instruction.size for instruction in decoded) != len(owner) or
            any(not window(spec) for spec in (
                VITA_WORLD_SEAM_DIAG_PRE_ROOM_WINDOW,
                VITA_WORLD_SEAM_DIAG_ROOM_WINDOW,
                VITA_WORLD_SEAM_DIAG_LATE_WINDOW,
                VITA_WORLD_SEAM_DIAG_HUD_WINDOW)) or
            not instruction(0x002CE77E, "mov", "edi, ecx", b"\x8b\xf9") or
            not instruction(0x002CEBCB, "mov",
                            "edi, dword ptr [esp + 0x48]") or
            not instruction(VITA_WORLD_SEAM_DIAG_BEGIN_SITE_RVA, "mov",
                            "ecx, 0x%x" % img.va(0x007C7A30)) or
            not instruction(0x002CEC29, "call", "0x564f50") or
            not instruction(0x002CEC6E, "call", "0x3cad40") or
            not instruction(0x002CEC77, "call", "0x3ece40") or
            not instruction(VITA_WORLD_SEAM_DIAG_ROOM_END_SITE_RVA, "call",
                            "0x3ffe10", b"\xe8\x8f\x11\x13\x00") or
            not instruction(VITA_WORLD_SEAM_DIAG_OVERLAY_DRAW_RVA, "call",
                            "dword ptr [eax + 0xc]", b"\xff\x50\x0c") or
            not instruction(0x002CED91, "je", "0x2cef88") or
            not instruction(VITA_WORLD_SEAM_DIAG_PRE_HUD_SITE_RVA, "call",
                            "0x20720", b"\xe8\x8d\x17\xd5\xff") or
            not instruction(VITA_WORLD_SEAM_DIAG_HUD_CALL_RVA, "call",
                            "0x504610", b"\xe8\x72\x56\x23\x00") or
            emitted_by_rva.get(VITA_WORLD_SEAM_DIAG_BEGIN_SITE_RVA) !=
            ("c->ecx = (uint32_t)(0x%08xU);" %
             ((emit_base + 0x007C7A30) & 0xFFFFFFFF),) or
            emitted_by_rva.get(VITA_WORLD_SEAM_DIAG_ROOM_END_SITE_RVA) !=
            ("gpush_generated(c, 0x2cec81U); "
             "GUEST_STACK_CALLSITE_BARRIER(); sub_003ffe10(c);",) or
            emitted_by_rva.get(VITA_WORLD_SEAM_DIAG_PRE_HUD_SITE_RVA) !=
            ("gpush_generated(c, 0x2cef93U); "
             "GUEST_STACK_CALLSITE_BARRIER(); sub_00020720(c);",) or
            len(lua_order) != VITA_WORLD_SEAM_DIAG_LUA_INSNS or
            lua_order[-1] != VITA_WORLD_SEAM_DIAG_LUA_LAST_RVA or
            rva_sequence_sha256(lua_order) !=
            VITA_WORLD_SEAM_DIAG_LUA_ORDER_SHA256 or
            hashlib.sha256(img.code_at(
                VITA_WORLD_SEAM_DIAG_LUA_ROOT_RVA,
                VITA_WORLD_SEAM_DIAG_LUA_END_RVA -
                VITA_WORLD_SEAM_DIAG_LUA_ROOT_RVA)).hexdigest() !=
            VITA_WORLD_SEAM_DIAG_LUA_BODY_SHA256 or
            len(lua_calls) != 2 or
            lua_calls[0].address != 0x003FFE6B or
            lua_calls[0].op_str != "0x40eef0" or
            lua_calls[1].address != VITA_WORLD_SEAM_DIAG_LUA_UNREF_CALL_RVA or
            lua_calls[1].op_str != "dword ptr [0x%08x]" %
            img.va(VITA_WORLD_SEAM_DIAG_LUA_UNREF_IAT_RVA) or
            len(lua_helper_order) !=
            VITA_WORLD_SEAM_DIAG_LUA_CALL_HELPER_INSNS or
            lua_helper_order[-1] !=
            VITA_WORLD_SEAM_DIAG_LUA_CALL_HELPER_LAST_RVA or
            rva_sequence_sha256(lua_helper_order) !=
            VITA_WORLD_SEAM_DIAG_LUA_CALL_HELPER_ORDER_SHA256 or
            hashlib.sha256(img.code_at(
                VITA_WORLD_SEAM_DIAG_LUA_CALL_HELPER_RVA,
                VITA_WORLD_SEAM_DIAG_LUA_CALL_HELPER_END_RVA -
                VITA_WORLD_SEAM_DIAG_LUA_CALL_HELPER_RVA)).hexdigest() !=
            VITA_WORLD_SEAM_DIAG_LUA_CALL_HELPER_BODY_SHA256 or
            helper_observed_iats != helper_direct_iats or
            lua_helper_insns.get(0x0040EF15) is None or
            lua_helper_insns[0x0040EF15].op_str != "esi, dword ptr [0x%08x]" %
            img.va(0x00606240)):
        raise RuntimeError(
            "world-seam Game/Room/Lua/overlay/HUD proof changed")
    return True


def render_vita_world_seam_diag_before(site):
    """Emit diagnostic calls which must run before the frozen instruction."""
    if site == VITA_WORLD_SEAM_DIAG_BEGIN_SITE_RVA:
        return (
            "#if defined(__vita__) && defined(ISAAC_VITA_WORLD_SEAM_DIAG)",
            "    (void)0; /* A generated label must precede a C statement. */",
            "    extern void kage_vita_world_seam_diag_begin(uint32_t, uint32_t);",
            "    /* Game embeds Level at +0: stage/type are the first words. */",
            "    kage_vita_world_seam_diag_begin(",
            "        ld32(c->edi), ld32((uint32_t)(c->edi + 4U)));",
            "#endif",
        )
    if site == VITA_WORLD_SEAM_DIAG_ROOM_END_SITE_RVA:
        return (
            "#if defined(__vita__) && defined(ISAAC_VITA_WORLD_SEAM_DIAG)",
            "    (void)0; /* A generated label must precede a C statement. */",
            "    extern void kage_vita_world_seam_diag_post_room(void);",
            "    kage_vita_world_seam_diag_post_room();",
            "#endif",
        )
    return ()


def render_vita_world_seam_diag_after(site):
    """Emit diagnostic calls which must run after the frozen instruction."""
    if site == VITA_WORLD_SEAM_DIAG_ROOM_END_SITE_RVA:
        return (
            "#if defined(__vita__) && defined(ISAAC_VITA_WORLD_SEAM_DIAG)",
            "    (void)0; /* A generated label must precede a C statement. */",
            "    extern void kage_vita_world_seam_diag_post_lua(void);",
            "    kage_vita_world_seam_diag_post_lua();",
            "#endif",
        )
    if site == VITA_WORLD_SEAM_DIAG_PRE_HUD_SITE_RVA:
        return (
            "#if defined(__vita__) && defined(ISAAC_VITA_WORLD_SEAM_DIAG)",
            "    (void)0; /* A generated label must precede a C statement. */",
            "    extern void kage_vita_world_seam_diag_pre_hud(void);",
            "    kage_vita_world_seam_diag_pre_hud();",
            "#endif",
        )
    return ()


def _vita_pill_bloom_bypass_file_sha256(path):
    digest = hashlib.sha256()
    with open(path, "rb") as stream:
        for chunk in iter(lambda: stream.read(1024 * 1024), b""):
            digest.update(chunk)
    return digest.hexdigest()


def vita_pill_bloom_bypass_for_body(
        img, root_rva, em, insns, order, body):
    """Select the exact paired pill-Bloom capture/composite seams."""
    members = frozenset(order)
    reached = members & VITA_PILL_BLOOM_BYPASS_SITES
    if not reached:
        return False
    if (root_rva != VITA_PILL_BLOOM_BYPASS_ROOT_RVA or
            reached != VITA_PILL_BLOOM_BYPASS_SITES):
        raise RuntimeError(
            "unexpected or partial pill-Bloom membership at root %08x" %
            root_rva)
    if (img.base != DEFAULT_BASE or
            os.path.getsize(img.path) != VITA_PILL_BLOOM_BYPASS_PE_SIZE or
            _vita_pill_bloom_bypass_file_sha256(img.path) !=
            VITA_PILL_BLOOM_BYPASS_PE_SHA256):
        raise RuntimeError("pill-Bloom bypass input PE identity changed")

    owner = img.code_at(
        VITA_PILL_BLOOM_BYPASS_ROOT_RVA,
        VITA_PILL_BLOOM_BYPASS_END_RVA -
        VITA_PILL_BLOOM_BYPASS_ROOT_RVA)
    decoded = tuple(T.CS.disasm(owner, VITA_PILL_BLOOM_BYPASS_ROOT_RVA))
    by_rva = {ins.address: ins for ins in decoded}
    emitted_by_rva = {
        ins.address: legacy_statements(statements) for ins, statements in body
    }
    capture = insns.get(VITA_PILL_BLOOM_BYPASS_CAPTURE_SITE_RVA)
    composite = insns.get(VITA_PILL_BLOOM_BYPASS_COMPOSITE_SITE_RVA)
    capture_timer = by_rva.get(VITA_PILL_BLOOM_BYPASS_CAPTURE_WINDOW_RVA)
    capture_option = by_rva.get(0x002CEA83)
    capture_activate = by_rva.get(0x002CEAA8)
    composite_timer = by_rva.get(VITA_PILL_BLOOM_BYPASS_COMPOSITE_WINDOW_RVA)
    composite_option = by_rva.get(0x002CF35A)
    composite_pop = by_rva.get(0x002CF371)

    def window_sha256(start, end):
        return hashlib.sha256(img.code_at(start, end - start)).hexdigest()

    if (hashlib.sha256(owner).hexdigest() !=
            VITA_PILL_BLOOM_BYPASS_BODY_SHA256 or
            len(order) != VITA_PILL_BLOOM_BYPASS_INSNS or not order or
            order[0] != VITA_PILL_BLOOM_BYPASS_ROOT_RVA or
            order[-1] != VITA_PILL_BLOOM_BYPASS_LAST_RVA or
            max(order) != VITA_PILL_BLOOM_BYPASS_LAST_RVA or
            rva_sequence_sha256(order) !=
            VITA_PILL_BLOOM_BYPASS_ORDER_SHA256 or
            len(decoded) != VITA_PILL_BLOOM_BYPASS_INSNS or
            sum(ins.size for ins in decoded) != len(owner) or
            capture is None or capture.mnemonic != "je" or
            capture.op_str != "0x%x" %
            VITA_PILL_BLOOM_BYPASS_CAPTURE_WINDOW_END_RVA or
            bytes(capture.bytes) != VITA_PILL_BLOOM_BYPASS_CAPTURE_MACHINE or
            not jcc_statement_matches(
                emitted_by_rva.get(
                    VITA_PILL_BLOOM_BYPASS_CAPTURE_SITE_RVA, ()),
                VITA_PILL_BLOOM_BYPASS_CAPTURE_WINDOW_END_RVA) or
            composite is None or composite.mnemonic != "je" or
            composite.op_str != "0x%x" %
            VITA_PILL_BLOOM_BYPASS_COMPOSITE_WINDOW_END_RVA or
            bytes(composite.bytes) !=
            VITA_PILL_BLOOM_BYPASS_COMPOSITE_MACHINE or
            not jcc_statement_matches(
                emitted_by_rva.get(
                    VITA_PILL_BLOOM_BYPASS_COMPOSITE_SITE_RVA, ()),
                VITA_PILL_BLOOM_BYPASS_COMPOSITE_WINDOW_END_RVA) or
            capture_timer is None or capture_timer.mnemonic != "cmp" or
            capture_timer.op_str != "dword ptr [edi + 0x1c3148], 0" or
            capture_option is None or capture_option.mnemonic != "cmp" or
            capture_option.op_str != "byte ptr [eax + 0x29e7a], 0" or
            capture_activate is None or capture_activate.mnemonic != "call" or
            capture_activate.op_str != "0x564db0" or
            composite_timer is None or composite_timer.mnemonic != "cmp" or
            composite_timer.op_str != "dword ptr [edi + 0x1c3148], 0" or
            composite_option is None or composite_option.mnemonic != "cmp" or
            composite_option.op_str != "byte ptr [eax + 0x29e7a], 0" or
            composite_pop is None or composite_pop.mnemonic != "call" or
            composite_pop.op_str != "0x25b650" or
            window_sha256(
                VITA_PILL_BLOOM_BYPASS_TRIGGER_WINDOW_RVA,
                VITA_PILL_BLOOM_BYPASS_TRIGGER_WINDOW_END_RVA) !=
            VITA_PILL_BLOOM_BYPASS_TRIGGER_WINDOW_SHA256 or
            window_sha256(
                VITA_PILL_BLOOM_BYPASS_CREATE_WINDOW_RVA,
                VITA_PILL_BLOOM_BYPASS_CREATE_WINDOW_END_RVA) !=
            VITA_PILL_BLOOM_BYPASS_CREATE_WINDOW_SHA256 or
            window_sha256(
                VITA_PILL_BLOOM_BYPASS_CAPTURE_WINDOW_RVA,
                VITA_PILL_BLOOM_BYPASS_CAPTURE_WINDOW_END_RVA) !=
            VITA_PILL_BLOOM_BYPASS_CAPTURE_WINDOW_SHA256 or
            window_sha256(
                VITA_PILL_BLOOM_BYPASS_COMPOSITE_WINDOW_RVA,
                VITA_PILL_BLOOM_BYPASS_COMPOSITE_WINDOW_END_RVA) !=
            VITA_PILL_BLOOM_BYPASS_COMPOSITE_WINDOW_SHA256 or
            img.code_at(
                VITA_PILL_BLOOM_BYPASS_STRING_RVA,
                len(VITA_PILL_BLOOM_BYPASS_STRING)) !=
            VITA_PILL_BLOOM_BYPASS_STRING or
            VITA_PILL_BLOOM_BYPASS_CAPTURE_WINDOW_END_RVA not in em.labels or
            VITA_PILL_BLOOM_BYPASS_COMPOSITE_WINDOW_END_RVA not in em.labels):
        raise RuntimeError(
            "pill-Bloom trigger/surface/capture/composite proof changed")
    return True


def render_vita_pill_bloom_bypass_local():
    """Render the function-local token which owns capture/pop balance."""
    return (
        "#if defined(__vita__) && "
        "defined(ISAAC_VITA_PILL_BLOOM_BYPASS)",
        "    uint32_t _guest_vita_pill_bloom_bypassed = 0U;",
        "#if defined(ISAAC_VITA_PHASE_RECEIPTS)",
        "    extern void "
        "kage_vita_phase_profile_note_pill_bloom_capture_skip(void);",
        "    extern void "
        "kage_vita_phase_profile_note_pill_bloom_composite_skip(void);",
        "#endif",
        "#endif",
    )


def render_vita_pill_bloom_bypass_site(site):
    """Render one half of the paired selective pill-Bloom bypass."""
    prefix = (
        "#if defined(__vita__) && "
        "defined(ISAAC_VITA_PILL_BLOOM_BYPASS)",
    )
    if site == VITA_PILL_BLOOM_BYPASS_CAPTURE_SITE_RVA:
        return prefix + (
            "    /* Performance mode: omit this shared transient-Bloom capture. */",
            "    _guest_vita_pill_bloom_bypassed = 1U;",
            "#if defined(ISAAC_VITA_PHASE_RECEIPTS)",
            "    kage_vita_phase_profile_note_pill_bloom_capture_skip();",
            "#endif",
            "    goto L_002ceaad;",
            "#endif",
        )
    if site == VITA_PILL_BLOOM_BYPASS_COMPOSITE_SITE_RVA:
        return prefix + (
            "    if (_guest_vita_pill_bloom_bypassed != 0U) {",
            "#if defined(ISAAC_VITA_PHASE_RECEIPTS)",
            "        kage_vita_phase_profile_note_pill_bloom_composite_skip();",
            "#endif",
            "        goto L_002cf5a1;",
            "    }",
            "#endif",
        )
    raise ValueError("unknown pill-Bloom bypass site %08x" % site)


def vita_pill_bloom_bypass_host_oracle(timer, bloom_option, enabled):
    """Model target-stack ownership and the two aggregate skip counters."""
    active = timer > 0 and bool(bloom_option)
    if not active:
        return {
            "capture_pushes": 0, "composite_pops": 0,
            "capture_skips": 0, "composite_skips": 0,
        }
    if not enabled:
        return {
            "capture_pushes": 1, "composite_pops": 1,
            "capture_skips": 0, "composite_skips": 0,
        }
    return {
        "capture_pushes": 0, "composite_pops": 0,
        "capture_skips": 1, "composite_skips": 1,
    }


def _vita_transient_bloom_half_res_lifecycle_proof(img):
    """Pin the existing virtual/viewport/backing/composite coordinate split."""
    for start, end, expected in (
            VITA_TRANSIENT_BLOOM_HALF_RES_ACTIVATE_WINDOW,
            VITA_TRANSIENT_BLOOM_HALF_RES_PROJECTION_WINDOW,
            VITA_TRANSIENT_BLOOM_HALF_RES_SURFACE_WINDOW,
            VITA_TRANSIENT_BLOOM_HALF_RES_UV_WINDOW,
            VITA_TRANSIENT_BLOOM_HALF_RES_DRAW_DISPATCH_WINDOW,
            VITA_TRANSIENT_BLOOM_HALF_RES_QUAD_WINDOW,
            VITA_TRANSIENT_BLOOM_HALF_RES_COMPOSITE_WINDOW,
            VITA_TRANSIENT_BLOOM_HALF_RES_GLOBALS_WINDOW,
            VITA_TRANSIENT_BLOOM_HALF_RES_RESIZE_WINDOW,
            VITA_TRANSIENT_BLOOM_HALF_RES_RECREATE_WINDOW):
        if hashlib.sha256(img.code_at(start, end - start)).hexdigest() != expected:
            raise RuntimeError(
                "transient-Bloom half-res lifecycle changed at %08x" % start)

    def instruction(rva, size):
        decoded = tuple(T.CS.disasm(img.code_at(rva, size), rva))
        return decoded[0] if decoded else None

    expected = {
        0x00001190: ("movss", "xmm0, dword ptr [0x307aa92c]"),
        0x00001198: ("movss", "dword ptr [0x307fec08], xmm0"),
        0x000011B0: ("movss", "xmm0, dword ptr [0x307aa930]"),
        0x000011B8: ("movss", "dword ptr [0x307fec68], xmm0"),
        0x000011DD: ("mov", "dword ptr [0x307fec6c], eax"),
        0x000011FD: ("mov", "dword ptr [0x307fec0c], eax"),
        0x002CEA9B: ("push", "1"),
        0x002CEA9D: ("push", "dword ptr [0x307fecbc]"),
        0x00564DB4: ("mov", "al, byte ptr [ebp + 0xc]"),
        0x00564DC4: ("mov", "byte ptr [ebx + 0x1c], al"),
        0x00564E09: ("call", "dword ptr [edx + 0x28]"),
        0x00564E12: ("call", "dword ptr [edx + 0x2c]"),
        0x00564E28: ("call", "dword ptr [0x307c1e84]"),
        0x00564E30: ("call", "0x565240"),
        0x0056525A: ("cmp", "byte ptr [esi + 0x1c], 0"),
        0x0056525E: ("jne", "0x5652b0"),
        0x005652B0: ("movss", "xmm1, dword ptr [0x307aa92c]"),
        0x005652B8: ("movss", "xmm4, dword ptr [0x307aa930]"),
        0x0055EBD6: ("cmp", "dword ptr [edi + 0x20], 1"),
        0x0055EBE8: ("call", "dword ptr [eax + 0x28]"),
        0x0055EC18: ("call", "dword ptr [eax + 0x2c]"),
        0x0055F622: ("call", "dword ptr [edx + 8]"),
        0x0055F675: ("call", "0x55f990"),
        0x0055FA3C: ("movss", "xmm0, dword ptr [0x307aa92c]"),
        0x0055FA4A: ("movss", "xmm0, dword ptr [0x307aa930]"),
        0x005B5E8B: ("mov", "dword ptr [ebx], 0x307682ac"),
        0x005B5E91: ("mov", "dword ptr [ebx + 0x80], ecx"),
        0x005B5E97: ("mov", "dword ptr [ebx + 0x84], edx"),
        0x005B5E9D: ("mov", "dword ptr [ebx + 0x88], ecx"),
        0x005B5EA3: ("mov", "dword ptr [ebx + 0x8c], edx"),
        0x005B5ECA: ("cmp", "byte ptr [0x307fd66a], 0"),
        0x005B60D1: ("movss", "dword ptr [ebx + 8], xmm1"),
        0x005B6107: ("movss", "dword ptr [ebx + 0xc], xmm1"),
        0x00032ED0: ("mov", "eax, dword ptr [ecx + 0x80]"),
        0x005A1A70: ("mov", "eax, dword ptr [ecx + 0x84]"),
        0x005A1A80: ("mov", "eax, dword ptr [ecx + 0x88]"),
        0x005B6270: ("mov", "eax, dword ptr [ecx + 0x8c]"),
        0x002CF3A8: ("push", "0x307fec68"),
        0x002CF3B6: ("push", "0x307fec08"),
        0x002CF434: ("call", "0x55e590"),
        0x002CF447: ("mov", "ecx, dword ptr [0x307fecbc]"),
        0x002CF467: ("mov", "eax, dword ptr [eax + 0xc]"),
        0x002CF478: ("mov", "esi, dword ptr [0x307fecbc]"),
        0x002CF482: ("mov", "edx, dword ptr [edx + 0x30]"),
        0x002CF49F: ("mov", "eax, dword ptr [eax + 0x34]"),
        0x004AF4AE: ("call", "0x560f20"),
        0x004AF591: ("mov", "eax, 0x1e0"),
        0x004AF596: ("mov", "ecx, 0x10e"),
        0x004AF5E5: ("mov", "dword ptr [0x307fec6c], eax"),
        0x004AF5EF: ("movss", "dword ptr [0x307fec08], xmm0"),
        0x004AF606: ("mov", "dword ptr [0x307fec0c], ebx"),
        0x004AF612: ("movss", "dword ptr [0x307fec68], xmm0"),
        0x004AF68A: ("mov", "byte ptr [eax + 0x1c3154], 1"),
        0x002CE784: ("cmp", "byte ptr [edi + 0x1c3154], 0"),
        0x002CE89C: ("mov", "ecx, 0x307fecbc"),
        0x002CE8D6: ("call", "0x2c7e70"),
    }
    for rva, pair in expected.items():
        decoded = instruction(rva, 8)
        if decoded is None or (decoded.mnemonic, decoded.op_str) != pair:
            raise RuntimeError(
                "transient-Bloom coordinate proof changed at %08x" % rva)
    call_sites = []
    for site in range(img.text_rva, img.text_end - 4):
        if img.mem[site] != 0xE8:
            continue
        displacement = int.from_bytes(
            img.code_at(site + 1, 4), "little", signed=True)
        if ((site + 5 + displacement) & 0xFFFFFFFF) == \
                VITA_TRANSIENT_BLOOM_HALF_RES_CREATE_ROOT_RVA:
            call_sites.append(site)
    if tuple(call_sites) != VITA_TRANSIENT_BLOOM_HALF_RES_CREATE_CALL_SITES:
        raise RuntimeError(
            "transient-Bloom creation caller census changed")
    expected_surface_vtable = b"".join(
        (img.base + rva).to_bytes(4, "little")
        for rva in (0x0055F300, 0x0055F320, 0x0055F630, 0x0055F610)
    )
    if (img.code_at(0x007682AC, 16) != expected_surface_vtable or
            img.code_at(0x007AA92C, 8) != bytes.fromhex(
            "0000f04300008743") or
            img.code_at(
                VITA_PILL_BLOOM_BYPASS_STRING_RVA,
                len(VITA_PILL_BLOOM_BYPASS_STRING)) !=
            VITA_PILL_BLOOM_BYPASS_STRING):
        raise RuntimeError("transient-Bloom virtual extent/name changed")


def vita_transient_bloom_half_res_for_body(
        img, root_rva, em, insns, order, body, emit_base=None):
    """Select exact creation and active capture/composite census seams."""
    reached = frozenset(order) & VITA_TRANSIENT_BLOOM_HALF_RES_ALL_SITES
    if not reached:
        return None
    if (img.base != DEFAULT_BASE or
            os.path.getsize(img.path) != VITA_PILL_BLOOM_BYPASS_PE_SIZE or
            _vita_pill_bloom_bypass_file_sha256(img.path) !=
            VITA_PILL_BLOOM_BYPASS_PE_SHA256):
        raise RuntimeError("transient-Bloom half-res input PE identity changed")
    emitted_by_rva = {
        instruction.address: legacy_statements(statements)
        for instruction, statements in body
    }
    if emit_base is None:
        emit_base = img.base

    def relocated_push(global_rva):
        address = (emit_base + global_rva) & 0xffffffff
        displacement = address if address < 0x80000000 else address - 0x100000000
        formatted = (
            "0x%xU" % address
            if displacement >= 0 else
            "(uint32_t)(int32_t)(%d)" % displacement
        )
        return (
            bytes.fromhex("ff35") + address.to_bytes(4, "little"),
            "dword ptr [0x%x]" % address,
            "gpush_generated(c, ld32((uint32_t)(%s))); "
            "GUEST_STACK_CALLSITE_BARRIER();" % formatted,
        )

    if root_rva == VITA_TRANSIENT_BLOOM_HALF_RES_CREATE_ROOT_RVA:
        if reached != VITA_TRANSIENT_BLOOM_HALF_RES_CREATE_SITES:
            raise RuntimeError("partial transient-Bloom creation membership")
        owner = img.code_at(
            root_rva,
            VITA_TRANSIENT_BLOOM_HALF_RES_CREATE_END_RVA - root_rva)
        height = insns.get(VITA_TRANSIENT_BLOOM_HALF_RES_HEIGHT_SITE_RVA)
        width = insns.get(VITA_TRANSIENT_BLOOM_HALF_RES_WIDTH_SITE_RVA)
        height_machine, height_operand, height_statement = relocated_push(
            VITA_TRANSIENT_BLOOM_HALF_RES_HEIGHT_GLOBAL_RVA)
        width_machine, width_operand, width_statement = relocated_push(
            VITA_TRANSIENT_BLOOM_HALF_RES_WIDTH_GLOBAL_RVA)
        if (hashlib.sha256(owner).hexdigest() !=
                VITA_TRANSIENT_BLOOM_HALF_RES_CREATE_BODY_SHA256 or
                len(order) != VITA_TRANSIENT_BLOOM_HALF_RES_CREATE_INSNS or
                not order or order[0] != root_rva or
                order[-1] != VITA_TRANSIENT_BLOOM_HALF_RES_CREATE_LAST_RVA or
                max(order) != VITA_TRANSIENT_BLOOM_HALF_RES_CREATE_LAST_RVA or
                rva_sequence_sha256(order) !=
                VITA_TRANSIENT_BLOOM_HALF_RES_CREATE_ORDER_SHA256 or
                height is None or height.mnemonic != "push" or
                height.op_str != height_operand or
                bytes(height.bytes) != height_machine or
                emitted_by_rva.get(height.address) !=
                (height_statement,) or
                width is None or width.mnemonic != "push" or
                width.op_str != width_operand or
                bytes(width.bytes) != width_machine or
                emitted_by_rva.get(width.address) !=
                (width_statement,)):
            raise RuntimeError("transient-Bloom creation proof changed")
        _vita_transient_bloom_half_res_lifecycle_proof(img)
        return "create"

    if root_rva == VITA_TRANSIENT_BLOOM_HALF_RES_RENDER_ROOT_RVA:
        if reached != VITA_TRANSIENT_BLOOM_HALF_RES_RENDER_SITES:
            raise RuntimeError("partial transient-Bloom render membership")
        # This independently pins the full owner, trigger writers, both guards,
        # target-stack calls and their continuation labels.
        if not vita_pill_bloom_bypass_for_body(
                img, root_rva, em, insns, order, body):
            raise RuntimeError("transient-Bloom render owner was not selected")
        return "render"
    raise RuntimeError(
        "unexpected transient-Bloom half-res owner %08x" % root_rva)


def render_vita_transient_bloom_half_res_create():
    """Leave initial half-scanout Bloom intact; halve its recreation."""
    return (
        "#if defined(__vita__) && "
        "defined(ISAAC_VITA_TRANSIENT_BLOOM_HALF_RES)",
        "#if defined(ISAAC_VITA_PHASE_RECEIPTS)",
        "    extern void kage_vita_phase_profile_note_bloom_half_create(",
        "        uint32_t);",
        "#endif",
        "    uint32_t _guest_vita_bloom_width = ld32((uint32_t)c->esp);",
        "    uint32_t _guest_vita_bloom_height =",
        "        ld32((uint32_t)(c->esp + 4U));",
        "    if (_guest_vita_bloom_width == 480U &&",
        "            _guest_vita_bloom_height == 270U) {",
        "#if defined(ISAAC_VITA_PHASE_RECEIPTS)",
        "        kage_vita_phase_profile_note_bloom_half_create(1U);",
        "#endif",
        "    } else if (_guest_vita_bloom_width == 960U &&",
        "            _guest_vita_bloom_height == 540U) {",
        "        st32((uint32_t)c->esp, _guest_vita_bloom_width / 2U);",
        "        st32((uint32_t)(c->esp + 4U),",
        "             _guest_vita_bloom_height / 2U);",
        "#if defined(ISAAC_VITA_PHASE_RECEIPTS)",
        "        kage_vita_phase_profile_note_bloom_half_create(2U);",
        "#endif",
        "    } else {",
        "#if defined(ISAAC_VITA_PHASE_RECEIPTS)",
        "        kage_vita_phase_profile_note_bloom_half_create(0U);",
        "#endif",
        "    }",
        "#endif",
    )


def render_vita_transient_bloom_half_res_render(site):
    """Record balanced use of the lower-resolution auxiliary surface."""
    if site == VITA_PILL_BLOOM_BYPASS_CAPTURE_SITE_RVA:
        function = "kage_vita_phase_profile_note_bloom_half_capture"
    elif site == VITA_PILL_BLOOM_BYPASS_COMPOSITE_SITE_RVA:
        function = "kage_vita_phase_profile_note_bloom_half_composite"
    else:
        raise ValueError("unknown transient-Bloom half-res site %08x" % site)
    return (
        "#if defined(__vita__) && "
        "defined(ISAAC_VITA_TRANSIENT_BLOOM_HALF_RES) && "
        "defined(ISAAC_VITA_PHASE_RECEIPTS)",
        "    extern void %s(void);" % function,
        "    %s();" % function,
        "#endif",
    )


def vita_transient_bloom_half_res_host_oracle(
        width, height, align8=True, virtual_width=480, virtual_height=270):
    """Model the frozen Surface coordinate and padded-backing lifecycle."""
    initial = (width, height) == (480, 270)
    applied = (width, height) == (960, 540)
    requested_width = width // 2 if applied else width
    requested_height = height // 2 if applied else height
    if align8:
        backing_width = (requested_width + 7) & ~7
        backing_height = (requested_height + 7) & ~7
    else:
        backing_width = 8
        while backing_width < requested_width:
            backing_width *= 2
        backing_height = 8
        while backing_height < requested_height:
            backing_height *= 2
    return {
        "receipt": "initial" if initial else (
            "recreated" if applied else "rejected"),
        "applied": applied,
        "requested": (requested_width, requested_height),
        "backing": (backing_width, backing_height),
        "viewport": (requested_width, requested_height),
        "projection": (virtual_width, virtual_height),
        "composite": (virtual_width, virtual_height),
        "uv_extent": (
            requested_width / backing_width,
            requested_height / backing_height,
        ),
        "texel_step": (1 / backing_width, 1 / backing_height),
    }


def vita_laser_profile_for_body(
        img, root_rva, em, insns, order, body,
        extra_entries, indirect_edges):
    """Select the exact active Entity_Laser render/profile seam."""
    members = frozenset(order)
    reached = members & VITA_LASER_PROFILE_SITES
    reached_epilogues = members & VITA_LASER_PROFILE_EPILOGUE_SITES
    if not reached:
        return None
    spec = VITA_LASER_PROFILE_OWNERS.get(root_rva)
    if (spec is None or reached != {spec["site"]} or
            reached_epilogues != {spec["epilogue_site"]}):
        raise RuntimeError(
            "unexpected or partial laser-profile membership at root %08x" %
            root_rva)
    if (img.base != DEFAULT_BASE or
            os.path.getsize(img.path) != VITA_PILL_BLOOM_BYPASS_PE_SIZE or
            _vita_pill_bloom_bypass_file_sha256(img.path) !=
            VITA_PILL_BLOOM_BYPASS_PE_SHA256):
        raise RuntimeError("laser-profile input PE identity changed")

    owner = img.code_at(root_rva, spec["end"] - root_rva)
    emitted_by_rva = {
        instruction.address: legacy_statements(statements)
        for instruction, statements in body
    }
    site = insns.get(spec["site"])
    epilogue = insns.get(spec["epilogue_site"])
    this_move_rva = (
        0x004D135D if root_rva == 0x004D1330 else 0x004D50BA)
    visible_rva = (
        0x004D1362 if root_rva == 0x004D1330 else 0x004D50BF)
    sample_rva = (
        0x004D136F if root_rva == 0x004D1330 else 0x004D50CC)
    active_rva = 0x004D137C if root_rva == 0x004D1330 else None
    this_move = insns.get(this_move_rva)
    visible = insns.get(visible_rva)
    sample = insns.get(sample_rva)
    active = insns.get(active_rva) if active_rva is not None else None
    expected_edges = spec["switch_edges"]
    actual_edges = {
        key: tuple(value) for key, value in indirect_edges.items()
    }

    if (hashlib.sha256(owner).hexdigest() != spec["body_sha256"] or
            len(order) != spec["insns"] or not order or
            order[0] != root_rva or order[-1] != spec["last"] or
            max(order) != spec["last"] or
            rva_sequence_sha256(order) != spec["order_sha256"] or
            tuple(extra_entries) != spec["switch_entries"] or
            actual_edges != expected_edges or
            site is None or site.mnemonic != "je" or
            bytes(site.bytes) != spec["machine"] or
            not jcc_statement_matches(
                emitted_by_rva.get(spec["site"], ()), spec["epilogue_site"]) or
            epilogue is None or
            bytes(epilogue.bytes) != spec["epilogue_machine"] or
            epilogue.mnemonic != spec["epilogue_mnemonic"] or
            epilogue.op_str != spec["epilogue_op_str"] or
            this_move is None or this_move.mnemonic != "mov" or
            this_move.op_str != "%s, ecx" % spec["this_reg"] or
            visible is None or visible.mnemonic != "cmp" or
            visible.op_str != "byte ptr [%s + 0x169], 0" %
            spec["this_reg"] or
            sample is None or
            (root_rva == 0x004D1330 and
             (sample.mnemonic != "cmp" or
              sample.op_str != "byte ptr [esi + 0x3ad], 0")) or
            (root_rva == 0x004D5090 and
             (sample.mnemonic != "mov" or
              sample.op_str != "al, byte ptr [edi + 0x3ad]")) or
            (active_rva is not None and
             (active is None or active.mnemonic != "cmp" or
              active.op_str != "byte ptr [esi + 0x145], 0")) or
            hashlib.sha256(img.code_at(
                root_rva, spec["window_end"] - root_rva)).hexdigest() !=
            spec["window_sha256"]):
        raise RuntimeError(
            "laser Render/Shadow active-path proof changed at %08x" %
            root_rva)
    return spec


def render_vita_laser_profile_begin(spec):
    """Render one bounded, read-only active-laser begin probe."""
    reg = spec["this_reg"]
    return (
        "#if defined(__vita__) && defined(ISAAC_VITA_LASER_PROFILE)",
        "    extern void kage_vita_phase_profile_laser_begin(",
        "        uint32_t, uint32_t, uint32_t, uint32_t, uint32_t, uint32_t);",
        "    kage_vita_phase_profile_laser_begin(",
        "        c->ebp,",
        "        ld32((uint32_t)(c->%s + 0x%xU))," %
        (reg, VITA_LASER_PROFILE_SOURCE_TYPE_OFFSET),
        "        ld32((uint32_t)(c->%s + 0x%xU))," %
        (reg, VITA_LASER_PROFILE_VARIANT_OFFSET),
        "        ld32((uint32_t)(c->%s + 0x%xU))," %
        (reg, VITA_LASER_PROFILE_SUBTYPE_OFFSET),
        "        (uint32_t)ld8((uint32_t)(c->%s + 0x%xU)), %uU);" %
        (reg, VITA_LASER_PROFILE_SAMPLE_OFFSET, spec["shadow"]),
        "#endif",
    )


def render_vita_laser_profile_end(spec):
    """Render the matching common-epilogue probe without guest mutation."""
    return (
        "#if defined(__vita__) && defined(ISAAC_VITA_LASER_PROFILE)",
        # This block is emitted immediately after the common-epilogue label.
        # ISO C does not allow a label to designate a declaration, so keep an
        # explicit null statement before the local prototype.
        "    ;",
        "    extern void kage_vita_phase_profile_laser_end(",
        "        uint32_t, uint32_t);",
        "    kage_vita_phase_profile_laser_end(c->ebp, %uU);" %
        spec["shadow"],
        "#endif",
    )


def vita_laser_profile_host_oracle(events):
    """Classify the scalar tuples emitted at the exact active seams."""
    result = {
        "render": 0, "shadow": 0,
        "sample_zero": 0, "sample_positive": 0,
        "source_1": 0, "source_10_999": 0, "source_other": 0,
        "variant_0": 0, "variant_1": 0, "variant_2": 0,
        "variant_other": 0, "subtype_1_3": 0, "subtype_other": 0,
        "bad": 0,
    }
    for source_type, variant, subtype, sample, shadow in events:
        key = "shadow" if shadow else "render"
        result[key] += 1
        if shadow:
            if sample == 0 or sample >= 0x80:
                result["bad"] += 1
            continue
        if sample == 0:
            result["sample_zero"] += 1
        elif sample < 0x80:
            result["sample_positive"] += 1
        else:
            result["bad"] += 1
        if source_type == 1:
            result["source_1"] += 1
        elif 10 <= source_type < 1000:
            result["source_10_999"] += 1
        else:
            result["source_other"] += 1
        if variant in (0, 1, 2):
            result["variant_%u" % variant] += 1
        else:
            result["variant_other"] += 1
        if subtype in (1, 2, 3):
            result["subtype_1_3"] += 1
        else:
            result["subtype_other"] += 1
    return result


def vita_poop_fx_for_body(img, root_rva, em, insns, order, body):
    """Select and pin the exact AddPoopFx and foreground-render seams."""
    members = frozenset(order)
    reached = members & VITA_POOP_FX_SITES
    if not reached:
        return None
    spec = VITA_POOP_FX_OWNERS.get(root_rva)
    if spec is None or reached != spec["sites"]:
        raise RuntimeError(
            "unexpected or partial PoopFx membership at root %08x" % root_rva)
    if (img.base != DEFAULT_BASE or
            os.path.getsize(img.path) != VITA_POOP_FX_PE_SIZE or
            _vita_pill_bloom_bypass_file_sha256(img.path) !=
            VITA_POOP_FX_PE_SHA256):
        raise RuntimeError("PoopFx input PE identity changed")

    owner = img.code_at(root_rva, spec["end"] - root_rva)
    decoded = tuple(T.CS.disasm(owner, root_rva))
    emitted_by_rva = {
        instruction.address: legacy_statements(statements)
        for instruction, statements in body
    }
    if (hashlib.sha256(owner).hexdigest() != spec["body_sha256"] or
            len(order) != spec["insns"] or not order or
            order[0] != root_rva or order[-1] != spec["last"] or
            max(order) != spec["last"] or
            rva_sequence_sha256(order) != spec["order_sha256"] or
            len(decoded) != spec["insns"] or
            sum(instruction.size for instruction in decoded) != len(owner)):
        raise RuntimeError(
            "PoopFx translated owner identity changed at %08x" % root_rva)

    if root_rva == VITA_POOP_FX_RENDER_ROOT_RVA:
        countdown_guard = insns.get(0x004EC4F4)
        countdown_branch = insns.get(0x004EC4F8)
        count_guard = insns.get(0x004EC563)
        active_branch = insns.get(VITA_POOP_FX_RENDER_ACTIVE_SITE_RVA)
        cap_site = insns.get(VITA_POOP_FX_RENDER_CAP_SITE_RVA)
        loop_branch = insns.get(VITA_POOP_FX_RENDER_LOOP_BRANCH_RVA)
        if (countdown_guard is None or countdown_guard.mnemonic != "cmp" or
                countdown_guard.op_str != "dword ptr [esi + 0x34], 0" or
                countdown_branch is None or countdown_branch.mnemonic != "jle" or
                countdown_branch.op_str != "0x%x" %
                VITA_POOP_FX_RENDER_EXIT_RVA or
                count_guard is None or count_guard.mnemonic != "cmp" or
                count_guard.op_str != "dword ptr [esi + 0x50], edi" or
                active_branch is None or active_branch.mnemonic != "jle" or
                active_branch.op_str != "0x%x" %
                VITA_POOP_FX_RENDER_EXIT_RVA or
                bytes(active_branch.bytes) !=
                VITA_POOP_FX_RENDER_ACTIVE_MACHINE or
                emitted_by_rva.get(VITA_POOP_FX_RENDER_ACTIVE_SITE_RVA) !=
                (VITA_POOP_FX_RENDER_ACTIVE_STATEMENT,) or
                cap_site is None or cap_site.mnemonic != "cmp" or
                cap_site.op_str != "edi, dword ptr [esi + 0x50]" or
                bytes(cap_site.bytes) != VITA_POOP_FX_RENDER_CAP_MACHINE or
                emitted_by_rva.get(VITA_POOP_FX_RENDER_CAP_SITE_RVA) != () or
                loop_branch is None or loop_branch.mnemonic != "jl" or
                loop_branch.op_str != "0x%x" % VITA_POOP_FX_RENDER_LOOP_RVA or
                bytes(loop_branch.bytes) !=
                VITA_POOP_FX_RENDER_LOOP_BRANCH_MACHINE or
                emitted_by_rva.get(VITA_POOP_FX_RENDER_LOOP_BRANCH_RVA) !=
                (VITA_POOP_FX_RENDER_LOOP_STATEMENT,) or
                VITA_POOP_FX_RENDER_LOOP_RVA not in em.labels or
                VITA_POOP_FX_RENDER_EXIT_RVA not in em.labels):
            raise RuntimeError("PoopFx foreground loop proof changed")
    else:
        capture = insns.get(VITA_POOP_FX_ADD_CAPTURE_SITE_RVA)
        countdown = insns.get(VITA_POOP_FX_ADD_COUNTDOWN_RVA)
        count = insns.get(VITA_POOP_FX_ADD_COUNT_RVA)
        direct_calls = _vita_fxlayers_direct_call_xrefs(
            img, VITA_POOP_FX_ADD_ROOT_RVA)
        if (capture is None or capture.mnemonic != "mov" or
                capture.op_str != "ebp, dword ptr [ebx + 4]" or
                bytes(capture.bytes) != VITA_POOP_FX_ADD_CAPTURE_MACHINE or
                emitted_by_rva.get(VITA_POOP_FX_ADD_CAPTURE_SITE_RVA) !=
                (VITA_POOP_FX_ADD_CAPTURE_STATEMENT,) or
                countdown is None or countdown.mnemonic != "mov" or
                countdown.op_str != "dword ptr [edi + 0x34], 0xb4" or
                count is None or count.mnemonic != "mov" or
                count.op_str != "dword ptr [edi + 0x50], 3" or
                direct_calls != VITA_POOP_FX_DIRECT_CALL_SITES or
                img.code_at(
                    VITA_POOP_FX_ASSET_STRING_RVA,
                    len(VITA_POOP_FX_ASSET_STRING)) !=
                VITA_POOP_FX_ASSET_STRING):
            raise RuntimeError("AddPoopFx source/state proof changed")
    return spec["kind"]


def render_vita_poop_fx_site(kind, site):
    """Emit read-only PoopFx telemetry and the opt-in one-cloud policy."""
    if kind == "add" and site == VITA_POOP_FX_ADD_CAPTURE_SITE_RVA:
        return (
            "#if defined(__vita__) && "
            "defined(ISAAC_VITA_POOP_FX_PROFILE) && "
            "defined(ISAAC_VITA_PHASE_RECEIPTS)",
            "    extern void kage_vita_phase_profile_note_poop_fx_add(uint32_t);",
            "    kage_vita_phase_profile_note_poop_fx_add(c->ebp);",
            "#endif",
        )
    if kind == "render" and site == VITA_POOP_FX_RENDER_ACTIVE_SITE_RVA:
        return (
            "#if defined(__vita__) && "
            "defined(ISAAC_VITA_POOP_FX_PROFILE) && "
            "defined(ISAAC_VITA_PHASE_RECEIPTS)",
            "    extern void kage_vita_phase_profile_note_poop_fx_render(",
            "        uint32_t, uint32_t);",
            "    kage_vita_phase_profile_note_poop_fx_render(",
            "        ld32((uint32_t)(c->esi + 0x34U)),",
            "        ld32((uint32_t)(c->esi + 0x50U)));",
            "#endif",
        )
    if kind == "render" and site == VITA_POOP_FX_RENDER_CAP_SITE_RVA:
        return (
            "#if defined(__vita__) && defined(ISAAC_VITA_POOP_FX_SINGLE_CLOUD)",
            "    if (c->edi == 1U &&",
            "            ld32((uint32_t)(c->esi + 0x50U)) == 3U) {",
            "#if defined(ISAAC_VITA_PHASE_RECEIPTS)",
            "        extern void kage_vita_phase_profile_note_poop_fx_cap(",
            "            uint32_t);",
            "        kage_vita_phase_profile_note_poop_fx_cap(2U);",
            "#endif",
            "        goto L_004ec78e;",
            "    }",
            "#endif",
        )
    raise ValueError("unknown PoopFx seam %s/%08x" % (kind, site))


def vita_poop_fx_profile_host_oracle(callers, renders, single_cloud=False):
    """Pure scalar model for source attribution and the visual cap predicate."""
    result = {
        "add_pill": 0, "add_black": 0, "add_other": 0, "add_unknown": 0,
        "active": 0, "clouds": 0,
        "countdown_min": 0, "countdown_max": 0, "countdown_last": 0,
        "cap_frames": 0, "cap_skipped": 0, "bad": 0,
    }
    known_other = set(VITA_POOP_FX_DIRECT_RETURN_RVAS) - {
        VITA_POOP_FX_PILL_RETURN_RVA,
        VITA_POOP_FX_BLACK_CORRELATED_RETURN_RVA,
    }
    for caller in callers:
        if caller == VITA_POOP_FX_PILL_RETURN_RVA:
            result["add_pill"] += 1
        elif caller == VITA_POOP_FX_BLACK_CORRELATED_RETURN_RVA:
            result["add_black"] += 1
        elif caller in known_other:
            result["add_other"] += 1
        else:
            result["add_unknown"] += 1
            result["bad"] += 1
    for countdown, count, completed_clouds in renders:
        result["active"] += 1
        result["clouds"] += count
        result["countdown_last"] = countdown
        if result["active"] == 1:
            result["countdown_min"] = countdown
        else:
            result["countdown_min"] = min(
                result["countdown_min"], countdown)
        result["countdown_max"] = max(result["countdown_max"], countdown)
        if countdown < 1 or countdown > 180 or count != 3:
            result["bad"] += 1
        if single_cloud and count == 3 and completed_clouds == 1:
            result["cap_frames"] += 1
            result["cap_skipped"] += 2
    return result


def _vita_png_decode_profile_rel32_xrefs(img, target_rva):
    """Return every raw .text E8 whose relative target is target_rva."""
    found = []
    for site in range(img.text_rva, img.text_end - 4):
        if img.mem[site] != 0xE8:
            continue
        displacement = int.from_bytes(
            img.code_at(site + 1, 4), "little", signed=True)
        if ((site + 5 + displacement) & 0xFFFFFFFF) == target_rva:
            found.append(site)
    return tuple(found)


def vita_png_decode_profile_for_body(
        img, root_rva, insns, order, body, extra_entries, indirect_edges):
    """Pin one of five exact PNG decode/profile owners and its ABI seam."""
    members = frozenset(order)
    reached = members & VITA_PNG_DECODE_PROFILE_SITES
    spec = VITA_PNG_DECODE_PROFILE_OWNERS.get(root_rva)
    if spec is None:
        if reached:
            raise RuntimeError(
                "unexpected PNG decode profile membership at root %08x" %
                root_rva)
        return None
    expected_reached = (
        frozenset((spec["site"],)) if "site" in spec else frozenset())
    if reached != expected_reached:
        raise RuntimeError(
            "partial PNG decode profile membership at root %08x" % root_rva)
    if (img.base != DEFAULT_BASE or
            os.path.getsize(img.path) != VITA_PNG_DECODE_PROFILE_PE_SIZE or
            _vita_pill_bloom_bypass_file_sha256(img.path) !=
            VITA_PNG_DECODE_PROFILE_PE_SHA256):
        raise RuntimeError("PNG decode profile input PE identity changed")

    # `img` is deliberately rebased for translation.  The frozen body/table
    # hashes are physical PE bytes, so reconstruct the preferred-base image
    # rather than accidentally pinning one generator relocation policy.
    raw_img = Image(img.path, img.orig_base)
    owner = raw_img.code_at(root_rva, spec["end"] - root_rva)
    emitted_by_rva = {
        instruction.address: legacy_statements(statements)
        for instruction, statements in body
    }
    if (hashlib.sha256(owner).hexdigest() != spec["body_sha256"] or
            len(order) != spec["insns"] or not order or
            order[0] != root_rva or order[-1] != spec["last"] or
            max(order) != spec["last"] or
            rva_sequence_sha256(order) != spec["order_sha256"]):
        raise RuntimeError(
            "PNG decode translated owner identity changed at %08x" %
            root_rva)

    if "site" in spec:
        site = insns.get(spec["site"])
        target = (VITA_PNG_DECODE_PROFILE_OUTER_RVA
                  if spec["kind"] == "image"
                  else VITA_PNG_DECODE_PROFILE_ROW_RVA)
        if (site is None or site.mnemonic != "call" or
                bytes(site.bytes) != spec["machine"] or
                site.op_str != "0x%x" % target or
                emitted_by_rva.get(spec["site"]) != (spec["statement"],)):
            raise RuntimeError(
                "PNG decode CALL/emission seam changed at %08x" %
                spec["site"])

    if root_rva == VITA_PNG_DECODE_PROFILE_OUTER_RVA:
        local_setjmp = insns.get(VITA_PNG_DECODE_PROFILE_SETJMP_RVA)
        setjmp_test = insns.get(VITA_PNG_DECODE_PROFILE_SETJMP_TEST_RVA)
        normal_branch = insns.get(VITA_PNG_DECODE_PROFILE_NORMAL_BRANCH_RVA)
        error_entry = insns.get(VITA_PNG_DECODE_PROFILE_ERROR_PATH_RVA)
        error_exit = insns.get(VITA_PNG_DECODE_PROFILE_ERROR_EXIT_RVA)
        common_fail = insns.get(VITA_PNG_DECODE_PROFILE_COMMON_FAIL_RVA)
        read_row = insns.get(VITA_PNG_DECODE_PROFILE_READ_ROW_CALL_RVA)
        setjmp_spec = SETJMP_CALL_SPECS.get(
            VITA_PNG_DECODE_PROFILE_SETJMP_RVA)
        if (_vita_png_decode_profile_rel32_xrefs(
                raw_img, VITA_PNG_DECODE_PROFILE_OUTER_RVA) !=
                VITA_PNG_DECODE_PROFILE_IMAGE_XREFS or
                _vita_png_decode_profile_rel32_xrefs(
                    raw_img, 0x005B1500) !=
                VITA_PNG_DECODE_PROFILE_READ_XREFS or
                local_setjmp is None or local_setjmp.mnemonic != "call" or
                bytes(local_setjmp.bytes) !=
                VITA_PNG_DECODE_PROFILE_SETJMP_MACHINE or
                local_setjmp.op_str != "0x%x" % SETJMP_THUNK_RVA or
                setjmp_spec is None or
                setjmp_spec["continuation"] !=
                VITA_PNG_DECODE_PROFILE_SETJMP_CONTINUATION_RVA or
                setjmp_spec["machine"] !=
                VITA_PNG_DECODE_PROFILE_SETJMP_MACHINE or
                setjmp_spec["members"] != frozenset((root_rva,)) or
                setjmp_test is None or setjmp_test.mnemonic != "test" or
                setjmp_test.op_str != "eax, eax" or
                bytes(setjmp_test.bytes) !=
                VITA_PNG_DECODE_PROFILE_SETJMP_TEST_MACHINE or
                normal_branch is None or normal_branch.mnemonic != "je" or
                normal_branch.op_str != "0x%x" %
                VITA_PNG_DECODE_PROFILE_NORMAL_PATH_RVA or
                bytes(normal_branch.bytes) !=
                VITA_PNG_DECODE_PROFILE_NORMAL_BRANCH_MACHINE or
                error_entry is None or error_entry.mnemonic != "push" or
                error_entry.op_str != "dword ptr [ebp - 0x41c]" or
                error_exit is None or error_exit.mnemonic != "jmp" or
                error_exit.op_str != "0x%x" %
                VITA_PNG_DECODE_PROFILE_COMMON_FAIL_RVA or
                bytes(error_exit.bytes) !=
                VITA_PNG_DECODE_PROFILE_ERROR_EXIT_MACHINE or
                common_fail is None or common_fail.mnemonic != "mov" or
                common_fail.op_str != "ecx, dword ptr [ebp - 4]" or
                VITA_PNG_DECODE_PROFILE_NORMAL_PATH_RVA not in members or
                VITA_PNG_DECODE_PROFILE_ERROR_PATH_RVA not in members or
                VITA_PNG_DECODE_PROFILE_COMMON_FAIL_RVA not in members or
                read_row is None or read_row.mnemonic != "call" or
                bytes(read_row.bytes) !=
                VITA_PNG_DECODE_PROFILE_READ_ROW_MACHINE or
                read_row.op_str != "0x5b1500" or
                order.index(VITA_PNG_DECODE_PROFILE_SETJMP_RVA) >=
                order.index(VITA_PNG_DECODE_PROFILE_READ_ROW_CALL_RVA)):
            raise RuntimeError(
                "PNG image-loader xref/local-longjmp proof changed")

    if root_rva == 0x005B1500:
        abi = {
            0x005B178F: ("lea", "edx, [esi + 0xf8]"),
            0x005B17CD: ("mov", "dword ptr [esi + 0xf8], ecx"),
            0x005B17DF: ("mov", "dword ptr [esi + 0xfc], eax"),
            0x005B17E5: ("movzx", "eax, byte ptr [ecx]"),
            0x005B17E8: ("push", "eax"),
            0x005B17F0: ("push", "eax"),
            0x005B17F6: ("push", "eax"),
        }
        read_table = raw_img.code_at(
            VITA_PNG_DECODE_PROFILE_READ_TABLE_RVA,
            len(VITA_PNG_DECODE_PROFILE_READ_TABLE_RAW))
        read_jump = insns.get(VITA_PNG_DECODE_PROFILE_READ_TABLE_SITE_RVA)
        read_edges = {
            site: tuple(targets) for site, targets in indirect_edges.items()
        }
        if (hashlib.sha256(raw_img.code_at(
                VITA_PNG_DECODE_PROFILE_ROW_WINDOW_RVA,
                VITA_PNG_DECODE_PROFILE_ROW_WINDOW_END_RVA -
                VITA_PNG_DECODE_PROFILE_ROW_WINDOW_RVA)).hexdigest() !=
                VITA_PNG_DECODE_PROFILE_ROW_WINDOW_SHA256 or
                any(insns.get(rva) is None or
                    insns[rva].mnemonic != expected[0] or
                    insns[rva].op_str != expected[1]
                    for rva, expected in abi.items()) or
                _vita_png_decode_profile_rel32_xrefs(
                    raw_img, VITA_PNG_DECODE_PROFILE_ROW_RVA) !=
                VITA_PNG_DECODE_PROFILE_ROW_XREFS or
                tuple(extra_entries) != tuple(sorted(
                    VITA_PNG_DECODE_PROFILE_READ_TARGETS)) or
                # Indirect edges retain the on-disk jump-table order, which
                # is independently pinned below rather than merely set-equal.
                read_edges != {
                    VITA_PNG_DECODE_PROFILE_READ_TABLE_SITE_RVA:
                        VITA_PNG_DECODE_PROFILE_READ_TARGETS
                } or
                read_table != VITA_PNG_DECODE_PROFILE_READ_TABLE_RAW or
                hashlib.sha256(read_table).hexdigest() !=
                VITA_PNG_DECODE_PROFILE_READ_TABLE_SHA256 or
                tuple(int.from_bytes(
                    read_table[index:index + 4], "little")
                    for index in range(0, len(read_table), 4)) !=
                tuple(raw_img.va(target) for target in
                      VITA_PNG_DECODE_PROFILE_READ_TARGETS) or
                any(VITA_PNG_DECODE_PROFILE_READ_TABLE_RVA + 4 * index
                    not in raw_img.reloc_rvas for index in range(7)) or
                read_jump is None or read_jump.mnemonic != "jmp" or
                bytes(read_jump.bytes[:3]) != bytes.fromhex("ff2485")):
            raise RuntimeError("PNG row caller ABI/xref proof changed")

    if root_rva == VITA_PNG_DECODE_PROFILE_ROW_RVA:
        table = raw_img.code_at(
            VITA_PNG_DECODE_PROFILE_TABLE_RVA,
            len(VITA_PNG_DECODE_PROFILE_TABLE_RAW))
        jump = insns.get(VITA_PNG_DECODE_PROFILE_TABLE_SITE_RVA)
        actual_edges = {
            site: tuple(targets) for site, targets in indirect_edges.items()
        }
        expected_edges = {
            VITA_PNG_DECODE_PROFILE_TABLE_SITE_RVA:
                VITA_PNG_DECODE_PROFILE_FILTER_TARGETS
        }
        raw_targets = tuple(
            int.from_bytes(table[index:index + 4], "little")
            for index in range(0, len(table), 4)
        )
        full_extent = raw_img.code_at(
            root_rva,
            VITA_PNG_DECODE_PROFILE_ROW_EXTENT_END_RVA - root_rva)
        if (hashlib.sha256(full_extent).hexdigest() !=
                VITA_PNG_DECODE_PROFILE_ROW_EXTENT_SHA256 or
                raw_img.code_at(
                    VITA_PNG_DECODE_PROFILE_PADDING_RVA,
                    len(VITA_PNG_DECODE_PROFILE_PADDING)) !=
                VITA_PNG_DECODE_PROFILE_PADDING or
                table != VITA_PNG_DECODE_PROFILE_TABLE_RAW or
                hashlib.sha256(table).hexdigest() !=
                VITA_PNG_DECODE_PROFILE_TABLE_SHA256 or
                raw_targets != tuple(
                    raw_img.va(target)
                    for target in VITA_PNG_DECODE_PROFILE_FILTER_TARGETS) or
                any(VITA_PNG_DECODE_PROFILE_TABLE_RVA + 4 * index not in
                    raw_img.reloc_rvas for index in range(5)) or
                tuple(extra_entries) != tuple(sorted(
                    VITA_PNG_DECODE_PROFILE_FILTER_TARGETS)) or
                actual_edges != expected_edges or
                jump is None or jump.mnemonic != "jmp" or
                bytes(jump.bytes[:3]) != bytes.fromhex("ff2495")):
            raise RuntimeError("PNG row filter table/CFG proof changed")
    return spec["kind"]


def vita_png_inflate_profile_for_body(
        img, root_rva, insns, order, body, extra_entries, indirect_edges):
    """Pin every frozen libpng -> zlib timing seam and its guest ABI."""
    members = frozenset(order)
    reached = members & VITA_PNG_INFLATE_PROFILE_SITES
    spec = VITA_PNG_INFLATE_PROFILE_OWNERS.get(root_rva)
    if spec is None:
        if reached:
            raise RuntimeError(
                "unexpected PNG inflate profile membership at root %08x" %
                root_rva)
        return None
    if reached != frozenset((spec["site"],)):
        raise RuntimeError(
            "partial PNG inflate profile membership at root %08x" %
            root_rva)
    if (img.base != DEFAULT_BASE or
            os.path.getsize(img.path) != VITA_PNG_DECODE_PROFILE_PE_SIZE or
            _vita_pill_bloom_bypass_file_sha256(img.path) !=
            VITA_PNG_DECODE_PROFILE_PE_SHA256):
        raise RuntimeError("PNG inflate profile input PE identity changed")

    raw_img = Image(img.path, img.orig_base)
    owner = raw_img.code_at(root_rva, spec["end"] - root_rva)
    site = insns.get(spec["site"])
    emitted_by_rva = {
        instruction.address: legacy_statements(statements)
        for instruction, statements in body
    }
    if (hashlib.sha256(owner).hexdigest() != spec["body_sha256"] or
            len(order) != spec["insns"] or not order or
            order[0] != root_rva or order[-1] != spec["last"] or
            max(order) != spec["last"] or
            rva_sequence_sha256(order) != spec["order_sha256"] or
            site is None or site.mnemonic != "call" or
            bytes(site.bytes) != spec["machine"] or
            site.op_str != "0x%x" % spec["target"] or
            emitted_by_rva.get(spec["site"]) != (spec["statement"],) or
            hashlib.sha256(raw_img.code_at(
                spec["window_start"],
                spec["window_end"] - spec["window_start"])).hexdigest() !=
            spec["window_sha256"] or
            any(insns.get(rva) is None or
                insns[rva].mnemonic != expected[0] or
                insns[rva].op_str != expected[1]
                for rva, expected in spec["abi"].items())):
        raise RuntimeError(
            "PNG inflate owner/CALL/ABI identity changed at %08x" %
            root_rva)

    # These raw-text censuses prove that the three caller classes and the one
    # nested fast seam are complete, rather than merely the sites we happened
    # to find in the translated roots.
    if (_vita_png_decode_profile_rel32_xrefs(
            raw_img, VITA_PNG_INFLATE_PROFILE_INFLATE_RVA) !=
            VITA_PNG_INFLATE_PROFILE_INFLATE_XREFS or
            _vita_png_decode_profile_rel32_xrefs(
                raw_img, VITA_PNG_INFLATE_PROFILE_FAST_RVA) !=
            VITA_PNG_INFLATE_PROFILE_FAST_XREFS):
        raise RuntimeError("PNG inflate direct-xref census changed")

    if root_rva == 0x005D6D80:
        table = raw_img.code_at(
            VITA_PNG_INFLATE_PROFILE_CODES_TABLE_RVA,
            len(VITA_PNG_INFLATE_PROFILE_CODES_TABLE_RAW))
        jump = insns.get(VITA_PNG_INFLATE_PROFILE_CODES_TABLE_SITE_RVA)
        actual_edges = {
            site_rva: tuple(targets)
            for site_rva, targets in indirect_edges.items()
        }
        raw_targets = tuple(
            int.from_bytes(table[index:index + 4], "little")
            for index in range(0, len(table), 4)
        )
        if (tuple(extra_entries) != tuple(sorted(
                VITA_PNG_INFLATE_PROFILE_CODES_TARGETS)) or
                actual_edges != {
                    VITA_PNG_INFLATE_PROFILE_CODES_TABLE_SITE_RVA:
                        VITA_PNG_INFLATE_PROFILE_CODES_TARGETS
                } or
                table != VITA_PNG_INFLATE_PROFILE_CODES_TABLE_RAW or
                hashlib.sha256(table).hexdigest() !=
                VITA_PNG_INFLATE_PROFILE_CODES_TABLE_SHA256 or
                raw_targets != tuple(
                    raw_img.va(target)
                    for target in VITA_PNG_INFLATE_PROFILE_CODES_TARGETS) or
                any(VITA_PNG_INFLATE_PROFILE_CODES_TABLE_RVA + 4 * index
                    not in raw_img.reloc_rvas for index in range(10)) or
                jump is None or jump.mnemonic != "jmp" or
                bytes(jump.bytes[:3]) != bytes.fromhex("ff2495")):
            raise RuntimeError("PNG inflate_codes table/CFG proof changed")
    return spec["kind"]


def vita_archive_miniz_fastpath_for_body(
        img, root_rva, insns, order, extra_entries, indirect_edges):
    """Authenticate Isaac's frozen 32-bit miniz v1.15 coroutine."""
    if root_rva != VITA_ARCHIVE_MINIZ_FASTPATH_ROOT_RVA:
        return False
    if (img.base != DEFAULT_BASE or
            os.path.getsize(img.path) != VITA_PNG_DECODE_PROFILE_PE_SIZE or
            _vita_pill_bloom_bypass_file_sha256(img.path) !=
            VITA_PNG_DECODE_PROFILE_PE_SHA256):
        raise RuntimeError("archive MiniZ fast-path PE identity changed")

    raw_img = Image(img.path, img.orig_base)
    body = raw_img.code_at(
        root_rva, VITA_ARCHIVE_MINIZ_FASTPATH_END_RVA - root_rva)
    caller = raw_img.code_at(
        VITA_ARCHIVE_MINIZ_FASTPATH_CALLER_START_RVA,
        VITA_ARCHIVE_MINIZ_FASTPATH_CALLER_END_RVA -
        VITA_ARCHIVE_MINIZ_FASTPATH_CALLER_START_RVA)
    initializer = raw_img.code_at(
        VITA_ARCHIVE_MINIZ_FASTPATH_INIT_START_RVA,
        VITA_ARCHIVE_MINIZ_FASTPATH_INIT_END_RVA -
        VITA_ARCHIVE_MINIZ_FASTPATH_INIT_START_RVA)
    calls = _vita_png_decode_profile_rel32_xrefs(raw_img, root_rva)
    address_refs = tuple(
        rva for rva in sorted(raw_img.reloc_rvas)
        if int.from_bytes(raw_img.code_at(rva, 4), "little") ==
        raw_img.va(root_rva)
    )
    actual_edges = {
        site: tuple(targets) for site, targets in indirect_edges.items()
    }
    required = {
        0x005AEB13: ("mov", "eax, dword ptr [ebp + 8]"),
        0x005AEB18: ("mov", "esi, dword ptr [ebp + 0x10]"),
        0x005AEB1B: ("mov", "ebx, edx"),
        0x005AEB26: ("mov", "edi, ecx"),
        0x005AEB2E: ("mov", "ecx, dword ptr [ebp + 0x14]"),
        0x005AEB33: ("mov", "edx, dword ptr [ebp + 0xc]"),
        0x005AEB69: ("mov", "ecx, dword ptr [ebp + 0x18]"),
        VITA_ARCHIVE_MINIZ_FASTPATH_LAST_RVA: ("ret", ""),
    }
    if (hashlib.sha256(body).hexdigest() !=
            VITA_ARCHIVE_MINIZ_FASTPATH_BODY_SHA256 or
            len(order) != VITA_ARCHIVE_MINIZ_FASTPATH_INSNS or
            not order or order[0] != root_rva or
            order[-1] != VITA_ARCHIVE_MINIZ_FASTPATH_LAST_RVA or
            rva_sequence_sha256(order) !=
            VITA_ARCHIVE_MINIZ_FASTPATH_ORDER_SHA256 or
            hashlib.sha256(caller).hexdigest() !=
            VITA_ARCHIVE_MINIZ_FASTPATH_CALLER_SHA256 or
            hashlib.sha256(initializer).hexdigest() !=
            VITA_ARCHIVE_MINIZ_FASTPATH_INIT_SHA256 or
            calls != (VITA_ARCHIVE_MINIZ_FASTPATH_CALL_SITE,) or
            address_refs or
            tuple(extra_entries) != tuple(sorted(ARCHIVE_REMAP_CASES)) or
            actual_edges != {
                ARCHIVE_REMAP_SWITCH_RVA: ARCHIVE_REMAP_CASES
            } or
            any(insns.get(rva) is None or
                insns[rva].mnemonic != expected[0] or
                insns[rva].op_str != expected[1]
                for rva, expected in required.items())):
        raise RuntimeError("archive MiniZ body/caller/ABI proof changed")
    return True


def vita_png_inflate_flush_fastpath_for_body(img, root_rva, insns, order):
    """Authenticate the bounded zlib 1.1.4 inflate_flush replacement."""
    if root_rva != VITA_PNG_INFLATE_FLUSH_FASTPATH_RVA:
        return False
    if (img.base != DEFAULT_BASE or
            os.path.getsize(img.path) != VITA_PNG_DECODE_PROFILE_PE_SIZE or
            _vita_pill_bloom_bypass_file_sha256(img.path) !=
            VITA_PNG_DECODE_PROFILE_PE_SHA256):
        raise RuntimeError("PNG inflate_flush fast-path PE identity changed")

    raw_img = Image(img.path, img.orig_base)
    body = raw_img.code_at(
        root_rva,
        VITA_PNG_INFLATE_FLUSH_FASTPATH_END_RVA - root_rva)
    blocks = raw_img.code_at(
        VITA_PNG_INFLATE_FLUSH_BLOCKS_RVA,
        VITA_PNG_INFLATE_FLUSH_BLOCKS_END_RVA -
        VITA_PNG_INFLATE_FLUSH_BLOCKS_RVA)
    codes_spec = VITA_PNG_INFLATE_PROFILE_OWNERS[0x005D6D80]
    codes = raw_img.code_at(
        0x005D6D80, codes_spec["end"] - 0x005D6D80)
    adler = raw_img.code_at(
        VITA_PNG_INFLATE_FLUSH_ADLER_RVA,
        VITA_PNG_INFLATE_FLUSH_ADLER_END_RVA -
        VITA_PNG_INFLATE_FLUSH_ADLER_RVA)
    calls = _vita_png_decode_profile_rel32_xrefs(raw_img, root_rva)
    flush_address_refs = tuple(
        rva for rva in sorted(raw_img.reloc_rvas)
        if int.from_bytes(raw_img.code_at(rva, 4), "little") ==
        raw_img.va(root_rva)
    )
    adler_address_refs = tuple(
        rva for rva in sorted(raw_img.reloc_rvas)
        if int.from_bytes(raw_img.code_at(rva, 4), "little") ==
        raw_img.va(VITA_PNG_INFLATE_FLUSH_ADLER_RVA)
    )
    required = {
        0x005D6729: ("mov", "ebx, edx"),
        0x005D672B: ("mov", "edi, ecx"),
        0x005D6730: ("mov", "esi, dword ptr [edi + 0x30]"),
        0x005D6733: ("mov", "edx, dword ptr [edi + 0x34]"),
        0x005D6736: ("mov", "eax, dword ptr [ebx + 0xc]"),
        0x005D6750: ("mov", "edx, dword ptr [ebp + 8]"),
        0x005D6776: ("mov", "edx, dword ptr [edi + 0x38]"),
        0x005D6782: ("call", "edx"),
        0x005D6796: ("call", "0x5ec14c"),
        0x005D67E9: ("mov", "eax, dword ptr [edi + 0x38]"),
        0x005D67F5: ("call", "eax"),
        0x005D6808: ("call", "0x5ec14c"),
        0x005D681A: ("mov", "dword ptr [ebx + 0xc], eax"),
        0x005D6820: ("mov", "dword ptr [edi + 0x30], esi"),
        0x005D6829: ("ret", ""),
    }
    if (hashlib.sha256(body).hexdigest() !=
            VITA_PNG_INFLATE_FLUSH_FASTPATH_BODY_SHA256 or
            len(order) != VITA_PNG_INFLATE_FLUSH_FASTPATH_INSNS or
            not order or order[0] != root_rva or order[-1] != 0x005D6829 or
            max(order) != 0x005D6829 or
            calls != VITA_PNG_INFLATE_FLUSH_FASTPATH_CALL_SITES or
            calls[:5] != (0x005CE9C6, 0x005CF12A, 0x005CF2AE,
                          0x005CF32C, 0x005CF365) or
            calls[5:] != (0x005D70D4, 0x005D71B9, 0x005D7263,
                          0x005D72F3, 0x005D7326, 0x005D736A,
                          0x005D739F, 0x005D73C7) or
            flush_address_refs or
            hashlib.sha256(blocks).hexdigest() !=
            VITA_PNG_INFLATE_FLUSH_BLOCKS_SHA256 or
            hashlib.sha256(codes).hexdigest() != codes_spec["body_sha256"] or
            hashlib.sha256(adler).hexdigest() !=
            VITA_PNG_INFLATE_FLUSH_ADLER_SHA256 or
            adler_address_refs != (0x005C3732,) or
            _vita_png_decode_profile_rel32_xrefs(
                raw_img, VITA_PNG_INFLATE_PROFILE_INFLATE_RVA) !=
            VITA_PNG_INFLATE_PROFILE_INFLATE_XREFS or
            any(insns.get(rva) is None or
                insns[rva].mnemonic != expected[0] or
                insns[rva].op_str != expected[1]
                for rva, expected in required.items())):
        raise RuntimeError("PNG inflate_flush body/caller/ABI proof changed")
    return True


def vita_png_crc32_fastpath_for_body(
        img, root_rva, insns, order, emit_image_base):
    """Authenticate the frozen bulk PNG/zlib CRC-32 byte loop."""
    if root_rva != VITA_PNG_CRC32_FASTPATH_RVA:
        return False
    if (img.base != DEFAULT_BASE or
            os.path.getsize(img.path) != VITA_PNG_DECODE_PROFILE_PE_SIZE or
            _vita_pill_bloom_bypass_file_sha256(img.path) !=
            VITA_PNG_DECODE_PROFILE_PE_SHA256):
        raise RuntimeError("PNG CRC32 fast-path PE identity changed")

    raw_img = Image(img.path, img.orig_base)
    body = raw_img.code_at(
        root_rva, VITA_PNG_CRC32_FASTPATH_END_RVA - root_rva)
    table = raw_img.code_at(
        VITA_PNG_CRC32_FASTPATH_TABLE_RVA,
        VITA_PNG_CRC32_FASTPATH_TABLE_BYTES)
    calls = _vita_png_decode_profile_rel32_xrefs(raw_img, root_rva)
    address_refs = tuple(
        rva for rva in sorted(raw_img.reloc_rvas)
        if int.from_bytes(raw_img.code_at(rva, 4), "little") ==
        raw_img.va(root_rva)
    )
    expected_table_address = (
        emit_image_base + VITA_PNG_CRC32_FASTPATH_TABLE_RVA) & 0xFFFFFFFF
    table_sites = (0x005C334E, 0x005C33D6, 0x005C33FE)
    table_operands_valid = True
    for site in table_sites:
        instruction = insns.get(site)
        operands = instruction.operands if instruction is not None else ()
        memory = (operands[1].mem if len(operands) == 2 and
                  operands[1].type == T.cx.X86_OP_MEM else None)
        if (instruction is None or instruction.mnemonic != "xor" or
                len(operands) != 2 or
                operands[0].type != T.cx.X86_OP_REG or
                operands[0].reg != T.cx.X86_REG_ECX or
                memory is None or
                memory.base not in (0, T.cx.X86_REG_INVALID) or
                memory.index != T.cx.X86_REG_EAX or memory.scale != 4 or
                (memory.disp & 0xFFFFFFFF) != expected_table_address):
            table_operands_valid = False
    required = {
        0x005C3323: ("test", "edx, edx"),
        0x005C332C: ("mov", "esi, dword ptr [ebp + 8]"),
        0x005C332F: ("not", "ecx"),
        0x005C333D: ("shr", "edi, 3"),
        0x005C3340: ("movzx", "eax, byte ptr [edx]"),
        0x005C33CB: ("add", "edx, 8"),
        0x005C33E0: ("jne", "0x5c3340"),
        0x005C33F0: ("movzx", "eax, byte ptr [edx]"),
        0x005C3408: ("jne", "0x5c33f0"),
        0x005C340A: ("not", "ecx"),
        0x005C3410: ("ret", ""),
    }
    if (hashlib.sha256(body).hexdigest() !=
            VITA_PNG_CRC32_FASTPATH_BODY_SHA256 or
            len(order) != VITA_PNG_CRC32_FASTPATH_INSNS or
            not order or order[0] != root_rva or
            order[-1] != VITA_PNG_CRC32_FASTPATH_END_RVA - 1 or
            rva_sequence_sha256(order) !=
            VITA_PNG_CRC32_FASTPATH_ORDER_SHA256 or
            calls != VITA_PNG_CRC32_FASTPATH_CALL_SITES or
            address_refs or
            not table_operands_valid or
            hashlib.sha256(table).hexdigest() !=
            VITA_PNG_CRC32_FASTPATH_TABLE_SHA256 or
            any(insns.get(rva) is None or
                insns[rva].mnemonic != expected[0] or
                insns[rva].op_str != expected[1]
                for rva, expected in required.items())):
        raise RuntimeError("PNG CRC32 body/caller/table/ABI proof changed")
    return True


def vita_png_inflate_capture_range_nonwrapping(zstream):
    """Scalar oracle for the generated observation-only z_stream gate."""
    return (isinstance(zstream, int) and not isinstance(zstream, bool) and
            0 < zstream <=
            0xFFFFFFFF -
            VITA_PNG_INFLATE_PROFILE_STREAM_PROVEN_LAST_OFFSET)


def render_vita_png_decode_profile_call(kind, statement):
    """Bracket one frozen guest CALL; preserve the original statement once."""
    if kind == "image":
        before = (
            "#if defined(__vita__) && "
            "defined(ISAAC_VITA_PNG_DECODE_PROFILE)",
            "    extern void kage_vita_png_profile_image_begin(void);",
            "    kage_vita_png_profile_image_begin();",
            "#endif",
        )
        after = (
            "#if defined(__vita__) && "
            "defined(ISAAC_VITA_PNG_DECODE_PROFILE)",
            "    extern void kage_vita_png_profile_image_end(void);",
            "    kage_vita_png_profile_image_end();",
            "#endif",
        )
    elif kind == "row":
        before = (
            "#if defined(__vita__) && "
            "defined(ISAAC_VITA_PNG_DECODE_PROFILE)",
            "    {",
            "        uint32_t _guest_vita_png_filter = UINT32_MAX;",
            "        extern void kage_vita_png_profile_row_begin(",
            "            uint32_t, uint32_t, uint32_t);",
            "        if (guest_stack_contains(c, "
            "(uint32_t)(c->esp + 8U), 4U))",
            "            _guest_vita_png_filter = "
            "ld32((uint32_t)(c->esp + 8U));",
            "        kage_vita_png_profile_row_begin(",
            "            ld32((uint32_t)(c->edx + 4U)),",
            "            (uint32_t)ld8((uint32_t)(c->edx + 0xbU)),",
            "            _guest_vita_png_filter);",
            "    }",
            "#endif",
        )
        after = (
            "#if defined(__vita__) && "
            "defined(ISAAC_VITA_PNG_DECODE_PROFILE)",
            "    extern void kage_vita_png_profile_row_end(void);",
            "    kage_vita_png_profile_row_end();",
            "#endif",
        )
    else:
        raise ValueError("unknown PNG decode profile seam %r" % kind)
    return before + ("    " + statement,) + after


def render_vita_png_inflate_profile_call(spec, statement):
    """Bracket one exact zlib CALL without changing guest state or ABI."""
    guard = (
        "#if defined(__vita__) && ",
        "defined(ISAAC_VITA_PNG_DECODE_PROFILE)",
    )
    if spec["kind"] == "fast":
        return (
            guard[0] + guard[1],
            "    extern void kage_vita_png_profile_fast_begin(void);",
            "    kage_vita_png_profile_fast_begin();",
            "#endif",
            "    " + statement,
            guard[0] + guard[1],
            "    extern void kage_vita_png_profile_fast_end(void);",
            "    kage_vita_png_profile_fast_end();",
            "#endif",
        )

    return (
        guard[0] + guard[1],
        "    {",
        "        uint32_t _guest_vita_png_zstream = c->ecx;",
        "        uint32_t _guest_vita_png_zcapture =",
        "            _guest_vita_png_zstream != 0U &&",
        "            _guest_vita_png_zstream <= UINT32_MAX - 0x%02xU;" %
        VITA_PNG_INFLATE_PROFILE_STREAM_PROVEN_LAST_OFFSET,
        "        uint32_t _guest_vita_png_total_in = 0U;",
        "        uint32_t _guest_vita_png_total_out = 0U;",
        "        extern void kage_vita_png_profile_inflate_begin(",
        "            uint32_t, uint32_t, uint32_t, uint32_t);",
        "        if (_guest_vita_png_zcapture) {",
        "            _guest_vita_png_total_in = ld32(",
        "                _guest_vita_png_zstream + 0x8U);",
        "            _guest_vita_png_total_out = ld32(",
        "                _guest_vita_png_zstream + 0x14U);",
        "        }",
        "        kage_vita_png_profile_inflate_begin(",
        "            %dU, _guest_vita_png_zcapture," % spec["class"],
        "            _guest_vita_png_total_in, _guest_vita_png_total_out);",
        "#endif",
        "    " + statement,
        guard[0] + guard[1],
        "        extern void kage_vita_png_profile_inflate_end(",
        "            uint32_t, uint32_t, uint32_t);",
        "        if (_guest_vita_png_zcapture) {",
        "            _guest_vita_png_total_in = ld32(",
        "                _guest_vita_png_zstream + 0x8U);",
        "            _guest_vita_png_total_out = ld32(",
        "                _guest_vita_png_zstream + 0x14U);",
        "        }",
        "        kage_vita_png_profile_inflate_end(",
        "            _guest_vita_png_zcapture,",
        "            _guest_vita_png_total_in, _guest_vita_png_total_out);",
        "    }",
        "#endif",
    )


def _vita_vanilla_kage_bundle_file_sha256(path):
    digest = hashlib.sha256()
    with open(path, "rb") as stream:
        for chunk in iter(lambda: stream.read(1024 * 1024), b""):
            digest.update(chunk)
    return digest.hexdigest()


def vita_vanilla_kage_bundle_for_body(
        img, root_rva, em, insns, order, body):
    """Select and fail-close the three REPENTOGON-derived vanilla seams."""
    members = frozenset(order)
    reached = members & VITA_VANILLA_KAGE_BUNDLE_SITES
    if not reached:
        return ()

    expected = tuple(
        spec for spec in VITA_VANILLA_KAGE_BUNDLE_SPECS
        if root_rva in spec["roots"]
    )
    expected_sites = frozenset(spec["site"] for spec in expected)
    if (root_rva not in VITA_VANILLA_KAGE_BUNDLE_ROOTS or
            reached != expected_sites):
        raise RuntimeError(
            "unexpected vanilla/KAGE bundle membership at root %08x" %
            root_rva)
    if (img.base != DEFAULT_BASE or
            os.path.getsize(img.path) !=
            VITA_VANILLA_KAGE_BUNDLE_PE_SIZE or
            _vita_vanilla_kage_bundle_file_sha256(img.path) !=
            VITA_VANILLA_KAGE_BUNDLE_PE_SHA256):
        raise RuntimeError("vanilla/KAGE bundle input PE identity changed")

    emitted_by_rva = {
        ins.address: legacy_statements(statements) for ins, statements in body
    }
    if VITA_VANILLA_KAGE_GODHEAD_SITE_RVA in reached:
        root_spec = VITA_VANILLA_KAGE_GODHEAD_ROOT_SPECS.get(root_rva)
        if root_spec is None:
            raise RuntimeError(
                "unexpected Godhead body copy at root %08x" % root_rva)
        count, first, last, order_sha256 = root_spec
        push = insns.get(VITA_VANILLA_KAGE_GODHEAD_SITE_RVA)
        _validate_entity_tear_update_owner_identity(img)
        if (len(order) != count or not order or order[0] != first or
                order[-1] != last or max(order) != last or
                rva_sequence_sha256(order) != order_sha256 or
                push is None or push.mnemonic != "push" or
                push.op_str != "-1" or
                bytes(push.bytes) != VITA_VANILLA_KAGE_GODHEAD_MACHINE or
                emitted_by_rva.get(VITA_VANILLA_KAGE_GODHEAD_SITE_RVA) !=
                (VITA_VANILLA_KAGE_GODHEAD_STATEMENT,) or
                canonical_relocated_chunk_sha256(
                    img, VITA_VANILLA_KAGE_GODHEAD_WINDOW_RVA,
                    VITA_VANILLA_KAGE_GODHEAD_WINDOW_END_RVA -
                    VITA_VANILLA_KAGE_GODHEAD_WINDOW_RVA) !=
                VITA_VANILLA_KAGE_GODHEAD_WINDOW_SHA256):
            raise RuntimeError(
                "Godhead partition owner/emission changed at root %08x" %
                root_rva)

    if VITA_VANILLA_KAGE_STRIDE_SITE_RVA in reached:
        start = VITA_VANILLA_KAGE_STRIDE_ROOT_RVA
        end = VITA_VANILLA_KAGE_STRIDE_END_RVA
        raw = img.code_at(start, end - start)
        decoded = tuple(T.CS.disasm(raw, start))
        branch = insns.get(VITA_VANILLA_KAGE_STRIDE_SITE_RVA)
        if (root_rva != start or
                len(decoded) != VITA_VANILLA_KAGE_STRIDE_INSNS or
                sum(ins.size for ins in decoded) != len(raw) or
                hashlib.sha256(raw).hexdigest() !=
                VITA_VANILLA_KAGE_STRIDE_BODY_SHA256 or
                len(order) != VITA_VANILLA_KAGE_STRIDE_INSNS or
                not order or order[0] != start or
                order[-1] != VITA_VANILLA_KAGE_STRIDE_LAST_RVA or
                max(order) != VITA_VANILLA_KAGE_STRIDE_LAST_RVA or
                rva_sequence_sha256(order) !=
                VITA_VANILLA_KAGE_STRIDE_ORDER_SHA256 or
                branch is None or branch.mnemonic != "je" or
                branch.op_str != "0x%x" %
                VITA_VANILLA_KAGE_STRIDE_ALLOCATE_RVA or
                bytes(branch.bytes) != VITA_VANILLA_KAGE_STRIDE_MACHINE or
                emitted_by_rva.get(VITA_VANILLA_KAGE_STRIDE_SITE_RVA) !=
                (VITA_VANILLA_KAGE_STRIDE_STATEMENT,) or
                VITA_VANILLA_KAGE_STRIDE_ALLOCATE_RVA not in em.labels or
                canonical_relocated_chunk_sha256(
                    img, VITA_VANILLA_KAGE_STRIDE_WINDOW_RVA,
                    VITA_VANILLA_KAGE_STRIDE_WINDOW_END_RVA -
                    VITA_VANILLA_KAGE_STRIDE_WINDOW_RVA) !=
                VITA_VANILLA_KAGE_STRIDE_WINDOW_SHA256):
            raise RuntimeError(
                "KAGE compatible-stride owner/emission changed")

    if VITA_VANILLA_KAGE_INVALIDATE_SITE_RVA in reached:
        start = VITA_VANILLA_KAGE_INVALIDATE_ROOT_RVA
        end = VITA_VANILLA_KAGE_INVALIDATE_END_RVA
        raw = img.code_at(start, end - start)
        decoded = tuple(T.CS.disasm(raw, start))
        store = insns.get(VITA_VANILLA_KAGE_INVALIDATE_SITE_RVA)
        if (root_rva != start or
                len(decoded) != VITA_VANILLA_KAGE_INVALIDATE_INSNS or
                sum(ins.size for ins in decoded) != len(raw) or
                hashlib.sha256(raw).hexdigest() !=
                VITA_VANILLA_KAGE_INVALIDATE_BODY_SHA256 or
                len(order) != VITA_VANILLA_KAGE_INVALIDATE_INSNS or
                not order or order[0] != start or
                order[-1] != VITA_VANILLA_KAGE_INVALIDATE_LAST_RVA or
                max(order) != VITA_VANILLA_KAGE_INVALIDATE_LAST_RVA or
                rva_sequence_sha256(order) !=
                VITA_VANILLA_KAGE_INVALIDATE_ORDER_SHA256 or
                store is None or store.mnemonic != "mov" or
                store.op_str != "dword ptr [eax + 0x5c], 0" or
                bytes(store.bytes) !=
                VITA_VANILLA_KAGE_INVALIDATE_MACHINE or
                emitted_by_rva.get(VITA_VANILLA_KAGE_INVALIDATE_SITE_RVA) !=
                (VITA_VANILLA_KAGE_INVALIDATE_STATEMENT,) or
                canonical_relocated_chunk_sha256(
                    img, VITA_VANILLA_KAGE_INVALIDATE_WINDOW_RVA,
                    VITA_VANILLA_KAGE_INVALIDATE_WINDOW_END_RVA -
                    VITA_VANILLA_KAGE_INVALIDATE_WINDOW_RVA) !=
                VITA_VANILLA_KAGE_INVALIDATE_WINDOW_SHA256):
            raise RuntimeError(
                "KAGE same-image invalidation owner/emission changed")
    return expected


def render_vita_vanilla_kage_bundle(spec, statements):
    """Replace one proved statement while retaining its exact OFF path."""
    if spec not in VITA_VANILLA_KAGE_BUNDLE_SPECS:
        raise RuntimeError("unknown vanilla/KAGE bundle specification")
    kind = spec["kind"]
    expected = {
        "godhead_partition": VITA_VANILLA_KAGE_GODHEAD_STATEMENT,
        "compatible_stride": VITA_VANILLA_KAGE_STRIDE_STATEMENT,
        "same_image_invalidation":
            VITA_VANILLA_KAGE_INVALIDATE_STATEMENT,
    }[kind]
    if legacy_statements(statements) != (expected,):
        raise RuntimeError(
            "vanilla/KAGE rendered statement changed at %08x" %
            spec["site"])

    fence = (
        "#if defined(__vita__) && "
        "defined(ISAAC_VITA_VANILLA_KAGE_BUNDLE)"
    )
    if kind == "godhead_partition":
        return (
            fence,
            "    /* REPENTOGON: Godhead only queries the ENEMY partition. */",
            "    gpush_generated(c, 0x%xU); "
            "GUEST_STACK_CALLSITE_BARRIER();" %
            VITA_VANILLA_KAGE_GODHEAD_PARTITION,
            "#else",
            "    " + statements[0],
            "#endif",
        )
    if kind == "compatible_stride":
        return (
            fence,
            "    /* REPENTOGON: reuse only a batch with this image stride. */",
            "    {",
            "        const uint32_t _reusable_begin = c->eax;",
            "        const uint32_t _reusable_count = c->ecx;",
            "        const uint32_t _image = (uint32_t)(c->esi - 0x%xU);" %
            VITA_VANILLA_KAGE_REUSABLE_VECTOR_OFFSET,
            "        const uint32_t _vertex_stride = (uint32_t)ld16(",
            "            (uint32_t)(_image + 0x%xU));" %
            VITA_VANILLA_KAGE_IMAGE_STRIDE_OFFSET,
            "        uint32_t _reusable_index = _reusable_count;",
            "        uint32_t _compatible_found = 0U;",
            "        while (_reusable_index != 0U) {",
            "            uint32_t _slot;",
            "            uint32_t _batch;",
            "            --_reusable_index;",
            "            _slot = (uint32_t)(_reusable_begin +",
            "                _reusable_index * 4U);",
            "            _batch = ld32(_slot);",
            "            if (ld32((uint32_t)(_batch + 0x%xU)) ==" %
            VITA_VANILLA_KAGE_BATCH_ELEMENT_SIZE_OFFSET,
            "                    _vertex_stride) {",
            "                const uint32_t _back_slot = (uint32_t)(",
            "                    _reusable_begin +",
            "                    (_reusable_count - 1U) * 4U);",
            "                if (_slot != _back_slot) {",
            "                    const uint32_t _back = ld32(_back_slot);",
            "                    st32(_slot, _back);",
            "                    st32(_back_slot, _batch);",
            "                }",
            "                _compatible_found = 1U;",
            "                break;",
            "            }",
            "        }",
            "        if (_compatible_found == 0U)",
            "            goto L_%08x;" %
            VITA_VANILLA_KAGE_STRIDE_ALLOCATE_RVA,
            "    }",
            "#else",
            "    " + statements[0],
            "#endif",
        )
    return (
        fence,
        "    /* Keep the current image's just-selected batch reusable. */",
        "    if (c->eax != c->edi)",
        "        " + expected,
        "#else",
        "    " + statements[0],
        "#endif",
    )


def vita_vanilla_kage_stride_host_oracle(vertex_stride, batch_strides):
    """Model REPENTOGON's reverse search and swap-with-back contract."""
    batches = [value & 0xFFFFFFFF for value in batch_strides]
    stride = vertex_stride & 0xFFFF
    for index in range(len(batches) - 1, -1, -1):
        if batches[index] == stride:
            batches[index], batches[-1] = batches[-1], batches[index]
            return True, tuple(batches)
    return False, tuple(batches)


def vita_vanilla_kage_invalidation_host_oracle(
        previous_image, current_image):
    """Model the original NULL test plus REPENTOGON's same-image guard."""
    previous = previous_image & 0xFFFFFFFF
    current = current_image & 0xFFFFFFFF
    return previous != 0 and previous != current


def _vita_anm2_missing_layer_guard_file_sha256(path):
    digest = hashlib.sha256()
    with open(path, "rb") as stream:
        for chunk in iter(lambda: stream.read(1024 * 1024), b""):
            digest.update(chunk)
    return digest.hexdigest()


def vita_anm2_missing_layer_guard_for_body(
        img, root_rva, em, insns, order, body):
    """Select and prove all three ANM2::RenderLayer map-order seams.

    The map result is signed: -1 means that this AnimationData does not carry
    the requested logical layer.  The original Windows binary reads through
    that sentinel and survives only because allocator metadata at p-4 is also
    negative.  This proof deliberately owns the consumer boundary, not the
    allocator, and refuses any PE, CFG, machine or emitted-load drift.
    """
    members = frozenset(order)
    reached = members & VITA_ANM2_MISSING_LAYER_GUARD_SITES
    if not reached:
        return ()
    if (root_rva not in VITA_ANM2_MISSING_LAYER_GUARD_ROOTS or
            reached != VITA_ANM2_MISSING_LAYER_GUARD_SITES):
        raise RuntimeError(
            "unexpected ANM2 missing-layer seam membership at root %08x" %
            root_rva)
    if (img.base != DEFAULT_BASE or
            os.path.getsize(img.path) !=
            VITA_ANM2_MISSING_LAYER_GUARD_PE_SIZE or
            _vita_anm2_missing_layer_guard_file_sha256(img.path) !=
            VITA_ANM2_MISSING_LAYER_GUARD_PE_SHA256):
        raise RuntimeError("ANM2 missing-layer input PE identity changed")

    start = VITA_ANM2_MISSING_LAYER_GUARD_ROOT_RVA
    end = VITA_ANM2_MISSING_LAYER_GUARD_END_RVA
    raw = img.code_at(start, end - start)
    decoded = tuple(T.CS.disasm(raw, start))
    decoded_by_rva = {ins.address: ins for ins in decoded}
    emitted_by_rva = {
        ins.address: legacy_statements(statements) for ins, statements in body
    }
    semantic_load_sites = tuple(
        ins.address for ins in decoded
        if (ins.mnemonic == "mov" and
            ins.op_str == "ecx, dword ptr [edx + edi*4 + 0x38]")
    )
    expected_load_sites = tuple(
        spec["site"] for spec in VITA_ANM2_MISSING_LAYER_GUARD_SPECS
    )

    shared_jump = decoded_by_rva.get(0x000052BF)
    shared_jump_operand = (
        shared_jump.operands[0] if shared_jump is not None and
        len(shared_jump.operands) == 1 else None
    )
    shared_fallthrough = decoded_by_rva.get(0x0000530B)
    final_ret = decoded_by_rva.get(VITA_ANM2_MISSING_LAYER_GUARD_LAST_RVA)
    if (hashlib.sha256(raw).hexdigest() !=
            VITA_ANM2_MISSING_LAYER_GUARD_BODY_SHA256 or
            len(decoded) != VITA_ANM2_MISSING_LAYER_GUARD_INSNS or
            sum(ins.size for ins in decoded) != len(raw) or
            not order or order[0] != start or
            order[-1] != VITA_ANM2_MISSING_LAYER_GUARD_LAST_RVA or
            len(order) != VITA_ANM2_MISSING_LAYER_GUARD_INSNS or
            rva_sequence_sha256(order) !=
            VITA_ANM2_MISSING_LAYER_GUARD_ORDER_SHA256 or
            semantic_load_sites != expected_load_sites or
            final_ret is None or final_ret.mnemonic != "ret" or
            final_ret.op_str != "0x10" or
            shared_jump is None or shared_jump.mnemonic != "jmp" or
            shared_jump_operand is None or
            shared_jump_operand.type != T.cx.X86_OP_IMM or
            (shared_jump_operand.imm & 0xFFFFFFFF) != 0x0000530E or
            shared_fallthrough is None or
            shared_fallthrough.mnemonic != "mov" or
            shared_fallthrough.op_str != "eax, dword ptr [esi + 0x58]" or
            emitted_by_rva.get(0x000052BB) !=
            (VITA_ANM2_MISSING_LAYER_GUARD_PUSH_EAX_STATEMENT,) or
            emitted_by_rva.get(0x0000530A) !=
            (VITA_ANM2_MISSING_LAYER_GUARD_PUSH_EAX_STATEMENT,)):
        raise RuntimeError("ANM2 missing-layer owner/CFG identity changed")

    for spec in VITA_ANM2_MISSING_LAYER_GUARD_SPECS:
        site = spec["site"]
        load = insns.get(site)
        window = img.code_at(site, spec["window_end"] - site)
        if (load is None or load.mnemonic != "mov" or
                load.op_str !=
                "ecx, dword ptr [edx + edi*4 + 0x38]" or
                bytes(load.bytes) !=
                VITA_ANM2_MISSING_LAYER_GUARD_LOAD_MACHINE or
                emitted_by_rva.get(site) !=
                (VITA_ANM2_MISSING_LAYER_GUARD_LOAD_STATEMENT,) or
                spec["next"] not in members or
                spec["skip"] not in em.labels or
                hashlib.sha256(window).hexdigest() !=
                spec["window_sha256"]):
            raise RuntimeError(
                "ANM2 missing-layer machine/emission changed at %08x" % site)
    if (tuple(spec["pending_stack_bytes"]
              for spec in VITA_ANM2_MISSING_LAYER_GUARD_SPECS) !=
            (0, 0, 4)):
        raise RuntimeError("ANM2 missing-layer pending-stack contract changed")
    return VITA_ANM2_MISSING_LAYER_GUARD_SPECS


def render_vita_anm2_missing_layer_guard(spec):
    """Render one post-map-load guard from the validated frozen spec."""
    if spec not in VITA_ANM2_MISSING_LAYER_GUARD_SPECS:
        raise RuntimeError("unknown ANM2 missing-layer guard specification")
    pending = spec["pending_stack_bytes"]
    if pending not in (0, 4):
        raise RuntimeError("unsupported ANM2 missing-layer stack delta")
    lines = [
        "#if defined(ISAAC_VITA_ANM2_MISSING_LAYER_GUARD)",
        "    /* Vita: -1 means this animation has no requested layer. */",
        "    if ((int32_t)c->ecx < 0) {",
    ]
    if pending:
        lines.append(
            "        if (!guest_stack_adjust_generated(c, %dU)) return;" %
            pending)
        lines.append("        GUEST_STACK_CALLSITE_BARRIER();")
    lines.extend((
        "        goto L_%08x;" % spec["skip"],
        "    }",
        "#endif",
    ))
    return tuple(lines)


def vita_anm2_missing_layer_guard_host_oracle(
        spec, layer_order, guest_esp):
    """Model the generated signed test for the focused host/codegen oracle."""
    if spec not in VITA_ANM2_MISSING_LAYER_GUARD_SPECS:
        raise RuntimeError("unknown ANM2 missing-layer guard specification")
    order_u32 = layer_order & 0xFFFFFFFF
    if order_u32 < 0x80000000:
        return None, guest_esp & 0xFFFFFFFF
    return (spec["skip"],
            (guest_esp + spec["pending_stack_bytes"]) & 0xFFFFFFFF)


def _vita_renderframe_direct_call_xrefs(img, target_rva):
    """Return every raw rel32 CALL to one physical RVA in `.text`."""
    found = []
    for site in range(img.text_rva, img.text_end - 4):
        if img.mem[site] != 0xE8:
            continue
        displacement = int.from_bytes(
            img.code_at(site + 1, 4), "little", signed=True)
        if ((site + 5 + displacement) & 0xFFFFFFFF) == target_rva:
            found.append(site)
    return tuple(found)


def _vita_renderframe_linear_body(
        img, start, end, expected_insns, expected_sha256, description):
    raw = img.code_at(start, end - start)
    decoded = tuple(T.CS.disasm(raw, start))
    if (hashlib.sha256(raw).hexdigest() != expected_sha256 or
            len(decoded) != expected_insns or
            sum(ins.size for ins in decoded) != len(raw)):
        raise RuntimeError(
            "RenderFrame fast-path %s identity changed" % description)
    return decoded


def _vita_renderframe_require_insns(decoded, expected, description):
    """Make the fields/calls behind a body hash reviewable and executable."""
    by_rva = {ins.address: ins for ins in decoded}
    for rva, mnemonic, op_str in expected:
        ins = by_rva.get(rva)
        if (ins is None or ins.mnemonic != mnemonic or
                ins.op_str != op_str):
            raise RuntimeError(
                "RenderFrame fast-path %s semantics changed at %08x" %
                (description, rva))


def _vita_renderframe_original_call_statement(spec):
    return (
        "gpush_generated(c, 0x%xU); GUEST_STACK_CALLSITE_BARRIER(); "
        "sub_%08x(c);" %
        (spec["next"], VITA_RENDERFRAME_FASTPATH_GETTER_RVA)
    )


def _vita_renderframe_prove_pure_consumer(img, decoded_by_rva, spec):
    """Pin the lifetime/ABI boundary after one borrowed return value.

    EAX is the only defined getter result and the generated branch reproduces
    it.  These exact continuations overwrite ECX before its next use, do not
    read EDX or incoming flags before another call/definition, and expose the
    borrowed image only to a NULL test or GetWidth/GetHeight.  In particular,
    the five virtual Render consumers are intentionally absent.
    """
    raw = img.code_at(spec["next"], spec["consumer_end"] - spec["next"])
    if hashlib.sha256(raw).hexdigest() != spec["consumer_sha256"]:
        raise RuntimeError(
            "RenderFrame fast-path %s consumer changed" % spec["consumer"])

    def has(rva, mnemonic, op_str):
        ins = decoded_by_rva.get(rva)
        return (ins is not None and ins.mnemonic == mnemonic and
                ins.op_str == op_str)

    kind = spec["consumer"]
    if kind == "null-test":
        proved = (
            has(0x00003EFE, "lea", "ecx, [ebp - 0x158]") and
            has(0x00003F04, "mov", "esi, dword ptr [eax]") and
            has(0x00003F06, "call", "0x7790") and
            has(0x00003F0B, "test", "esi, esi") and
            has(0x00003F0D, "je", "0x4731")
        )
    elif kind == "get-width":
        proved = (
            has(0x00004363, "mov", "ecx, dword ptr [eax]") and
            has(0x00004365, "mov", "eax, dword ptr [ecx]") and
            has(0x00004367, "mov", "eax, dword ptr [eax + 0x30]") and
            has(0x0000436A, "call", "eax") and
            has(0x00004390, "mov", "ecx, dword ptr [ebp - 0x15c]") and
            has(0x00004396, "test", "ecx, ecx")
        )
    elif kind == "get-height":
        proved = (
            has(0x000043D6, "mov", "ecx, dword ptr [eax]") and
            has(0x000043D8, "mov", "eax, dword ptr [ecx]") and
            has(0x000043DA, "mov", "eax, dword ptr [eax + 0x34]") and
            has(0x000043DD, "call", "eax") and
            has(0x00004403, "mov", "ecx, dword ptr [ebp - 0x154]") and
            has(0x00004409, "test", "ecx, ecx")
        )
    elif kind == "final-size-helper":
        proved = (
            has(0x000046F9, "push", "esi") and
            has(0x000046FA, "lea", "ecx, [ebp - 0x12c]") and
            has(0x00004700, "call", "0x25af60")
        )
    else:
        raise RuntimeError(
            "unknown RenderFrame fast-path consumer %r" % kind)
    if not proved:
        raise RuntimeError(
            "RenderFrame fast-path %s semantics changed" % kind)


def vita_renderframe_fastpath_for_body(
        img, root_rva, em, insns, order, body):
    """Prove all nine J835 getter calls and select four pure consumers.

    The generated branch never reimplements rendering.  It only materializes
    the same two-word temporary without reference churn when a native helper
    proves that GetSpriteSheet would perform no sampler update and that
    releasing the temporary would have no observer side effect.
    """
    members = frozenset(order)
    reached = members & VITA_RENDERFRAME_FASTPATH_SITES
    if not reached:
        return ()
    if (root_rva not in VITA_RENDERFRAME_FASTPATH_ROOTS or
            reached != VITA_RENDERFRAME_FASTPATH_SITES):
        raise RuntimeError(
            "unexpected RenderFrame fast-path seam membership at root %08x" %
            root_rva)
    if (img.base != DEFAULT_BASE or
            os.path.getsize(img.path) !=
            VITA_RENDERFRAME_FASTPATH_PE_SIZE or
            _vita_anm2_missing_layer_guard_file_sha256(img.path) !=
            VITA_RENDERFRAME_FASTPATH_PE_SHA256):
        raise RuntimeError("RenderFrame fast-path input PE identity changed")

    raw = img.code_at(
        VITA_RENDERFRAME_FASTPATH_ROOT_RVA,
        VITA_RENDERFRAME_FASTPATH_END_RVA -
        VITA_RENDERFRAME_FASTPATH_ROOT_RVA,
    )
    decoded = tuple(T.CS.disasm(
        raw, VITA_RENDERFRAME_FASTPATH_ROOT_RVA))
    decoded_by_rva = {ins.address: ins for ins in decoded}
    emitted_by_rva = {
        ins.address: legacy_statements(statements) for ins, statements in body
    }
    calls = tuple(
        ins.address for ins in decoded
        if (ins.mnemonic == "call" and ins.op_str ==
            "0x%x" % VITA_RENDERFRAME_FASTPATH_GETTER_RVA)
    )
    final_ret = decoded_by_rva.get(VITA_RENDERFRAME_FASTPATH_LAST_RVA)
    if (hashlib.sha256(raw).hexdigest() !=
            VITA_RENDERFRAME_FASTPATH_BODY_SHA256 or
            len(decoded) != VITA_RENDERFRAME_FASTPATH_INSNS or
            sum(ins.size for ins in decoded) != len(raw) or
            not order or
            order[0] != VITA_RENDERFRAME_FASTPATH_ROOT_RVA or
            order[-1] != VITA_RENDERFRAME_FASTPATH_LAST_RVA or
            len(order) != VITA_RENDERFRAME_FASTPATH_INSNS or
            rva_sequence_sha256(order) !=
            VITA_RENDERFRAME_FASTPATH_ORDER_SHA256 or
            calls != VITA_RENDERFRAME_FASTPATH_ALL_GETTER_SITES or
            rva_sequence_sha256(calls) !=
            VITA_RENDERFRAME_FASTPATH_CALL_ORDER_SHA256 or
            final_ret is None or final_ret.mnemonic != "ret" or
            final_ret.op_str != "0x14"):
        raise RuntimeError("RenderFrame fast-path owner/CFG identity changed")

    # Freeze whole-program ownership too.  All known uses are ordinary direct
    # thiscall invocations; no relocated function pointer can enter the body
    # with a different threading/lifetime convention.
    caller_sites = _vita_renderframe_direct_call_xrefs(
        img, VITA_RENDERFRAME_FASTPATH_ROOT_RVA)
    address_refs = tuple(
        rva for rva in sorted(img.reloc_rvas)
        if int.from_bytes(img.code_at(rva, 4), "little") ==
        img.va(VITA_RENDERFRAME_FASTPATH_ROOT_RVA)
    )
    if (len(caller_sites) != VITA_RENDERFRAME_FASTPATH_CALLER_COUNT or
            rva_sequence_sha256(caller_sites) !=
            VITA_RENDERFRAME_FASTPATH_CALLER_ORDER_SHA256 or
            address_refs):
        raise RuntimeError(
            "RenderFrame fast-path whole-program caller ownership changed")

    getter = _vita_renderframe_linear_body(
        img,
        VITA_RENDERFRAME_FASTPATH_GETTER_RVA,
        VITA_RENDERFRAME_FASTPATH_GETTER_END_RVA,
        VITA_RENDERFRAME_FASTPATH_GETTER_INSNS,
        VITA_RENDERFRAME_FASTPATH_GETTER_BODY_SHA256,
        "GetSpriteSheet body",
    )
    if (rva_sequence_sha256(tuple(ins.address for ins in getter)) !=
            VITA_RENDERFRAME_FASTPATH_GETTER_ORDER_SHA256 or
            tuple(ins.address for ins in getter
                  if ins.mnemonic == "call" and
                  ins.op_str == "0x%x" %
                  VITA_RENDERFRAME_FASTPATH_SMART_COPY_RVA) != (0x0000358F,)):
        raise RuntimeError(
            "RenderFrame fast-path GetSpriteSheet semantics changed")
    _vita_renderframe_require_insns(getter, (
        (0x00003546, "mov", "ecx, dword ptr [esi + 0x94]"),
        (0x0000354D, "lea", "edi, [esi + 0x94]"),
        (0x00003557, "mov", "edx, dword ptr [esi + 0x20]"),
        (0x0000355A, "cmp", "dword ptr [ecx + 0x24], edx"),
        (0x00003562, "cmp", "eax, dword ptr [esi + 0x24]"),
        (0x0000356D, "call", "dword ptr [eax + 0x40]"),
        (0x00003572, "mov", "edx, dword ptr [esi + 0x28]"),
        (0x00003575, "cmp", "dword ptr [ecx + 0x2c], edx"),
        (0x0000357D, "cmp", "eax, dword ptr [esi + 0x2c]"),
        (0x00003588, "call", "dword ptr [eax + 0x44]"),
        (0x0000358F, "call", "0x78a0"),
    ), "GetSpriteSheet fields")
    smart_copy = _vita_renderframe_linear_body(
        img,
        VITA_RENDERFRAME_FASTPATH_SMART_COPY_RVA,
        VITA_RENDERFRAME_FASTPATH_SMART_COPY_END_RVA,
        VITA_RENDERFRAME_FASTPATH_SMART_COPY_INSNS,
        VITA_RENDERFRAME_FASTPATH_SMART_COPY_BODY_SHA256,
        "SmartPointer copy body",
    )
    _vita_renderframe_require_insns(smart_copy, (
        (0x000078B8, "mov", "edi, dword ptr [eax + 4]"),
        (0x000078BB, "mov", "ebx, dword ptr [eax]"),
        (0x000078C5, "mov", "eax, dword ptr [eax + 4]"),
        (0x000078C8, "call", "eax"),
        (0x000078EF, "mov", "dword ptr [esi + 4], edi"),
        (0x000078F2, "mov", "dword ptr [esi], ebx"),
    ), "SmartPointer copy")
    smart_dtor = _vita_renderframe_linear_body(
        img,
        VITA_RENDERFRAME_FASTPATH_SMART_DTOR_RVA,
        VITA_RENDERFRAME_FASTPATH_SMART_DTOR_END_RVA,
        VITA_RENDERFRAME_FASTPATH_SMART_DTOR_INSNS,
        VITA_RENDERFRAME_FASTPATH_SMART_DTOR_BODY_SHA256,
        "SmartPointer destructor body",
    )
    _vita_renderframe_require_insns(smart_dtor, (
        (0x000077B5, "mov", "ecx, dword ptr [esi + 4]"),
        (0x000077BE, "mov", "eax, dword ptr [eax + 0xc]"),
        (0x000077C1, "call", "eax"),
        (0x000077C7, "mov", "eax, dword ptr [0x307fd62c]"),
    ), "SmartPointer destructor")
    release_callback = _vita_renderframe_linear_body(
        img,
        VITA_RENDERFRAME_FASTPATH_RELEASE_CALLBACK_RVA,
        VITA_RENDERFRAME_FASTPATH_RELEASE_CALLBACK_END_RVA,
        VITA_RENDERFRAME_FASTPATH_RELEASE_CALLBACK_INSNS,
        VITA_RENDERFRAME_FASTPATH_RELEASE_CALLBACK_BODY_SHA256,
        "release-observer callback body",
    )
    _vita_renderframe_require_insns(release_callback, (
        (0x0056D8C4, "mov", "ebx, dword ptr [ebp + 8]"),
        (0x0056D8C8, "mov", "esi, dword ptr [ebx + 4]"),
        (0x0056D8CF, "mov", "eax, dword ptr [esi + 8]"),
        (0x0056D8D3, "lea", "edi, [esi + 8]"),
        (0x0056D8DA, "call", "dword ptr [eax + 0xc]"),
        (0x0056D8E1, "movzx", "esi, word ptr [esi + 4]"),
        (0x0056D8E5, "call", "dword ptr [eax + 0x10]"),
        (0x0056D8E9, "cmp", "esi, 1"),
        (0x0056D8EC, "jne", "0x56d8f5"),
        (0x0056D8EE, "push", "dword ptr [ebx]"),
        (0x0056D8F0, "call", "0x56d220"),
        (0x0056D8F8, "ret", ""),
    ), "release-observer callback")
    decrement = _vita_renderframe_linear_body(
        img,
        VITA_RENDERFRAME_FASTPATH_DECREMENT_RVA,
        VITA_RENDERFRAME_FASTPATH_DECREMENT_END_RVA,
        VITA_RENDERFRAME_FASTPATH_DECREMENT_INSNS,
        VITA_RENDERFRAME_FASTPATH_DECREMENT_BODY_SHA256,
        "reference decrement body",
    )
    _vita_renderframe_require_insns(decrement, (
        (0x00007AFF, "movzx", "eax, word ptr [esi + 4]"),
        (0x00007B08, "dec", "eax"),
        (0x00007B09, "mov", "word ptr [esi + 4], ax"),
        (0x00007B1B, "mov", "ecx, dword ptr [esi + 0x14]"),
    ), "reference decrement")
    increment = _vita_renderframe_linear_body(
        img,
        VITA_RENDERFRAME_FASTPATH_INCREMENT_RVA,
        VITA_RENDERFRAME_FASTPATH_INCREMENT_END_RVA,
        VITA_RENDERFRAME_FASTPATH_INCREMENT_INSNS,
        VITA_RENDERFRAME_FASTPATH_INCREMENT_BODY_SHA256,
        "reference increment body",
    )
    _vita_renderframe_require_insns(increment, (
        (0x00007B5C, "call", "dword ptr [eax + 0xc]"),
        (0x00007B5F, "inc", "word ptr [esi + 4]"),
        (0x00007B6B, "jmp", "dword ptr [eax + 0x10]"),
    ), "reference increment")
    increment_nonzero = _vita_renderframe_linear_body(
        img,
        VITA_RENDERFRAME_FASTPATH_INCREMENT_NONZERO_RVA,
        VITA_RENDERFRAME_FASTPATH_INCREMENT_NONZERO_END_RVA,
        VITA_RENDERFRAME_FASTPATH_INCREMENT_NONZERO_INSNS,
        VITA_RENDERFRAME_FASTPATH_INCREMENT_NONZERO_BODY_SHA256,
        "nonzero reference increment body",
    )
    _vita_renderframe_require_insns(increment_nonzero, (
        (0x00007B7C, "call", "dword ptr [eax + 0xc]"),
        (0x00007B88, "cmp", "word ptr [edi + 4], 0"),
        (0x00007B96, "call", "dword ptr [eax]"),
        (0x00007B9C, "call", "dword ptr [eax + 8]"),
    ), "nonzero reference increment")
    final_consumer = _vita_renderframe_linear_body(
        img,
        VITA_RENDERFRAME_FASTPATH_FINAL_CONSUMER_RVA,
        VITA_RENDERFRAME_FASTPATH_FINAL_CONSUMER_END_RVA,
        VITA_RENDERFRAME_FASTPATH_FINAL_CONSUMER_INSNS,
        VITA_RENDERFRAME_FASTPATH_FINAL_CONSUMER_BODY_SHA256,
        "final by-value consumer body",
    )
    final_calls = tuple(
        (ins.address, ins.op_str) for ins in final_consumer
        if ins.mnemonic == "call"
    )
    if final_calls != (
            (0x0025B00F, "dword ptr [eax + 0x30]"),
            (0x0025B045, "dword ptr [eax + 0x34]"),
            (0x0025B0BC, "eax"),
            (0x0025B0CF, "eax")):
        raise RuntimeError(
            "RenderFrame fast-path final pure-consumer calls changed")

    # Both local SmartPointer destruction and the final by-value consumer
    # consult this same observer slot after decrement.  KAGE installs the
    # exact callback pinned above: it locks the counter, observes the
    # post-release strong count and performs its sole image-cache effect only
    # when that count is one.  The runtime helper accepts that callback only
    # above this observable edge; zero remains the only other accepted value.
    observer_operand = "dword ptr [0x%x]" % img.va(
        VITA_RENDERFRAME_FASTPATH_RELEASE_OBSERVER_RVA)
    release_init = img.code_at(
        VITA_RENDERFRAME_FASTPATH_RELEASE_INIT_RVA,
        len(VITA_RENDERFRAME_FASTPATH_RELEASE_INIT_MACHINE))
    release_init_relocs = tuple(sorted(
        rva for rva in img.reloc_rvas
        if VITA_RENDERFRAME_FASTPATH_RELEASE_INIT_RVA <= rva <
        VITA_RENDERFRAME_FASTPATH_RELEASE_INIT_RVA + len(release_init)))
    if (release_init != VITA_RENDERFRAME_FASTPATH_RELEASE_INIT_MACHINE or
            release_init_relocs != (
                VITA_RENDERFRAME_FASTPATH_RELEASE_INIT_RVA + 2,
                VITA_RENDERFRAME_FASTPATH_RELEASE_INIT_RVA + 6) or
            int.from_bytes(release_init[2:6], "little") !=
            img.va(VITA_RENDERFRAME_FASTPATH_RELEASE_OBSERVER_RVA) or
            int.from_bytes(release_init[6:10], "little") !=
            img.va(VITA_RENDERFRAME_FASTPATH_RELEASE_CALLBACK_RVA) or
            sum(observer_operand in ins.op_str for ins in smart_dtor) != 1 or
            sum(observer_operand in ins.op_str for ins in final_consumer) != 1 or
            int.from_bytes(img.code_at(
                VITA_RENDERFRAME_FASTPATH_RELEASE_OBSERVER_RVA, 4),
                "little") != 0 or
            VITA_RENDERFRAME_FASTPATH_RELEASE_OBSERVER_RVA in img.reloc_rvas):
        raise RuntimeError(
            "RenderFrame fast-path release-observer contract changed")

    # RTTI/vftable ownership proves the fields read by the native helper:
    # strong count +4 and owned object +14 are consumed by the exact pinned
    # DecrementReference body above.  Every vftable slot is a PE relocation to
    # the corresponding pinned implementation.
    for index, target in enumerate(
            VITA_RENDERFRAME_FASTPATH_COUNTER_VFTABLE_SLOTS):
        slot = VITA_RENDERFRAME_FASTPATH_COUNTER_VFTABLE_RVA + index * 4
        value = int.from_bytes(img.code_at(slot, 4), "little")
        if (slot not in img.reloc_rvas or value != img.va(target)):
            raise RuntimeError(
                "RenderFrame fast-path counter vftable changed at slot %d" %
                index)

    for spec in VITA_RENDERFRAME_FASTPATH_SPECS:
        site = spec["site"]
        call = insns.get(site)
        state = insns.get(spec["state"])
        push = insns.get(spec["push"])
        original = _vita_renderframe_original_call_statement(spec)
        window = img.code_at(
            spec["window_start"], spec["next"] - spec["window_start"])
        if (call is None or call.mnemonic != "call" or
                call.op_str != "0x%x" %
                VITA_RENDERFRAME_FASTPATH_GETTER_RVA or
                state is None or state.mnemonic != "mov" or
                state.op_str != "ecx, edi" or
                emitted_by_rva.get(spec["state"]) !=
                (VITA_RENDERFRAME_FASTPATH_STATE_STATEMENT,) or
                push is None or push.mnemonic != "push" or
                emitted_by_rva.get(spec["push"]) !=
                (spec["push_statement"],) or
                emitted_by_rva.get(site) != (original,) or
                spec["next"] != site + call.size or
                spec["next"] not in members or
                hashlib.sha256(window).hexdigest() !=
                spec["window_sha256"]):
            raise RuntimeError(
                "RenderFrame fast-path machine/emission changed at %08x" %
                site)
        _vita_renderframe_prove_pure_consumer(img, decoded_by_rva, spec)
        edge_rva = spec.get("state_edge")
        if edge_rva is not None:
            edge = insns.get(edge_rva)
            operand = (edge.operands[0] if edge is not None and
                       len(edge.operands) == 1 else None)
            if (edge is None or edge.mnemonic != "je" or
                    operand is None or operand.type != T.cx.X86_OP_IMM or
                    (operand.imm & 0xFFFFFFFF) != 0x0000465B or
                    0x0000465B not in em.labels):
                raise RuntimeError(
                    "RenderFrame fast-path inherited-this edge changed")
    return VITA_RENDERFRAME_FASTPATH_SPECS


def render_vita_renderframe_fastpath(spec, statements, image_base):
    """Render one proved fallback-preserving GetSpriteSheet acquisition."""
    if spec not in VITA_RENDERFRAME_FASTPATH_SPECS:
        raise RuntimeError("unknown RenderFrame fast-path specification")
    original = _vita_renderframe_original_call_statement(spec)
    if legacy_statements(statements) != (original,):
        raise RuntimeError(
            "RenderFrame fast-path original call emission changed")
    if image_base not in (DEFAULT_BASE, 0x98000000):
        raise RuntimeError(
            "RenderFrame fast-path unsupported emission image base")
    counter_vftable = (
        image_base + VITA_RENDERFRAME_FASTPATH_COUNTER_VFTABLE_RVA
    ) & 0xFFFFFFFF
    observer_slot = (
        image_base + VITA_RENDERFRAME_FASTPATH_RELEASE_OBSERVER_RVA
    ) & 0xFFFFFFFF
    observer_callback = (
        image_base + VITA_RENDERFRAME_FASTPATH_RELEASE_CALLBACK_RVA
    ) & 0xFFFFFFFF
    return (
        "#if defined(__vita__) && defined(ISAAC_VITA_RENDERFRAME_FASTPATH)",
        "    {",
        "        uint32_t _guest_vita_renderframe_image = 0U;",
        "        if (isaac_vita_renderframe_try_borrow(",
        "                c->ecx, 0x%08xU, 0x%08xU, 0x%08xU," %
        (counter_vftable, observer_slot, observer_callback),
        "                &_guest_vita_renderframe_image)) {",
        "            const uint32_t _guest_vita_renderframe_output =",
        "                ld32(c->esp);",
        "            st32(_guest_vita_renderframe_output,",
        "                 _guest_vita_renderframe_image);",
        "            st32(_guest_vita_renderframe_output + 4U, 0U);",
        "            c->eax = _guest_vita_renderframe_output;",
        "            if (!guest_stack_adjust_generated(c, 4U)) return;",
        "            GUEST_STACK_CALLSITE_BARRIER();",
        "            goto L_%08x;" % spec["next"],
        "        }",
        "    }",
        "#endif",
        "    " + statements[0],
    )


def _vita_refcount_direct_original(edge, instruction):
    site, _target, _mnemonic, _op_str, source, tail = edge
    if tail:
        return ("GUEST_FLAGS_FLUSH(c); guest_call(c, %s); return;" % source,)
    return (
        "{ uint32_t _target = %s;" % source,
        "  gpush_generated(c, 0x%xU);" % (site + instruction.size),
        "  GUEST_STACK_CALLSITE_BARRIER();",
        "  guest_call(c, _target);",
        "}",
    )


def vita_refcount_direct_edges_for_body(
        img, root_rva, insns, order, body):
    """Authenticate the five shared ImageBase reference-count owners.

    Every selected edge remains target-guarded.  The proof establishes that
    this frozen PE's render path reaches the owners and that generator drift
    cannot silently move a seam; it does not assume every caller has one
    vtable type.
    """
    owner = VITA_REFCOUNT_DIRECT_EDGE_ROOT_SPECS.get(root_rva)
    if owner is None:
        return ()
    if (img.base != DEFAULT_BASE or
            os.path.getsize(img.path) != VITA_RENDERFRAME_FASTPATH_PE_SIZE or
            _vita_anm2_missing_layer_guard_file_sha256(img.path) !=
            VITA_RENDERFRAME_FASTPATH_PE_SHA256):
        raise RuntimeError("ReferenceCount direct-edge input PE changed")

    raw = img.code_at(root_rva, owner["end"] - root_rva)
    decoded = tuple(T.CS.disasm(raw, root_rva))
    expected_sites = tuple(edge[0] for edge in owner["edges"])
    reached_sites = tuple(
        instruction.address for instruction, _statements in body
        if instruction.address in VITA_REFCOUNT_DIRECT_EDGE_SITES
    )
    if (hashlib.sha256(raw).hexdigest() != owner["body_sha256"] or
            len(decoded) != owner["insns"] or
            sum(instruction.size for instruction in decoded) != len(raw) or
            len(order) != owner["insns"] or not order or
            order[0] != root_rva or order[-1] != owner["last"] or
            rva_sequence_sha256(order) != owner["order_sha256"] or
            reached_sites != expected_sites):
        raise RuntimeError(
            "ReferenceCount direct-edge body/CFG changed at %08x" %
            root_rva)

    # The exact ImageBase counter used by RenderFrame selects these outer
    # owners.  Its embedded CriticalSection selects the two mutex wrappers.
    for index, target in enumerate(
            VITA_RENDERFRAME_FASTPATH_COUNTER_VFTABLE_SLOTS):
        slot = VITA_RENDERFRAME_FASTPATH_COUNTER_VFTABLE_RVA + index * 4
        if (slot not in img.reloc_rvas or
                int.from_bytes(img.code_at(slot, 4), "little") !=
                img.va(target)):
            raise RuntimeError(
                "ReferenceCount direct-edge counter vtable changed")
    mutex_slots = (
        (0x0075D654, VITA_REFCOUNT_DIRECT_MUTEX_ENTER_RVA),
        (0x0075D658, VITA_REFCOUNT_DIRECT_MUTEX_LEAVE_RVA),
    )
    for slot, target in mutex_slots:
        if (slot not in img.reloc_rvas or
                int.from_bytes(img.code_at(slot, 4), "little") !=
                img.va(target)):
            raise RuntimeError(
                "ReferenceCount direct-edge mutex vtable changed")

    emitted_by_rva = {
        instruction.address: (instruction, legacy_statements(statements))
        for instruction, statements in body
    }
    selected = []
    for edge in owner["edges"]:
        site, target, mnemonic, op_str, source, tail = edge
        pair = emitted_by_rva.get(site)
        instruction = pair[0] if pair is not None else None
        statements = pair[1] if pair is not None else ()
        if (instruction is None or instruction.mnemonic != mnemonic or
                instruction.op_str != op_str or
                statements !=
                _vita_refcount_direct_original(edge, instruction)):
            raise RuntimeError(
                "ReferenceCount direct-edge machine/emission changed at "
                "%08x" % site)
        selected.append({
            "site": site,
            "target": target,
            "source": source,
            "tail": tail,
            "edge": edge,
        })
    return tuple(selected)


def render_vita_refcount_direct_edge(spec, statements, instruction):
    """Render one exact-target route with the original guest_call fallback."""
    edge = spec["edge"]
    original = _vita_refcount_direct_original(edge, instruction)
    if legacy_statements(statements) != original:
        raise RuntimeError(
            "ReferenceCount direct-edge original emission changed")
    target = spec["target"]
    lines = [
        "#if defined(__vita__)",
        "    { uint32_t _target = %s;" % spec["source"],
    ]
    if not spec["tail"]:
        lines.extend((
            "      gpush_generated(c, 0x%xU);" %
            (spec["site"] + instruction.size),
            "      GUEST_STACK_CALLSITE_BARRIER();",
        ))
    lines.extend((
        "      if (guest_direct_translated_target(",
        "              _target, 0x%08xU)) {" % target,
        "          GUEST_PHASE_PROFILE_NOTE_CALL();",
        "          GUEST_PHASE_PROFILE_NOTE_LOOKUP();",
        "#if defined(ISAAC_VITA_PHASE_PROFILE)",
        "          guest_phase_profile_note_lookup_cache_hit();",
        "#endif",
        "          sub_%08x(c);" % target,
        "      } else",
        "          guest_call(c, _target);",
    ))
    if spec["tail"]:
        lines.append("      return;")
    lines.extend((
        "    }",
        "#else",
    ))
    lines.extend("    " + statement for statement in statements)
    lines.append("#endif")
    return tuple(lines)


def _vita_refcount_sync_iat_original(site, slot_rva, image_base):
    target_slot = (image_base + slot_rva) & 0xFFFFFFFF
    target_source = ("(uint32_t)(int32_t)(%d)" %
                     (target_slot - 0x100000000)
                     if target_slot & 0x80000000 else
                     "0x%xU" % target_slot)
    return (
        "{ uint32_t _target = ld32((uint32_t)(%s));" % target_source,
        "  gpush_generated(c, 0x%xU);" % (site + 6),
        "  GUEST_STACK_CALLSITE_BARRIER();",
        "  guest_call(c, _target);",
        "}",
    )


def vita_refcount_sync_iat_for_body(
        img, root_rva, insns, order, body, emit_base):
    """Authenticate the three Enter/Leave IAT sites in refcount wrappers."""
    owner = VITA_REFCOUNT_SYNC_IAT_ROOT_SPECS.get(root_rva)
    if owner is None:
        return ()
    if (img.base != DEFAULT_BASE or
            emit_base not in (DEFAULT_BASE, 0x98000000) or
            os.path.getsize(img.path) != VITA_RENDERFRAME_FASTPATH_PE_SIZE or
            _vita_anm2_missing_layer_guard_file_sha256(img.path) !=
            VITA_RENDERFRAME_FASTPATH_PE_SHA256):
        raise RuntimeError("ReferenceCount sync-IAT input PE changed")

    raw = img.code_at(root_rva, owner["end"] - root_rva)
    decoded = tuple(T.CS.disasm(raw, root_rva))
    decoded_by_rva = {instruction.address: instruction
                      for instruction in decoded}
    expected_sites = tuple(site for site, _slot, _name in owner["sites"])
    reached_sites = tuple(
        instruction.address for instruction, _statements in body
        if instruction.address in VITA_REFCOUNT_SYNC_IAT_SITES
    )
    if (hashlib.sha256(raw).hexdigest() != owner["body_sha256"] or
            len(decoded) != owner["insns"] or
            sum(instruction.size for instruction in decoded) != len(raw) or
            len(order) != owner["insns"] or not order or
            order[0] != root_rva or order[-1] != owner["last"] or
            rva_sequence_sha256(order) != owner["order_sha256"] or
            reached_sites != expected_sites):
        raise RuntimeError(
            "ReferenceCount sync-IAT body/CFG changed at %08x" % root_rva)

    direct_callers = _vita_renderframe_direct_call_xrefs(img, root_rva)
    address_refs = tuple(
        rva for rva in sorted(img.reloc_rvas)
        if int.from_bytes(img.code_at(rva, 4), "little") == img.va(root_rva)
    )
    if (direct_callers != owner["direct_callers"] or
            address_refs != owner["address_refs"]):
        raise RuntimeError(
            "ReferenceCount sync-IAT wrapper ownership changed at %08x" %
            root_rva)

    imports = dict(read_imports(img.path))
    emitted_by_rva = {
        instruction.address: (instruction, legacy_statements(statements))
        for instruction, statements in body
    }
    selected = []
    invalid = (0, T.cx.X86_REG_INVALID)
    for site, slot_rva, import_name in owner["sites"]:
        pair = emitted_by_rva.get(site)
        instruction = pair[0] if pair is not None else None
        statements = pair[1] if pair is not None else ()
        pinned = decoded_by_rva.get(site)
        operand = (instruction.operands[0] if instruction is not None and
                   len(instruction.operands) == 1 else None)
        mem = (operand.mem if operand is not None and
               operand.type == T.cx.X86_OP_MEM else None)
        expected_slot = (emit_base + slot_rva) & 0xFFFFFFFF
        if (instruction is None or instruction.mnemonic != "call" or
                instruction.size != 6 or operand is None or
                operand.size != 4 or mem is None or
                mem.segment not in invalid or mem.base not in invalid or
                mem.index not in invalid or
                (mem.disp & 0xFFFFFFFF) != expected_slot or
                instruction.disp_size != 4 or
                site + instruction.disp_offset not in img.reloc_rvas or
                pinned is None or pinned.mnemonic != "call" or
                bytes(pinned.bytes[:2]) != b"\xff\x15" or
                imports.get(slot_rva) != import_name or
                statements != _vita_refcount_sync_iat_original(
                    site, slot_rva, emit_base)):
            raise RuntimeError(
                "ReferenceCount sync-IAT machine/emission changed at %08x" %
                site)
        selected.append({
            "site": site,
            "slot_rva": slot_rva,
            "import_name": import_name,
        })
    return tuple(selected)


def render_vita_refcount_sync_iat(spec, statements, image_base):
    """Route one exact registered sync IAT target, else preserve guest_call."""
    original = _vita_refcount_sync_iat_original(
        spec["site"], spec["slot_rva"], image_base)
    if legacy_statements(statements) != original:
        raise RuntimeError("ReferenceCount sync-IAT original emission changed")
    lines = [
        "#if defined(__vita__)",
        "    " + original[0],
        "      gpush_generated(c, 0x%xU);" % (spec["site"] + 6),
        "      GUEST_STACK_CALLSITE_BARRIER();",
        "      if (!guest_try_direct_sync_import_call(",
        "              c, _target, 0x%08xU))" % spec["slot_rva"],
        "          guest_call(c, _target);",
        "    }",
        "#else",
    ]
    lines.extend("    " + statement for statement in statements)
    lines.append("#endif")
    return tuple(lines)


def _vita_fxlayers_direct_call_xrefs(img, target_rva):
    """Return every raw rel32 CALL to one physical RVA in `.text`."""
    found = []
    for site in range(img.text_rva, img.text_end - 4):
        if img.mem[site] != 0xE8:
            continue
        displacement = int.from_bytes(
            img.code_at(site + 1, 4), "little", signed=True)
        if ((site + 5 + displacement) & 0xFFFFFFFF) == target_rva:
            found.append(site)
    return tuple(found)


def vita_fxlayers_null_rollback_for_body(
        img, root_rva, em, insns, order, extra_entries, image_base):
    """Select and pin the exact FXLayers::Init NULL-ImageBase edge.

    This is deliberately a producer-boundary seam.  The selected branch is
    reached only after the just-appended lighting record owns the moved smart
    pointer, and before the original failure log/cleanup.  Both translated
    owners share this physical tail, so their exact membership is checked by
    the aggregate generation census below.
    """
    members = frozenset(order)
    site = VITA_FXLAYERS_NULL_ROLLBACK_SITE_RVA
    if site not in members:
        return False
    base_specs = VITA_FXLAYERS_NULL_ROLLBACK_ORDER_SPECS_BY_IMAGE_BASE.get(
        image_base)
    if base_specs is None:
        raise RuntimeError(
            "unsupported FXLayers rollback image base 0x%08x" % image_base)
    spec = base_specs.get(root_rva)
    if spec is None:
        raise RuntimeError(
            "unexpected FXLayers rollback membership at root %08x" %
            root_rva)

    expected_count, expected_first, expected_last, expected_order_hash = spec
    order_hash = rva_sequence_sha256(order)
    destructor_raw = img.code_at(
        VITA_FXLAYERS_DESTRUCTOR_RVA,
        VITA_FXLAYERS_DESTRUCTOR_END_RVA -
        VITA_FXLAYERS_DESTRUCTOR_RVA)
    destructor = tuple(T.CS.disasm(
        destructor_raw, VITA_FXLAYERS_DESTRUCTOR_RVA))
    destructor_order = tuple(ins.address for ins in destructor)

    append_cmp = insns.get(0x004E9687)
    saved_end = insns.get(0x004E96B6)
    image_load = insns.get(0x004E9753)
    image_read = insns.get(VITA_FXLAYERS_NULL_EDGE_RVA)
    image_test = insns.get(0x004E97EF)
    failure_branch = insns.get(0x004E97F1)
    failure_target = (
        failure_branch.operands[0].imm & 0xFFFFFFFF
        if failure_branch is not None and
        len(failure_branch.operands) == 1 and
        failure_branch.operands[0].type == T.cx.X86_OP_IMM else None)

    inbound = []
    for address in order:
        ins = insns.get(address)
        if (ins is None or not ins.mnemonic.startswith("j") or
                len(ins.operands) != 1 or
                ins.operands[0].type != T.cx.X86_OP_IMM):
            continue
        if (ins.operands[0].imm & 0xFFFFFFFF) == site:
            inbound.append(address)

    if (len(order) != expected_count or not order or
            order[0] != expected_first or order[-1] != expected_last or
            order_hash != expected_order_hash or
            len(extra_entries) != VITA_FXLAYERS_EXPECTED_SWITCH_ENTRIES or
            site not in em.labels or
            tuple(inbound) != VITA_FXLAYERS_FAILURE_INBOUND_RVAS or
            canonical_relocated_chunk_sha256(
                img, VITA_FXLAYERS_OWNER_RVA,
                VITA_FXLAYERS_OWNER_END_RVA -
                VITA_FXLAYERS_OWNER_RVA) !=
            VITA_FXLAYERS_OWNER_CANONICAL_SHA256 or
            canonical_relocated_chunk_sha256(
                img, VITA_FXLAYERS_APPEND_WINDOW_RVA,
                VITA_FXLAYERS_APPEND_WINDOW_END_RVA -
                VITA_FXLAYERS_APPEND_WINDOW_RVA) !=
            VITA_FXLAYERS_APPEND_WINDOW_CANONICAL_SHA256 or
            canonical_relocated_chunk_sha256(
                img, VITA_FXLAYERS_SMARTPTR_WINDOW_RVA,
                VITA_FXLAYERS_SMARTPTR_WINDOW_END_RVA -
                VITA_FXLAYERS_SMARTPTR_WINDOW_RVA) !=
            VITA_FXLAYERS_SMARTPTR_WINDOW_CANONICAL_SHA256 or
            canonical_relocated_chunk_sha256(
                img, VITA_FXLAYERS_NULL_EDGE_RVA,
                VITA_FXLAYERS_NULL_EDGE_END_RVA -
                VITA_FXLAYERS_NULL_EDGE_RVA) !=
            VITA_FXLAYERS_NULL_EDGE_CANONICAL_SHA256 or
            canonical_relocated_chunk_sha256(
                img, site,
                VITA_FXLAYERS_FAILURE_LOG_END_RVA - site) !=
            VITA_FXLAYERS_FAILURE_LOG_CANONICAL_SHA256 or
            canonical_relocated_chunk_sha256(
                img, VITA_FXLAYERS_DESTRUCTOR_RVA,
                VITA_FXLAYERS_DESTRUCTOR_END_RVA -
                VITA_FXLAYERS_DESTRUCTOR_RVA) !=
            VITA_FXLAYERS_DESTRUCTOR_CANONICAL_SHA256 or
            len(destructor) != VITA_FXLAYERS_DESTRUCTOR_INSNS or
            not destructor or
            destructor[-1].address != VITA_FXLAYERS_DESTRUCTOR_LAST_RVA or
            sum(ins.size for ins in destructor) != len(destructor_raw) or
            rva_sequence_sha256(destructor_order) !=
            VITA_FXLAYERS_DESTRUCTOR_ORDER_SHA256 or
            _vita_fxlayers_direct_call_xrefs(
                img, VITA_FXLAYERS_OWNER_RVA) !=
            VITA_FXLAYERS_INIT_DIRECT_XREFS or
            _vita_fxlayers_direct_call_xrefs(
                img, VITA_FXLAYERS_DESTRUCTOR_RVA) !=
            VITA_FXLAYERS_DESTRUCTOR_DIRECT_XREFS or
            append_cmp is None or append_cmp.mnemonic != "cmp" or
            append_cmp.op_str != "eax, dword ptr [esi + 0x20]" or
            saved_end is None or saved_end.mnemonic != "mov" or
            saved_end.op_str != "dword ptr [ebp - 0x1013c], eax" or
            image_load is None or image_load.mnemonic != "call" or
            image_load.op_str != "0x4b3340" or
            image_read is None or image_read.mnemonic != "mov" or
            image_read.op_str != "ecx, dword ptr [esi - 0x48]" or
            image_test is None or image_test.mnemonic != "test" or
            image_test.op_str != "ecx, ecx" or
            failure_branch is None or failure_branch.mnemonic != "je" or
            failure_target != site):
        details = {
            "order": (len(order), order[0] if order else None,
                      order[-1] if order else None, order_hash),
            "expected_order": (expected_count, expected_first,
                               expected_last, expected_order_hash),
            "extra_entries": len(extra_entries),
            "site_label": site in em.labels,
            "inbound": tuple(inbound),
            "owner_sha": canonical_relocated_chunk_sha256(
                img, VITA_FXLAYERS_OWNER_RVA,
                VITA_FXLAYERS_OWNER_END_RVA - VITA_FXLAYERS_OWNER_RVA),
            "append_sha": canonical_relocated_chunk_sha256(
                img, VITA_FXLAYERS_APPEND_WINDOW_RVA,
                VITA_FXLAYERS_APPEND_WINDOW_END_RVA -
                VITA_FXLAYERS_APPEND_WINDOW_RVA),
            "smartptr_sha": canonical_relocated_chunk_sha256(
                img, VITA_FXLAYERS_SMARTPTR_WINDOW_RVA,
                VITA_FXLAYERS_SMARTPTR_WINDOW_END_RVA -
                VITA_FXLAYERS_SMARTPTR_WINDOW_RVA),
            "edge_sha": canonical_relocated_chunk_sha256(
                img, VITA_FXLAYERS_NULL_EDGE_RVA,
                VITA_FXLAYERS_NULL_EDGE_END_RVA -
                VITA_FXLAYERS_NULL_EDGE_RVA),
            "failure_sha": canonical_relocated_chunk_sha256(
                img, site, VITA_FXLAYERS_FAILURE_LOG_END_RVA - site),
            "destructor_sha": canonical_relocated_chunk_sha256(
                img, VITA_FXLAYERS_DESTRUCTOR_RVA,
                VITA_FXLAYERS_DESTRUCTOR_END_RVA -
                VITA_FXLAYERS_DESTRUCTOR_RVA),
            "destructor_shape": (
                len(destructor),
                destructor[-1].address if destructor else None,
                sum(ins.size for ins in destructor), len(destructor_raw),
                rva_sequence_sha256(destructor_order)),
            "init_xrefs": _vita_fxlayers_direct_call_xrefs(
                img, VITA_FXLAYERS_OWNER_RVA),
            "destructor_xrefs": _vita_fxlayers_direct_call_xrefs(
                img, VITA_FXLAYERS_DESTRUCTOR_RVA),
            "append_cmp": (append_cmp.mnemonic, append_cmp.op_str)
                if append_cmp is not None else None,
            "saved_end": (saved_end.mnemonic, saved_end.op_str)
                if saved_end is not None else None,
            "image_load": (image_load.mnemonic, image_load.op_str)
                if image_load is not None else None,
            "image_read": (image_read.mnemonic, image_read.op_str)
                if image_read is not None else None,
            "image_test": (image_test.mnemonic, image_test.op_str)
                if image_test is not None else None,
            "failure_branch": (
                failure_branch.mnemonic, failure_branch.op_str,
                failure_target) if failure_branch is not None else None,
        }
        raise RuntimeError(
            "FXLayers rollback owner/append/move/edge/destructor changed: %r"
            % details)
    return True


def vita_ogg_queue_error_cleanup_for_body(
        img, root_rva, em, insns, order):
    """Select the exact unowned Ogg backing on Queue's decoder-error edge.

    The decoder helper writes a non-zero error and returns NULL before the
    node is published.  Queue then frees only the 16-byte node.  The injected
    call uses the same guest free wrapper that releases an active stream's
    transferred backing; PC execution remains byte-semantics-equivalent.
    """
    site = VITA_OGG_QUEUE_ERROR_CLEANUP_SITE_RVA
    if site not in frozenset(order):
        return False
    if root_rva not in VITA_OGG_QUEUE_ERROR_CLEANUP_ROOTS:
        raise RuntimeError(
            "unexpected Ogg Queue cleanup membership at root %08x" %
            root_rva)

    def direct_target(ins):
        operand = (ins.operands[0] if ins is not None and
                   len(ins.operands) == 1 else None)
        if (ins is None or ins.mnemonic != "call" or operand is None or
                operand.type != T.cx.X86_OP_IMM):
            return None
        return operand.imm & 0xFFFFFFFF

    def branch_target(ins):
        operand = (ins.operands[0] if ins is not None and
                   len(ins.operands) == 1 else None)
        if (ins is None or operand is None or
                operand.type != T.cx.X86_OP_IMM):
            return None
        return operand.imm & 0xFFFFFFFF

    inbound = []
    for address in order:
        ins = insns.get(address)
        if (ins is not None and ins.mnemonic.startswith("j") and
                branch_target(ins) == site):
            inbound.append(address)

    decoder_raw = img.code_at(
        VITA_OGG_QUEUE_DECODER_OPEN_RVA,
        VITA_OGG_QUEUE_DECODER_OPEN_END_RVA -
        VITA_OGG_QUEUE_DECODER_OPEN_RVA)
    decoder = tuple(T.CS.disasm(
        decoder_raw, VITA_OGG_QUEUE_DECODER_OPEN_RVA))
    decoder_by_rva = {ins.address: ins for ins in decoder}
    decoder_error_store = decoder_by_rva.get(0x005BD886)
    decoder_error_zero = decoder_by_rva.get(0x005BD898)
    decoder_error_ret = decoder_by_rva.get(0x005BD8A7)
    decoder_success_result = decoder_by_rva.get(0x005BD84E)
    decoder_success_ret = decoder_by_rva.get(0x005BD864)

    free_raw = img.code_at(
        VITA_OGG_QUEUE_FREE_RVA,
        VITA_OGG_QUEUE_FREE_END_RVA - VITA_OGG_QUEUE_FREE_RVA)
    free_decoded = tuple(T.CS.disasm(free_raw, VITA_OGG_QUEUE_FREE_RVA))
    free_jump = free_decoded[0] if len(free_decoded) == 1 else None
    free_bridge_raw = img.code_at(
        VITA_OGG_QUEUE_FREE_BRIDGE_RVA,
        VITA_OGG_QUEUE_FREE_BRIDGE_END_RVA -
        VITA_OGG_QUEUE_FREE_BRIDGE_RVA)
    free_bridge_decoded = tuple(T.CS.disasm(
        free_bridge_raw, VITA_OGG_QUEUE_FREE_BRIDGE_RVA))
    free_bridge_jump = (free_bridge_decoded[0]
                        if len(free_bridge_decoded) == 1 else None)
    free_thunk_raw = img.code_at(
        VITA_OGG_QUEUE_FREE_THUNK_RVA,
        VITA_OGG_QUEUE_FREE_THUNK_END_RVA -
        VITA_OGG_QUEUE_FREE_THUNK_RVA)
    free_thunk_decoded = tuple(T.CS.disasm(
        free_thunk_raw, VITA_OGG_QUEUE_FREE_THUNK_RVA))
    free_thunk = free_thunk_decoded[0] if len(free_thunk_decoded) == 1 else None
    free_thunk_operand = (
        free_thunk.operands[0] if free_thunk is not None and
        len(free_thunk.operands) == 1 else None)

    node_delete_raw = img.code_at(
        VITA_OGG_QUEUE_NODE_DELETE_RVA,
        VITA_OGG_QUEUE_NODE_DELETE_END_RVA -
        VITA_OGG_QUEUE_NODE_DELETE_RVA)
    node_delete = tuple(T.CS.disasm(
        node_delete_raw, VITA_OGG_QUEUE_NODE_DELETE_RVA))
    node_delete_call = next(
        (ins for ins in node_delete if ins.mnemonic == "call"), None)

    allocation_push = insns.get(0x005A23EA)
    allocation_size = insns.get(0x005A23EF)
    allocation_call = insns.get(VITA_OGG_QUEUE_ALLOCATION_CALL_RVA)
    backing_store = insns.get(VITA_OGG_QUEUE_ALLOCATION_RETURN_RVA)
    error_address = insns.get(0x005A23FD)
    buffer_argument = insns.get(0x005A2400)
    error_argument = insns.get(0x005A2406)
    error_clear = insns.get(0x005A2407)
    decoder_call = insns.get(VITA_OGG_QUEUE_DECODER_CALL_RVA)
    decoder_store = insns.get(VITA_OGG_QUEUE_DECODER_RETURN_RVA)
    decoder_stack_cleanup = insns.get(0x005A2415)
    error_load = insns.get(VITA_OGG_QUEUE_ERROR_LOAD_RVA)
    error_test = insns.get(VITA_OGG_QUEUE_ERROR_TEST_RVA)
    error_branch = insns.get(VITA_OGG_QUEUE_ERROR_BRANCH_RVA)
    error_log_call = insns.get(VITA_OGG_QUEUE_ERROR_LOG_CALL_RVA)
    error_log_cleanup = insns.get(0x005A242C)
    node_size_push = insns.get(VITA_OGG_QUEUE_ERROR_CLEANUP_SITE_RVA)
    node_pointer_push = insns.get(0x005A2431)
    node_delete_site = insns.get(VITA_OGG_QUEUE_NODE_DELETE_CALL_RVA)
    node_delete_cleanup = insns.get(0x005A2439)

    if (len(order) != VITA_OGG_QUEUE_ERROR_CLEANUP_INSNS or
            not order or order[0] != VITA_OGG_QUEUE_ERROR_CLEANUP_ROOT_RVA or
            order[-1] != VITA_OGG_QUEUE_ERROR_CLEANUP_LAST_RVA or
            order[-1] + insns[order[-1]].size !=
            VITA_OGG_QUEUE_ERROR_CLEANUP_END_RVA or
            rva_sequence_sha256(order) !=
            VITA_OGG_QUEUE_ERROR_CLEANUP_ORDER_SHA256 or
            site not in em.labels or
            VITA_OGG_QUEUE_SUCCESS_RVA not in em.labels or
            tuple(inbound) != (0x005A23E8,) or
            canonical_relocated_chunk_sha256(
                img, VITA_OGG_QUEUE_ERROR_CLEANUP_ROOT_RVA,
                VITA_OGG_QUEUE_ERROR_CLEANUP_END_RVA -
                VITA_OGG_QUEUE_ERROR_CLEANUP_ROOT_RVA) !=
            VITA_OGG_QUEUE_ERROR_CLEANUP_BODY_SHA256 or
            canonical_relocated_chunk_sha256(
                img, VITA_OGG_QUEUE_ERROR_WINDOW_RVA,
                VITA_OGG_QUEUE_ERROR_WINDOW_END_RVA -
                VITA_OGG_QUEUE_ERROR_WINDOW_RVA) !=
            VITA_OGG_QUEUE_ERROR_WINDOW_SHA256 or
            canonical_relocated_chunk_sha256(
                img, VITA_OGG_QUEUE_DECODER_OPEN_RVA,
                VITA_OGG_QUEUE_DECODER_OPEN_END_RVA -
                VITA_OGG_QUEUE_DECODER_OPEN_RVA) !=
            VITA_OGG_QUEUE_DECODER_OPEN_SHA256 or
            canonical_relocated_chunk_sha256(
                img, VITA_OGG_QUEUE_ACTIVE_BACKING_FREE_RVA,
                VITA_OGG_QUEUE_ACTIVE_BACKING_FREE_END_RVA -
                VITA_OGG_QUEUE_ACTIVE_BACKING_FREE_RVA) !=
            VITA_OGG_QUEUE_ACTIVE_BACKING_FREE_SHA256 or
            hashlib.sha256(node_delete_raw).hexdigest() !=
            VITA_OGG_QUEUE_NODE_DELETE_SHA256 or
            hashlib.sha256(free_raw).hexdigest() !=
            VITA_OGG_QUEUE_FREE_WRAPPER_SHA256 or
            hashlib.sha256(free_bridge_raw).hexdigest() !=
            VITA_OGG_QUEUE_FREE_BRIDGE_SHA256 or
            canonical_relocated_chunk_sha256(
                img, VITA_OGG_QUEUE_FREE_THUNK_RVA,
                VITA_OGG_QUEUE_FREE_THUNK_END_RVA -
                VITA_OGG_QUEUE_FREE_THUNK_RVA) !=
            VITA_OGG_QUEUE_FREE_THUNK_SHA256 or
            _vita_fxlayers_direct_call_xrefs(
                img, VITA_OGG_QUEUE_DECODER_OPEN_RVA) !=
            (0x005A2346, VITA_OGG_QUEUE_DECODER_CALL_RVA) or
            dict(read_imports(img.path)).get(VITA_OGG_QUEUE_FREE_IAT_RVA) !=
            VITA_OGG_QUEUE_FREE_IMPORT or
            allocation_push is None or allocation_push.mnemonic != "push" or
            allocation_push.op_str != "0x4b000" or
            allocation_size is None or allocation_size.mnemonic != "mov" or
            allocation_size.op_str !=
            "dword ptr [edi + 4], 0x4b000" or
            direct_target(allocation_call) !=
            VITA_OGG_QUEUE_OPERATOR_NEW_RVA or
            backing_store is None or backing_store.mnemonic != "mov" or
            backing_store.op_str != "dword ptr [edi], eax" or
            error_address is None or error_address.mnemonic != "lea" or
            error_address.op_str != "eax, [ebp - 4]" or
            buffer_argument is None or buffer_argument.mnemonic != "push" or
            buffer_argument.op_str != "edi" or
            error_argument is None or error_argument.mnemonic != "push" or
            error_argument.op_str != "eax" or
            error_clear is None or error_clear.mnemonic != "mov" or
            error_clear.op_str != "dword ptr [ebp - 4], 0" or
            direct_target(decoder_call) != VITA_OGG_QUEUE_DECODER_OPEN_RVA or
            decoder_store is None or decoder_store.mnemonic != "mov" or
            decoder_store.op_str != "dword ptr [ebx], eax" or
            decoder_stack_cleanup is None or
            decoder_stack_cleanup.mnemonic != "add" or
            decoder_stack_cleanup.op_str != "esp, 0xc" or
            error_load is None or error_load.mnemonic != "mov" or
            error_load.op_str != "eax, dword ptr [ebp - 4]" or
            error_test is None or error_test.mnemonic != "test" or
            error_test.op_str != "eax, eax" or
            error_branch is None or error_branch.mnemonic != "je" or
            branch_target(error_branch) != VITA_OGG_QUEUE_SUCCESS_RVA or
            direct_target(error_log_call) != VITA_OGG_QUEUE_ERROR_LOG_RVA or
            error_log_cleanup is None or
            error_log_cleanup.mnemonic != "add" or
            error_log_cleanup.op_str != "esp, 0xc" or
            node_size_push is None or node_size_push.mnemonic != "push" or
            node_size_push.op_str != "0x10" or
            node_pointer_push is None or
            node_pointer_push.mnemonic != "push" or
            node_pointer_push.op_str != "ebx" or
            direct_target(node_delete_site) != VITA_OGG_QUEUE_NODE_DELETE_RVA or
            node_delete_cleanup is None or
            node_delete_cleanup.mnemonic != "add" or
            node_delete_cleanup.op_str != "esp, 8" or
            len(decoder) != 104 or not decoder or
            decoder[-1].address != 0x005BD8A7 or
            sum(ins.size for ins in decoder) != len(decoder_raw) or
            decoder_error_store is None or
            decoder_error_store.mnemonic != "mov" or
            decoder_error_store.op_str != "dword ptr [edi], eax" or
            decoder_error_zero is None or decoder_error_zero.mnemonic != "xor" or
            decoder_error_zero.op_str != "eax, eax" or
            decoder_error_ret is None or decoder_error_ret.mnemonic != "ret" or
            decoder_success_result is None or
            decoder_success_result.mnemonic != "mov" or
            decoder_success_result.op_str != "eax, ebx" or
            decoder_success_ret is None or
            decoder_success_ret.mnemonic != "ret" or
            len(node_delete) != 7 or
            tuple(ins.mnemonic for ins in node_delete) !=
            ("push", "mov", "push", "call", "pop", "pop", "ret") or
            direct_target(node_delete_call) != VITA_OGG_QUEUE_FREE_BRIDGE_RVA or
            free_jump is None or free_jump.mnemonic != "jmp" or
            branch_target(free_jump) != VITA_OGG_QUEUE_FREE_BRIDGE_RVA or
            free_bridge_jump is None or
            free_bridge_jump.mnemonic != "jmp" or
            branch_target(free_bridge_jump) != VITA_OGG_QUEUE_FREE_THUNK_RVA or
            free_thunk is None or free_thunk.mnemonic != "jmp" or
            free_thunk_operand is None or
            free_thunk_operand.type != T.cx.X86_OP_MEM or
            free_thunk_operand.mem.base != 0 or
            free_thunk_operand.mem.index != 0 or
            (free_thunk_operand.mem.disp & 0xFFFFFFFF) !=
            img.va(VITA_OGG_QUEUE_FREE_IAT_RVA)):
        raise RuntimeError(
            "Ogg Queue allocation/error/backing/node/free ownership changed")
    return True


_VITA_ARCHIVE_VALIDATION_SKIP_PE_VALIDATED = False


def _validate_vita_archive_validation_skip_pe():
    global _VITA_ARCHIVE_VALIDATION_SKIP_PE_VALIDATED
    if _VITA_ARCHIVE_VALIDATION_SKIP_PE_VALIDATED:
        return
    if os.path.getsize(EXE) != VITA_STAGE_MEMORY_PE_SIZE:
        raise RuntimeError("archive-validation-skip input PE size changed")
    digest = hashlib.sha256()
    with open(EXE, "rb") as stream:
        for chunk in iter(lambda: stream.read(1024 * 1024), b""):
            digest.update(chunk)
    if digest.hexdigest() != VITA_STAGE_MEMORY_PE_SHA256:
        raise RuntimeError("archive-validation-skip input PE identity changed")
    _VITA_ARCHIVE_VALIDATION_SKIP_PE_VALIDATED = True


def vita_archive_validation_skip_for_body(
        img, root_rva, em, insns, order, emit_image_base):
    """Prove the one frozen validation-only edge before rendering it.

    This selects an exact owner and machine-code seam, not every call to the
    archive constructor.  Runtime policy is deliberately narrower still: only
    entries whose index checksum matched the executable's baked checksum table
    may take the shortcut.
    """
    site = VITA_ARCHIVE_VALIDATION_SKIP_SITE_RVA
    if site not in frozenset(order):
        return False
    if root_rva not in VITA_ARCHIVE_VALIDATION_SKIP_ROOTS:
        raise RuntimeError(
            "unexpected archive-validation-skip membership at root %08x" %
            root_rva)
    _validate_vita_archive_validation_skip_pe()

    def direct_target(ins):
        operand = (ins.operands[0] if ins is not None and
                   len(ins.operands) == 1 else None)
        if (ins is None or ins.mnemonic != "call" or operand is None or
                operand.type != T.cx.X86_OP_IMM):
            return None
        return operand.imm & 0xFFFFFFFF

    entry_load = insns.get(0x00563B30)
    argument_push = insns.get(0x00563B36)
    collision_clear = insns.get(0x00563B37)
    slot_load = insns.get(0x00563B41)
    match_store = insns.get(0x00563B44)
    slot_mask = insns.get(0x00563B47)
    temporary_this = insns.get(0x00563B4D)
    saved_slot = insns.get(0x00563B53)
    constructor_call = insns.get(site)
    resume = insns.get(VITA_ARCHIVE_VALIDATION_SKIP_RESUME_RVA)
    resume_operands = resume.operands if resume is not None else ()
    constructor_return = tuple(T.CS.disasm(
        img.code_at(0x0059C07A, 3), 0x0059C07A, count=1))

    if (len(order) != VITA_ARCHIVE_VALIDATION_SKIP_INSNS or
            not order or order[0] !=
            VITA_ARCHIVE_VALIDATION_SKIP_ROOT_RVA or
            order[-1] != VITA_ARCHIVE_VALIDATION_SKIP_LAST_RVA or
            order[-1] + insns[order[-1]].size !=
            VITA_ARCHIVE_VALIDATION_SKIP_END_RVA or
            rva_sequence_sha256(order) !=
            VITA_ARCHIVE_VALIDATION_SKIP_ORDER_SHA256 or
            canonical_relocated_chunk_sha256(
                img, VITA_ARCHIVE_VALIDATION_SKIP_ROOT_RVA,
                VITA_ARCHIVE_VALIDATION_SKIP_END_RVA -
                VITA_ARCHIVE_VALIDATION_SKIP_ROOT_RVA) !=
            VITA_ARCHIVE_VALIDATION_SKIP_BODY_SHA256 or
            canonical_relocated_chunk_sha256(
                img, VITA_ARCHIVE_VALIDATION_SKIP_PRECALL_RVA,
                VITA_ARCHIVE_VALIDATION_SKIP_PRECALL_END_RVA -
                VITA_ARCHIVE_VALIDATION_SKIP_PRECALL_RVA) !=
            VITA_ARCHIVE_VALIDATION_SKIP_PRECALL_SHA256 or
            canonical_relocated_chunk_sha256(
                img, VITA_ARCHIVE_VALIDATION_SKIP_SITE_RVA,
                VITA_ARCHIVE_VALIDATION_SKIP_RESUME_RVA -
                VITA_ARCHIVE_VALIDATION_SKIP_SITE_RVA) !=
            VITA_ARCHIVE_VALIDATION_SKIP_RANGE_SHA256 or
            canonical_relocated_chunk_sha256(
                img, VITA_ARCHIVE_VALIDATION_SKIP_RESUME_WINDOW_RVA,
                VITA_ARCHIVE_VALIDATION_SKIP_RESUME_WINDOW_END_RVA -
                VITA_ARCHIVE_VALIDATION_SKIP_RESUME_WINDOW_RVA) !=
            VITA_ARCHIVE_VALIDATION_SKIP_RESUME_WINDOW_SHA256 or
            entry_load is None or entry_load.mnemonic != "mov" or
            entry_load.op_str != "ecx, dword ptr [ebp - 0xe50]" or
            argument_push is None or argument_push.mnemonic != "push" or
            argument_push.op_str != "ecx" or
            collision_clear is None or collision_clear.mnemonic != "mov" or
            collision_clear.op_str != "dword ptr [ebp - 0xe84], 0" or
            slot_load is None or slot_load.mnemonic != "mov" or
            slot_load.op_str != "edi, dword ptr [ecx + 4]" or
            match_store is None or match_store.mnemonic != "mov" or
            match_store.op_str != "byte ptr [ecx + 0x18], al" or
            slot_mask is None or slot_mask.mnemonic != "and" or
            slot_mask.op_str != "edi, 0x7fff" or
            temporary_this is None or temporary_this.mnemonic != "lea" or
            temporary_this.op_str != "ecx, [ebp - 0xe44]" or
            saved_slot is None or saved_slot.mnemonic != "mov" or
            saved_slot.op_str != "dword ptr [ebp - 0xe80], edi" or
            direct_target(constructor_call) != 0x0059BFA0 or
            resume is None or resume.mnemonic != "mov" or
            len(resume_operands) != 2 or
            resume_operands[0].type != T.cx.X86_OP_REG or
            resume_operands[0].reg != T.cx.X86_REG_EAX or
            resume_operands[1].type != T.cx.X86_OP_MEM or
            resume_operands[1].mem.base != 0 or
            resume_operands[1].mem.index != T.cx.X86_REG_EDI or
            resume_operands[1].mem.scale != 4 or
            (resume_operands[1].mem.disp & 0xFFFFFFFF) !=
            ((emit_image_base + 0x007C7C68) & 0xFFFFFFFF) or
            len(constructor_return) != 1 or
            constructor_return[0].mnemonic != "ret" or
            constructor_return[0].op_str != "4"):
        raise RuntimeError(
            "archive-validation-skip owner/seam/constructor ABI changed")

    # 0x00563c8c is ordinary fall-through after the temporary destructor in
    # the original body.  The opt-in edge makes it an explicit C target.
    em.labels.add(VITA_ARCHIVE_VALIDATION_SKIP_RESUME_RVA)
    return True


def pc_clock_for_body(img, root_rva, em, order):
    """Validate the exact glfwGetTime root used by the PC frame limiter.

    The raw xref scan is intentionally independent of decoded function
    metadata.  A new physical caller or address-taken use changes the scope of
    this root replacement and must be reviewed instead of silently inheriting
    the PC clock policy.
    """
    members = frozenset(order)
    if PC_CLOCK_ROOT_RVA not in members:
        return False
    if root_rva != PC_CLOCK_ROOT_RVA:
        raise RuntimeError(
            "unexpected PC clock body membership at root %08x" % root_rva)

    # One root performs the image-wide raw-byte census.  Body memberships are
    # validated independently for every rendered function below.
    validate_pc_glfw_guard_census(img)

    body = img.code_at(
        PC_CLOCK_ROOT_RVA, PC_CLOCK_END_RVA - PC_CLOCK_ROOT_RVA)
    if (len(order) != 31 or order[0] != PC_CLOCK_ROOT_RVA or
            hashlib.sha256(body).hexdigest() != PC_CLOCK_BODY_SHA256):
        raise RuntimeError("PC clock body/CFG identity changed")

    decoded = list(T.CS.disasm(body, PC_CLOCK_ROOT_RVA))
    by_rva = {ins.address: ins for ins in decoded}
    first = by_rva.get(PC_CLOCK_ROOT_RVA)
    error_zero = by_rva.get(0x0057005E)
    success_scale = by_rva.get(0x0057009B)
    if (len(decoded) != 31 or first is None or
            first.mnemonic != "push" or first.op_str != "ebp" or
            error_zero is None or error_zero.mnemonic != "xorps" or
            error_zero.op_str != "xmm0, xmm0" or
            success_scale is None or success_scale.mnemonic != "mulsd" or
            not success_scale.op_str.startswith("xmm0, ")):
        raise RuntimeError("PC clock binary64 return ABI changed")
    for site in (0x00570064, 0x005700A6):
        ret = by_rva.get(site)
        if ret is None or ret.mnemonic != "ret" or ret.size != 1 or ret.op_str:
            raise RuntimeError("PC clock plain-RET ABI changed at %08x" % site)

    rel32_xrefs = []
    for site in range(img.text_rva, img.text_end - 4):
        if img.mem[site] != 0xE8:
            continue
        displacement = int.from_bytes(
            img.code_at(site + 1, 4), "little", signed=True)
        if ((site + 5 + displacement) & 0xFFFFFFFF) == PC_CLOCK_ROOT_RVA:
            rel32_xrefs.append(site)
    address_refs = tuple(
        site for site in sorted(img.reloc_rvas)
        if int.from_bytes(img.code_at(site, 4), "little") ==
        img.va(PC_CLOCK_ROOT_RVA)
    )
    if tuple(rel32_xrefs) != PC_CLOCK_DIRECT_XREFS or address_refs:
        raise RuntimeError("PC clock caller/address-reference census changed")

    for site, expected in PC_CLOCK_CALLER_ABI_WINDOWS:
        if img.code_at(site, len(expected)) != expected:
            raise RuntimeError(
                "PC clock caller ABI window changed at %08x" % site)
        instructions = list(T.CS.disasm(expected, site))
        call = instructions[0] if instructions else None
        result_use = instructions[-1] if instructions else None
        operand = (call.operands[0] if call is not None and
                   len(call.operands) == 1 else None)
        if (call is None or call.mnemonic != "call" or call.size != 5 or
                operand is None or operand.type != T.cx.X86_OP_IMM or
                (operand.imm & 0xFFFFFFFF) != PC_CLOCK_ROOT_RVA or
                result_use is None or "xmm0" not in result_use.op_str or
                result_use.mnemonic not in ("movsd", "subsd", "cvtsd2ss")):
            raise RuntimeError(
                "PC clock caller XMM0 contract changed at %08x" % site)

    # Keep the independently inlined-site inventory tied to this public-root
    # contract too.  pc_clock_inline_seams_for_body pins their complete owner,
    # blocks, error paths and injected continuations.
    for site in PC_CLOCK_KNOWN_INLINE_COPIES:
        if img.code_at(site, len(PC_CLOCK_INLINE_GUARD_MACHINE)) != \
                PC_CLOCK_INLINE_GUARD_MACHINE:
            raise RuntimeError(
                "known inlined GLFW clock copy changed at %08x" % site)
    return True


def pc_clock_inline_seams_for_body(img, root_rva, em, order):
    """Validate the three live inlined glfwGetTime limiter copies.

    The exact 96-byte blocks remain in generated C as the disabled-backend
    fallback.  An explicit backend gets one earlier edge to the original
    result continuation, so its only guest-state write is XMM0.d[0].
    """
    members = frozenset(order)
    sites = frozenset(spec["site"] for spec in PC_CLOCK_INLINE_SPECS)
    reached = members & sites
    if not reached:
        return ()
    if (root_rva != PC_CLOCK_INLINE_OWNER_RVA or reached != sites or
            tuple(spec["site"] for spec in PC_CLOCK_INLINE_SPECS) !=
            PC_CLOCK_KNOWN_INLINE_COPIES):
        raise RuntimeError(
            "unexpected inlined PC clock membership at root %08x" % root_rva)

    owner = img.code_at(
        PC_CLOCK_INLINE_OWNER_RVA,
        PC_CLOCK_INLINE_OWNER_END_RVA - PC_CLOCK_INLINE_OWNER_RVA)
    if (len(order) != PC_CLOCK_INLINE_OWNER_INSNS or
            order[0] != PC_CLOCK_INLINE_OWNER_RVA or
            order[-1] != PC_CLOCK_INLINE_OWNER_END_RVA - 1 or
            hashlib.sha256(owner).hexdigest() !=
            PC_CLOCK_INLINE_OWNER_SHA256):
        raise RuntimeError("inlined PC clock owner body/CFG changed")

    backward_consumers = []
    for ins in T.CS.disasm(owner, PC_CLOCK_INLINE_OWNER_RVA):
        if (not ins.mnemonic.startswith("j") or
                not ins.operands or
                ins.operands[0].type != T.cx.X86_OP_IMM):
            continue
        target = ins.operands[0].imm & 0xFFFFFFFF
        covered = tuple(
            site for site in PC_CLOCK_KNOWN_INLINE_COPIES
            if target <= site <= ins.address)
        if target < ins.address and covered:
            backward_consumers.append(
                (ins.address, ins.mnemonic, target, covered))
    if tuple(backward_consumers) != PC_CLOCK_INLINE_BACKWARD_CONSUMERS:
        raise RuntimeError(
            "inlined PC clock backward-consumer census changed")

    for spec in PC_CLOCK_INLINE_SPECS:
        site = spec["site"]
        continuation = spec["continuation"]
        block = img.code_at(site, PC_CLOCK_INLINE_BLOCK_SIZE)
        if (continuation - site != PC_CLOCK_INLINE_BLOCK_SIZE or
                hashlib.sha256(block).hexdigest() !=
                spec["block_sha256"]):
            raise RuntimeError(
                "inlined PC clock block changed at %08x" % site)

        # The first 0x1d bytes are precisely GLFW's flag-zero error path:
        # _glfwInputError(GLFW_NOT_INITIALIZED, NULL), result 0.0, then the
        # jump which our explicit-backend edge must pass without executing.
        prefix = tuple(
            (ins.address, ins.mnemonic, ins.op_str, ins.size)
            for ins in T.CS.disasm(block[:0x1d], site)
        )
        expected_prefix = (
            (site, "cmp", "byte ptr [0x307fd66b], 0", 7),
            (site + 0x07, "jne", "0x%x" % (site + 0x1d), 2),
            (site + 0x09, "push", "0", 2),
            (site + 0x0b, "push", "0x%x" % PC_CLOCK_INLINE_ERROR_CODE, 5),
            (site + 0x10, "call",
             "0x%x" % PC_CLOCK_INLINE_ERROR_LOGGER_RVA, 5),
            (site + 0x15, "add", "esp, 8", 3),
            (site + 0x18, "xorps", "xmm0, xmm0", 3),
            (site + 0x1b, "jmp", "0x%x" % continuation, 2),
        )
        if prefix != expected_prefix:
            raise RuntimeError(
                "inlined PC clock zero/error path changed at %08x" % site)

    if img.code_at(
            PC_CLOCK_INLINE_BUSY_BACKEDGE_RVA,
            len(PC_CLOCK_INLINE_BUSY_BACKEDGE_MACHINE)) != \
            PC_CLOCK_INLINE_BUSY_BACKEDGE_MACHINE:
        raise RuntimeError("inlined PC clock limiter backedge changed")
    limiter = tuple(T.CS.disasm(
        PC_CLOCK_INLINE_BUSY_BACKEDGE_MACHINE,
        PC_CLOCK_INLINE_BUSY_BACKEDGE_RVA))
    branch = limiter[-1] if limiter else None
    operand = (branch.operands[0] if branch is not None and
               len(branch.operands) == 1 else None)
    if (len(limiter) != 4 or branch.mnemonic != "ja" or
            operand is None or operand.type != T.cx.X86_OP_IMM or
            (operand.imm & 0xFFFFFFFF) != PC_CLOCK_KNOWN_INLINE_COPIES[2]):
        raise RuntimeError("inlined PC clock limiter edge changed")

    for spec in PC_CLOCK_INLINE_SPECS:
        em.labels.add(spec["continuation"])
    return PC_CLOCK_INLINE_SPECS


def pc_display_dimension_for_body(img, root_rva, em, order):
    """Validate the exact GLFW-backed display dimension root, if present.

    A raw rel32/address census freezes the whole physical caller set.  The
    preserved binaries prove the no-argument/plain-RET EAX ABI and, crucially,
    the uninitialized local read on the GLFW_NOT_INITIALIZED path which made
    the measured post-Intro resize publish 65537x0.
    """
    members = frozenset(order)
    matches = tuple(
        spec for spec in PC_DISPLAY_DIMENSION_SPECS
        if spec["root"] in members
    )
    if not matches:
        return None
    if len(matches) != 1:
        raise RuntimeError("PC display dimension roots unexpectedly overlap")
    spec = matches[0]
    root = spec["root"]
    if root_rva != root:
        raise RuntimeError(
            "unexpected PC display %s membership at root %08x"
            % (spec["dimension"], root_rva))

    body = img.code_at(root, spec["end"] - root)
    if (len(order) != 31 or order[0] != root or
            hashlib.sha256(body).hexdigest() != spec["body_sha256"]):
        raise RuntimeError(
            "PC display %s body/CFG identity changed" % spec["dimension"])

    decoded = list(T.CS.disasm(body, root))
    by_rva = {ins.address: ins for ins in decoded}
    first = by_rva.get(root)
    if (len(decoded) != 31 or first is None or
            first.mnemonic != "push" or first.op_str != "ebp"):
        raise RuntimeError(
            "PC display %s prologue identity changed" % spec["dimension"])
    for site, displacement in (
            (spec["failure_result"], -0x18),
            (spec["success_result"], -0x0C if spec["dimension"] == "width"
             else -0x08)):
        ins = by_rva.get(site)
        operands = ins.operands if ins is not None else ()
        if (ins is None or ins.mnemonic != "mov" or len(operands) != 2 or
                operands[0].type != T.cx.X86_OP_REG or
                operands[0].reg != T.cx.X86_REG_EAX or
                operands[1].type != T.cx.X86_OP_MEM or
                operands[1].mem.base != T.cx.X86_REG_EBP or
                operands[1].mem.disp != displacement):
            raise RuntimeError(
                "PC display %s EAX return source changed at %08x"
                % (spec["dimension"], site))
    for site in spec["returns"]:
        ret = by_rva.get(site)
        if ret is None or ret.mnemonic != "ret" or ret.size != 1 or ret.op_str:
            raise RuntimeError(
                "PC display %s plain-RET ABI changed at %08x"
                % (spec["dimension"], site))

    rel32_xrefs = []
    for site in range(img.text_rva, img.text_end - 4):
        if img.mem[site] != 0xE8:
            continue
        displacement = int.from_bytes(
            img.code_at(site + 1, 4), "little", signed=True)
        if ((site + 5 + displacement) & 0xFFFFFFFF) == root:
            rel32_xrefs.append(site)
    address_refs = tuple(
        site for site in sorted(img.reloc_rvas)
        if int.from_bytes(img.code_at(site, 4), "little") == img.va(root)
    )
    if tuple(rel32_xrefs) != spec["xrefs"] or address_refs:
        raise RuntimeError(
            "PC display %s caller/address-reference census changed"
            % spec["dimension"])
    if img.code_at(PC_DISPLAY_RESIZE_MACHINE_RVA,
                   len(PC_DISPLAY_RESIZE_MACHINE)) != \
            PC_DISPLAY_RESIZE_MACHINE:
        raise RuntimeError("PC post-Intro display resize chain changed")
    return spec["dimension"]


_VITA_STAGE_MEMORY_PE_VALIDATED = False


def _validate_vita_stage_memory_pe():
    global _VITA_STAGE_MEMORY_PE_VALIDATED
    if _VITA_STAGE_MEMORY_PE_VALIDATED:
        return
    if os.path.getsize(EXE) != VITA_STAGE_MEMORY_PE_SIZE:
        raise RuntimeError("stage-memory input PE size changed")
    digest = hashlib.sha256()
    with open(EXE, "rb") as stream:
        for chunk in iter(lambda: stream.read(1024 * 1024), b""):
            digest.update(chunk)
    if digest.hexdigest() != VITA_STAGE_MEMORY_PE_SHA256:
        raise RuntimeError("stage-memory input PE identity changed")
    _VITA_STAGE_MEMORY_PE_VALIDATED = True


def _vita_stage_memory_instruction(img, site, mnemonic):
    decoded = tuple(T.CS.disasm(img.code_at(site, 15), site, count=1))
    ins = decoded[0] if len(decoded) == 1 else None
    if ins is None or ins.address != site or ins.mnemonic != mnemonic:
        raise RuntimeError(
            "stage-memory instruction changed at %08x" % site)
    return ins


def _vita_stage_memory_mem_operand(operand, base, displacement):
    return (operand.type == T.cx.X86_OP_MEM and
            operand.mem.base == base and operand.mem.index == 0 and
            operand.mem.disp == displacement)


def _vita_stage_memory_validate_order_membership(root_rva, order):
    members = frozenset(order)
    present = members & VITA_STAGE_MEMORY_ALL_HOOK_SITES
    spec = VITA_STAGE_MEMORY_ROOT_SPECS.get(root_rva)
    if spec is None:
        if present:
            raise RuntimeError(
                "stage-memory hook sites leaked into non-owner %08x: %s"
                % (root_rva,
                   ",".join("%08x" % site for site in sorted(present))))
        return None
    expected_members = frozenset(spec["hooks"])
    if present != expected_members or root_rva not in members:
        raise RuntimeError(
            "stage-memory hook membership changed at %08x: %s != %s"
            % (root_rva,
               ",".join("%08x" % site for site in sorted(present)),
               ",".join("%08x" % site
                        for site in sorted(expected_members))))
    return spec


def _vita_stage_memory_validate_failed_extent(fn):
    """Fail a decode before a hook-containing canonical extent can stub."""
    root_rva = fn["rva"]
    end_rva = fn.get("end")
    if end_rva is None:
        if root_rva in VITA_STAGE_MEMORY_ROOT_SPECS:
            raise RuntimeError(
                "stage-memory owner decode has no provable extent at %08x" %
                root_rva)
        return
    present = frozenset(
        site for site in VITA_STAGE_MEMORY_ALL_HOOK_SITES
        if root_rva <= site < end_rva)
    if present:
        raise RuntimeError(
            "stage-memory hook extent failed decode at %08x: %s"
            % (root_rva,
               ",".join("%08x" % site for site in sorted(present))))


def vita_stage_memory_for_body(img, root_rva, em, order, body):
    """Select and prove one exact stage-memory owner, if this is one.

    The returned description is consumed only by the renderer.  Any byte,
    decoded-operand, branch-target or original-emission drift fails generation
    before a hook can be written.
    """
    spec = _vita_stage_memory_validate_order_membership(root_rva, order)
    if spec is None:
        return None
    _validate_vita_stage_memory_pe()
    body_bytes = img.code_at(root_rva, spec["end"] - root_rva)
    if hashlib.sha256(body_bytes).hexdigest() != spec["body_sha256"]:
        raise RuntimeError(
            "stage-memory owner body changed at %08x" % root_rva)
    for start, end, expected in spec["windows"]:
        if hashlib.sha256(img.code_at(start, end - start)).hexdigest() != \
                expected:
            raise RuntimeError(
                "stage-memory owner window changed at %08x" % start)
    if root_rva == VITA_STAGE_MEMORY_LEVEL_ROOT_RVA:
        push_specs = (
            (0x00312153, T.cx.X86_REG_EBP, -0x50),
            (0x00312156, T.cx.X86_REG_EDI, 4),
            (0x00312159, T.cx.X86_REG_EDI, 0),
        )
        for site, base, displacement in push_specs:
            ins = _vita_stage_memory_instruction(img, site, "push")
            if (len(ins.operands) != 1 or
                    not _vita_stage_memory_mem_operand(
                        ins.operands[0], base, displacement)):
                raise RuntimeError(
                    "stage-memory Level push operand changed at %08x" % site)
        marker = _vita_stage_memory_instruction(img, 0x0031215B, "push")
        if (len(marker.operands) != 1 or
                marker.operands[0].type != T.cx.X86_OP_IMM or
                (marker.operands[0].imm & 0xFFFFFFFF) != 0x3074C03C):
            raise RuntimeError("stage-memory Level begin boundary changed")
        clear = _vita_stage_memory_instruction(img, 0x00312E85, "mov")
        if (len(clear.operands) != 2 or
                not _vita_stage_memory_mem_operand(
                    clear.operands[0], T.cx.X86_REG_EDI, 0x18230) or
                clear.operands[1].type != T.cx.X86_OP_IMM or
                clear.operands[1].imm != 0):
            raise RuntimeError("stage-memory Level end boundary changed")
        _vita_stage_memory_instruction(img, 0x00312E8C, "mov")
    elif root_rva == VITA_STAGE_MEMORY_LOAD_ROOT_RVA:
        for site, register, displacement in (
                (0x003E543E, T.cx.X86_REG_EDX, 8),
                (0x003E5441, T.cx.X86_REG_EAX, 0x0C)):
            ins = _vita_stage_memory_instruction(img, site, "mov")
            if (len(ins.operands) != 2 or
                    ins.operands[0].type != T.cx.X86_OP_REG or
                    ins.operands[0].reg != register or
                    not _vita_stage_memory_mem_operand(
                        ins.operands[1], T.cx.X86_REG_EBX, displacement)):
                raise RuntimeError(
                    "stage-memory Load argument changed at %08x" % site)
        begin = _vita_stage_memory_instruction(img, 0x003E547C, "imul")
        if (len(begin.operands) != 3 or
                begin.operands[0].type != T.cx.X86_OP_REG or
                begin.operands[0].reg != T.cx.X86_REG_EAX or
                begin.operands[1].type != T.cx.X86_OP_REG or
                begin.operands[1].reg != T.cx.X86_REG_EAX or
                begin.operands[2].type != T.cx.X86_OP_IMM or
                begin.operands[2].imm != 0x2C):
            raise RuntimeError("stage-memory Load begin boundary changed")
        early_zero = _vita_stage_memory_instruction(img, 0x003E548D, "xor")
        if (len(early_zero.operands) != 2 or
                any(operand.type != T.cx.X86_OP_REG or
                    operand.reg != T.cx.X86_REG_AL
                    for operand in early_zero.operands)):
            raise RuntimeError("stage-memory early-failure AL zero changed")
        early_jump = _vita_stage_memory_instruction(img, 0x003E548F, "jmp")
        if (len(early_jump.operands) != 1 or
                early_jump.operands[0].type != T.cx.X86_OP_IMM or
                (early_jump.operands[0].imm & 0xFFFFFFFF) != 0x003E57E9):
            raise RuntimeError("stage-memory early-failure result edge changed")
        unload = _vita_stage_memory_instruction(img, 0x003E563B, "call")
        if (len(unload.operands) != 1 or
                unload.operands[0].type != T.cx.X86_OP_IMM or
                (unload.operands[0].imm & 0xFFFFFFFF) != 0x003E3780):
            raise RuntimeError("stage-memory unload call changed")
        _vita_stage_memory_instruction(img, 0x003E5640, "mov")
        result = _vita_stage_memory_instruction(img, 0x003E57E6, "mov")
        if (len(result.operands) != 2 or
                result.operands[0].type != T.cx.X86_OP_REG or
                result.operands[0].reg != T.cx.X86_REG_AL or
                not _vita_stage_memory_mem_operand(
                    result.operands[1], T.cx.X86_REG_EBP, -0x5D)):
            raise RuntimeError("stage-memory Load result boundary changed")
        for site, value in ((0x003E57A6, 1), (0x003E57AC, 0)):
            materialize = _vita_stage_memory_instruction(img, site, "mov")
            if (len(materialize.operands) != 2 or
                    not _vita_stage_memory_mem_operand(
                        materialize.operands[0], T.cx.X86_REG_EBP, -0x5D) or
                    materialize.operands[1].type != T.cx.X86_OP_IMM or
                    materialize.operands[1].imm != value):
                raise RuntimeError(
                    "stage-memory normal result local changed at %08x" % site)
        _vita_stage_memory_instruction(img, 0x003E57E9, "mov")

    rendered = {ins.address: legacy_statements(stmts) for ins, stmts in body}
    for (owner, site), reuse in VITA_STAGE_MEMORY_REUSE_SPECS.items():
        if owner != root_rva:
            continue
        branch = _vita_stage_memory_instruction(img, site, "jne")
        target = reuse["target"]
        if (len(branch.operands) != 1 or
                branch.operands[0].type != T.cx.X86_OP_IMM or
                (branch.operands[0].imm & 0xFFFFFFFF) != target or
                target not in em.labels or
                not jcc_statement_matches(rendered.get(site, ()), target)):
            raise RuntimeError(
                "stage-memory reuse edge/emission changed at %08x" % site)
    return spec


_VITA_CONTINUE_PROFILE_PE_VALIDATED = False


def _validate_vita_continue_profile_pe():
    global _VITA_CONTINUE_PROFILE_PE_VALIDATED
    if _VITA_CONTINUE_PROFILE_PE_VALIDATED:
        return
    if os.path.getsize(EXE) != VITA_CONTINUE_PROFILE_PE_SIZE:
        raise RuntimeError("continue-profile input PE size changed")
    digest = hashlib.sha256()
    with open(EXE, "rb") as stream:
        for chunk in iter(lambda: stream.read(1024 * 1024), b""):
            digest.update(chunk)
    if digest.hexdigest() != VITA_CONTINUE_PROFILE_PE_SHA256:
        raise RuntimeError("continue-profile input PE identity changed")
    _VITA_CONTINUE_PROFILE_PE_VALIDATED = True


def _vita_continue_profile_instruction(img, site, mnemonic=None):
    decoded = tuple(T.CS.disasm(img.code_at(site, 15), site, count=1))
    ins = decoded[0] if len(decoded) == 1 else None
    if (ins is None or ins.address != site or
            (mnemonic is not None and ins.mnemonic != mnemonic)):
        raise RuntimeError(
            "continue-profile instruction changed at %08x" % site)
    return ins


def _vita_continue_profile_validate_order_membership(root_rva, order):
    members = frozenset(order)
    present = members & VITA_CONTINUE_PROFILE_ALL_HOOK_SITES
    expected = frozenset(VITA_CONTINUE_PROFILE_ROOT_HOOKS.get(root_rva, ()))
    if not expected:
        if present:
            raise RuntimeError(
                "continue-profile hook sites leaked into non-owner %08x: %s"
                % (root_rva,
                   ",".join("%08x" % site for site in sorted(present))))
        return None
    if present != expected or root_rva not in members:
        raise RuntimeError(
            "continue-profile hook membership changed at %08x: %s != %s"
            % (root_rva,
               ",".join("%08x" % site for site in sorted(present)),
               ",".join("%08x" % site for site in sorted(expected))))
    return expected


def _vita_continue_profile_validate_failed_extent(fn):
    """Fail before a decode error can silently stub a hook owner."""
    root_rva = fn["rva"]
    end_rva = fn.get("end")
    if end_rva is None:
        if root_rva in VITA_CONTINUE_PROFILE_ROOT_HOOKS:
            raise RuntimeError(
                "continue-profile owner has no provable extent at %08x" %
                root_rva)
        return
    present = frozenset(
        site for site in VITA_CONTINUE_PROFILE_ALL_HOOK_SITES
        if root_rva <= site < end_rva)
    if present:
        raise RuntimeError(
            "continue-profile hook extent failed decode at %08x: %s"
            % (root_rva,
               ",".join("%08x" % site for site in sorted(present))))


def vita_continue_profile_for_body(img, root_rva, order, body):
    """Authenticate the frozen call/control edges used by the profiler."""
    expected = _vita_continue_profile_validate_order_membership(
        root_rva, order)
    if expected is None:
        return None
    _validate_vita_continue_profile_pe()

    if root_rva == VITA_CONTINUE_PROFILE_FILE_SELECT_ROOT:
        call = _vita_continue_profile_instruction(
            img, VITA_CONTINUE_PROFILE_FILE_SELECT_CALL, "call")
        operand = call.operands[0] if len(call.operands) == 1 else None
        if (call.address + call.size !=
                VITA_CONTINUE_PROFILE_FILE_SELECT_CALL_RESUME or
                operand is None or operand.type != T.cx.X86_OP_IMM or
                (operand.imm & 0xFFFFFFFF) !=
                VITA_CONTINUE_PROFILE_FILE_SELECT_TARGET):
            raise RuntimeError(
                "continue-profile file-select direct target changed")
        body_bytes = img.code_at(
            root_rva, VITA_CONTINUE_PROFILE_FILE_SELECT_END - root_rva)
        if (len(order) != 209 or order[0] != root_rva or
                order[-1] != VITA_CONTINUE_PROFILE_FILE_SELECT_RETURNS[-1] or
                hashlib.sha256(body_bytes).hexdigest() !=
                VITA_CONTINUE_PROFILE_FILE_SELECT_BODY_SHA256):
            raise RuntimeError(
                "continue-profile file-select body/extent changed")
        for site in VITA_CONTINUE_PROFILE_FILE_SELECT_RETURNS:
            ret = _vita_continue_profile_instruction(img, site, "ret")
            if ret.op_str != "4":
                raise RuntimeError(
                    "continue-profile file-select RET 4 ABI changed")
        rel32_xrefs = []
        for site in range(img.text_rva, img.text_end - 4):
            if img.mem[site] != 0xE8:
                continue
            displacement = int.from_bytes(
                img.code_at(site + 1, 4), "little", signed=True)
            if ((site + 5 + displacement) & 0xFFFFFFFF) == root_rva:
                rel32_xrefs.append(site)
        address_refs = tuple(
            site for site in sorted(img.reloc_rvas)
            if int.from_bytes(img.code_at(site, 4), "little") ==
            img.va(root_rva)
        )
        if (tuple(rel32_xrefs) !=
                VITA_CONTINUE_PROFILE_FILE_SELECT_XREFS or address_refs):
            raise RuntimeError(
                "continue-profile file-select caller census changed")

    for (owner, call_site, resume_site, direct_target, indirect_disp,
         _begin_event, _begin_value, _end_event, _end_value) in \
            VITA_CONTINUE_PROFILE_CALL_SPECS:
        if owner != root_rva:
            continue
        call = _vita_continue_profile_instruction(img, call_site, "call")
        if call.address + call.size != resume_site or len(call.operands) != 1:
            raise RuntimeError(
                "continue-profile call/resume edge changed at %08x" %
                call_site)
        operand = call.operands[0]
        if direct_target is not None:
            if (indirect_disp is not None or
                    operand.type != T.cx.X86_OP_IMM or
                    (operand.imm & 0xFFFFFFFF) != direct_target):
                raise RuntimeError(
                    "continue-profile direct target changed at %08x" %
                    call_site)
        else:
            if (indirect_disp is None or
                    operand.type != T.cx.X86_OP_MEM or
                    operand.mem.base != T.cx.X86_REG_EAX or
                    operand.mem.index != 0 or
                    operand.mem.disp != indirect_disp):
                raise RuntimeError(
                    "continue-profile indirect target changed at %08x" %
                    call_site)
        _vita_continue_profile_instruction(img, resume_site)

    for owner, site, _event, _value, mnemonic in \
            VITA_CONTINUE_PROFILE_CONTROL_SPECS:
        if owner == root_rva:
            _vita_continue_profile_instruction(img, site, mnemonic)

    rendered_hooks = tuple(
        ins.address for ins, _stmts in body
        if (root_rva, ins.address) in VITA_CONTINUE_PROFILE_SITE_SPECS)
    if frozenset(rendered_hooks) != expected or \
            len(rendered_hooks) != len(expected):
        raise RuntimeError(
            "continue-profile renderer membership changed at %08x" %
            root_rva)
    return {"hooks": rendered_hooks}


_VITA_EXIT_MENU_PROFILE_PE_VALIDATED = False


def _validate_vita_exit_menu_profile_pe():
    global _VITA_EXIT_MENU_PROFILE_PE_VALIDATED
    if _VITA_EXIT_MENU_PROFILE_PE_VALIDATED:
        return
    if os.path.getsize(EXE) != VITA_EXIT_MENU_PROFILE_PE_SIZE:
        raise RuntimeError("Exit-menu input PE size changed")
    digest = hashlib.sha256()
    with open(EXE, "rb") as stream:
        for chunk in iter(lambda: stream.read(1024 * 1024), b""):
            digest.update(chunk)
    if digest.hexdigest() != VITA_EXIT_MENU_PROFILE_PE_SHA256:
        raise RuntimeError("Exit-menu input PE identity changed")
    _VITA_EXIT_MENU_PROFILE_PE_VALIDATED = True


def _vita_exit_menu_profile_instruction(img, site, mnemonic=None):
    decoded = tuple(T.CS.disasm(img.code_at(site, 15), site, count=1))
    ins = decoded[0] if len(decoded) == 1 else None
    if (ins is None or ins.address != site or
            (mnemonic is not None and ins.mnemonic != mnemonic)):
        raise RuntimeError(
            "Exit-menu instruction changed at %08x" % site)
    return ins


def _vita_exit_menu_profile_validate_order_membership(root_rva, order):
    members = frozenset(order)
    present = members & VITA_EXIT_MENU_PROFILE_ALL_HOOK_SITES
    expected = frozenset(VITA_EXIT_MENU_PROFILE_ROOT_HOOKS.get(root_rva, ()))
    if not expected:
        if present:
            raise RuntimeError(
                "Exit-menu hook sites leaked into non-owner %08x: %s"
                % (root_rva,
                   ",".join("%08x" % site for site in sorted(present))))
        return None
    if present != expected or root_rva not in members:
        raise RuntimeError(
            "Exit-menu hook membership changed at %08x: %s != %s"
            % (root_rva,
               ",".join("%08x" % site for site in sorted(present)),
               ",".join("%08x" % site for site in sorted(expected))))
    return expected


def _vita_exit_menu_profile_validate_failed_extent(fn):
    """Do not let a decode error silently stub an Exit hook owner."""
    root_rva = fn["rva"]
    end_rva = fn.get("end")
    if end_rva is None:
        if root_rva in VITA_EXIT_MENU_PROFILE_ROOT_HOOKS:
            raise RuntimeError(
                "Exit-menu owner has no provable extent at %08x" % root_rva)
        return
    present = frozenset(
        site for site in VITA_EXIT_MENU_PROFILE_ALL_HOOK_SITES
        if root_rva <= site < end_rva)
    if present:
        raise RuntimeError(
            "Exit-menu hook extent failed decode at %08x: %s"
            % (root_rva,
               ",".join("%08x" % site for site in sorted(present))))


def _vita_exit_menu_profile_validate_xrefs(img):
    found = {target: [] for target in VITA_EXIT_MENU_PROFILE_DIRECT_XREFS}
    for site in range(img.text_rva, img.text_end - 4):
        if img.mem[site] != 0xE8:
            continue
        displacement = int.from_bytes(
            img.code_at(site + 1, 4), "little", signed=True)
        target = (site + 5 + displacement) & 0xFFFFFFFF
        if target in found:
            found[target].append(site)
    actual = {target: tuple(sites) for target, sites in found.items()}
    if actual != VITA_EXIT_MENU_PROFILE_DIRECT_XREFS:
        raise RuntimeError("Exit-menu direct caller census changed")


def _vita_exit_menu_profile_validate_read_checksum_census(img):
    calls = []
    for site in range(VITA_EXIT_MENU_PROFILE_READ_ROOT,
                      VITA_EXIT_MENU_PROFILE_READ_END - 4):
        if img.mem[site] != 0xE8:
            continue
        displacement = int.from_bytes(
            img.code_at(site + 1, 4), "little", signed=True)
        if ((site + 5 + displacement) & 0xFFFFFFFF) == \
                VITA_EXIT_MENU_PROFILE_CHECKSUM_TARGET:
            calls.append(site)
    packed = b"".join(site.to_bytes(4, "little") for site in calls)
    if (len(calls) != VITA_EXIT_MENU_PROFILE_CHECKSUM_CALL_COUNT or
            hashlib.sha256(packed).hexdigest() !=
            VITA_EXIT_MENU_PROFILE_CHECKSUM_CALLS_SHA256):
        raise RuntimeError("Exit-menu checksum caller census changed")
    body_bytes = img.code_at(
        VITA_EXIT_MENU_PROFILE_READ_ROOT,
        VITA_EXIT_MENU_PROFILE_READ_END -
        VITA_EXIT_MENU_PROFILE_READ_ROOT)
    if hashlib.sha256(body_bytes).hexdigest() != \
            VITA_EXIT_MENU_PROFILE_READ_BODY_SHA256:
        raise RuntimeError("Exit-menu GameState read body changed")


def vita_exit_menu_profile_for_body(img, root_rva, order, body):
    """Authenticate the frozen Exit/menu edges and scalar provenance."""
    expected = _vita_exit_menu_profile_validate_order_membership(
        root_rva, order)
    if expected is None:
        return None
    _validate_vita_exit_menu_profile_pe()

    for (owner, call_site, resume_site, direct_target,
         _begin_event, _begin_value, _end_event, _end_value) in \
            VITA_EXIT_MENU_PROFILE_CALL_SPECS:
        if owner != root_rva:
            continue
        call = _vita_exit_menu_profile_instruction(img, call_site, "call")
        operand = call.operands[0] if len(call.operands) == 1 else None
        if (call.address + call.size != resume_site or operand is None or
                operand.type != T.cx.X86_OP_IMM or
                (operand.imm & 0xFFFFFFFF) != direct_target):
            raise RuntimeError(
                "Exit-menu call/resume/target changed at %08x" % call_site)
        _vita_exit_menu_profile_instruction(img, resume_site)

    for owner, site, _event, _value, mnemonic in \
            VITA_EXIT_MENU_PROFILE_CONTROL_SPECS:
        if owner == root_rva:
            _vita_exit_menu_profile_instruction(img, site, mnemonic)

    if root_rva == 0x004B0010:
        _vita_exit_menu_profile_validate_xrefs(img)
        if (img.code_at(VITA_FULLSPEED_CONTINUE_CALL_MACHINE_RVA,
                        len(VITA_FULLSPEED_CONTINUE_CALL_MACHINE)) !=
                VITA_FULLSPEED_CONTINUE_CALL_MACHINE or
                img.code_at(VITA_FULLSPEED_GAME_CALL_MACHINE_RVA,
                            len(VITA_FULLSPEED_GAME_CALL_MACHINE)) !=
                VITA_FULLSPEED_GAME_CALL_MACHINE):
            raise RuntimeError(
                "Exit-menu gameplay qualifier machine chain changed")
        game_load = _vita_exit_menu_profile_instruction(
            img, VITA_FULLSPEED_GAME_CALL_MACHINE_RVA, "mov")
        game_call = _vita_exit_menu_profile_instruction(
            img, VITA_FULLSPEED_GAME_UPDATE_CALL_RVA, "call")
        game_operand = (game_load.operands[1]
                        if len(game_load.operands) == 2 else None)
        call_operand = (game_call.operands[0]
                        if len(game_call.operands) == 1 else None)
        if (game_operand is None or
                game_operand.type != T.cx.X86_OP_MEM or
                game_operand.mem.base != 0 or
                game_operand.mem.index != 0 or
                game_operand.mem.disp !=
                img.va(VITA_FULLSPEED_GAME_POINTER_RVA) or
                VITA_FULLSPEED_GAME_CALL_MACHINE_RVA + 1 not in
                img.reloc_rvas or
                call_operand is None or
                call_operand.type != T.cx.X86_OP_IMM or
                (call_operand.imm & 0xFFFFFFFF) != 0x002CDCF0):
            raise RuntimeError(
                "Exit-menu Game pointer/update provenance changed")
        second_work = _vita_exit_menu_profile_instruction(
            img, 0x004B0173, "mov")
        if (len(second_work.operands) != 2 or
                second_work.operands[0].type != T.cx.X86_OP_MEM or
                second_work.operands[0].mem.base != T.cx.X86_REG_EDI or
                second_work.operands[0].mem.index != 0 or
                second_work.operands[0].mem.disp != 0x001EA818 or
                second_work.operands[1].type != T.cx.X86_OP_IMM or
                second_work.operands[1].imm != 1):
            raise RuntimeError(
                "Exit-menu second caller work materialization changed")
        if img.code_at(
                VITA_EXIT_MENU_PROFILE_SECOND_CALL_PATH_RVA,
                len(VITA_EXIT_MENU_PROFILE_SECOND_CALL_PATH_MACHINE)) != \
                VITA_EXIT_MENU_PROFILE_SECOND_CALL_PATH_MACHINE:
            raise RuntimeError("Exit-menu second caller path changed")

    if root_rva == 0x004B4500:
        materialize = _vita_exit_menu_profile_instruction(
            img, VITA_EXIT_MENU_PROFILE_SLOT_SITE, "mov")
        if (len(materialize.operands) != 2 or
                materialize.operands[0].type != T.cx.X86_OP_REG or
                materialize.operands[0].reg != T.cx.X86_REG_EBX or
                materialize.operands[1].type != T.cx.X86_OP_MEM or
                materialize.operands[1].mem.base != T.cx.X86_REG_EBP or
                materialize.operands[1].mem.index != 0 or
                materialize.operands[1].mem.disp != 8):
            raise RuntimeError("Exit-menu slot provenance changed")

    if root_rva == 0x004B43D0:
        if img.code_at(
                VITA_EXIT_MENU_PROFILE_WORK_PREDICATE_RVA,
                len(VITA_EXIT_MENU_PROFILE_WORK_PREDICATE_MACHINE)) != \
                VITA_EXIT_MENU_PROFILE_WORK_PREDICATE_MACHINE:
            raise RuntimeError("Exit-menu work predicate changed")
        manager = _vita_exit_menu_profile_instruction(
            img, VITA_EXIT_MENU_PROFILE_WORK_PREDICATE_RVA, "mov")
        predicate = _vita_exit_menu_profile_instruction(
            img, 0x004B440C, "cmp")
        if (len(manager.operands) != 2 or
                manager.operands[0].type != T.cx.X86_OP_REG or
                manager.operands[0].reg != T.cx.X86_REG_ESI or
                manager.operands[1].type != T.cx.X86_OP_REG or
                manager.operands[1].reg != T.cx.X86_REG_ECX or
                len(predicate.operands) != 2 or
                predicate.operands[0].type != T.cx.X86_OP_MEM or
                predicate.operands[0].mem.base != T.cx.X86_REG_ESI or
                predicate.operands[0].mem.index != 0 or
                predicate.operands[0].mem.disp != 0x001EA818 or
                predicate.operands[1].type != T.cx.X86_OP_IMM or
                predicate.operands[1].imm != 0):
            raise RuntimeError("Exit-menu work predicate provenance changed")

    if root_rva == VITA_EXIT_MENU_PROFILE_CHECKSUM_TARGET:
        for site in (0x0025B398, 0x0025B4A8):
            if _vita_exit_menu_profile_instruction(
                    img, site, "ret").op_str != "8":
                raise RuntimeError("Exit-menu checksum RET 8 ABI changed")
        mode = _vita_exit_menu_profile_instruction(img, 0x0025B343, "mov")
        lengths = (
            _vita_exit_menu_profile_instruction(img, 0x0025B34D, "mov"),
            _vita_exit_menu_profile_instruction(img, 0x0025B475, "mov"),
        )
        if (len(mode.operands) != 2 or
                mode.operands[1].type != T.cx.X86_OP_MEM or
                mode.operands[1].mem.base != T.cx.X86_REG_ECX or
                mode.operands[1].mem.disp != 0x0C):
            raise RuntimeError("Exit-menu checksum mode provenance changed")
        for length in lengths:
            if (len(length.operands) != 2 or
                    length.operands[1].type != T.cx.X86_OP_MEM or
                    length.operands[1].mem.base != T.cx.X86_REG_EBP or
                    length.operands[1].mem.disp != 0x0C):
                raise RuntimeError(
                    "Exit-menu checksum length provenance changed")
        _vita_exit_menu_profile_validate_read_checksum_census(img)

    end_rva, count, last, body_sha256 = \
        VITA_EXIT_MENU_PROFILE_ROOT_SPECS[root_rva]
    body_bytes = img.code_at(root_rva, end_rva - root_rva)
    if (len(order) != count or order[0] != root_rva or
            order[-1] != last or
            hashlib.sha256(body_bytes).hexdigest() != body_sha256):
        raise RuntimeError(
            "Exit-menu body/order/extent changed at %08x" % root_rva)

    rendered_hooks = tuple(
        ins.address for ins, _stmts in body
        if (root_rva, ins.address) in
        VITA_EXIT_MENU_PROFILE_SITE_SPECS)
    if (frozenset(rendered_hooks) != expected or
            len(rendered_hooks) != len(expected)):
        raise RuntimeError(
            "Exit-menu renderer membership changed at %08x" % root_rva)
    return {"hooks": rendered_hooks}


def vita_save_checksum_fastpath_for_body(
        img, root_rva, insns, order, emit_image_base):
    """Authenticate the exact sub_0025b340 entry ABI and checksum body."""
    if root_rva != VITA_SAVE_CHECKSUM_FASTPATH_ROOT_RVA:
        return False
    if (os.path.getsize(img.path) != VITA_EXIT_MENU_PROFILE_PE_SIZE or
            _vita_pill_bloom_bypass_file_sha256(img.path) !=
            VITA_EXIT_MENU_PROFILE_PE_SHA256):
        raise RuntimeError("save-checksum fast-path input PE identity changed")

    raw_img = Image(img.path, img.orig_base)
    raw = raw_img.code_at(
        root_rva, VITA_SAVE_CHECKSUM_FASTPATH_END_RVA - root_rva)
    if (hashlib.sha256(raw).hexdigest() !=
            VITA_SAVE_CHECKSUM_FASTPATH_BODY_SHA256 or
            len(order) != VITA_SAVE_CHECKSUM_FASTPATH_INSNS or
            not order or order[0] != root_rva or
            order[-1] != 0x0025B4A8 or
            rva_sequence_sha256(order) !=
            VITA_SAVE_CHECKSUM_FASTPATH_ORDER_SHA256):
        raise RuntimeError("save-checksum body/CFG identity changed")

    calls = _vita_png_decode_profile_rel32_xrefs(img, root_rva)
    packed_calls = b"".join(
        site.to_bytes(4, "little") for site in calls)
    address_refs = tuple(
        rva for rva in sorted(img.reloc_rvas)
        if int.from_bytes(img.code_at(rva, 4), "little") == img.va(root_rva)
    )
    if (len(calls) != VITA_SAVE_CHECKSUM_FASTPATH_CALLER_COUNT or
            hashlib.sha256(packed_calls).hexdigest() !=
            VITA_SAVE_CHECKSUM_FASTPATH_CALLERS_SHA256 or address_refs):
        raise RuntimeError("save-checksum whole-program callers changed")

    required = {
        0x0025B340: ("push", "ebp"),
        0x0025B343: ("mov", "eax, dword ptr [ecx + 0xc]"),
        0x0025B34D: ("mov", "edi, dword ptr [ebp + 0xc]"),
        0x0025B35A: ("mov", "ebx, dword ptr [ebp + 8]"),
        0x0025B360: ("movzx", "edx, byte ptr [ecx + 4]"),
        0x0025B368: ("mov", "byte ptr [edx + ecx], al"),
        0x0025B37F: ("shr", "edx, 1"),
        0x0025B381: ("shl", "eax, 0x1f"),
        0x0025B38A: ("add", "edx, dword ptr [ecx]"),
        0x0025B38C: ("mov", "dword ptr [ecx + 8], edx"),
        0x0025B3C0: ("shr", "eax, 1"),
        0x0025B3D5: ("sar", "edx, 1"),
        0x0025B3EA: ("sar", "esi, 1"),
        0x0025B3FF: ("sar", "edx, 1"),
        0x0025B414: ("sar", "esi, 1"),
        0x0025B429: ("sar", "edx, 1"),
        0x0025B43E: ("sar", "esi, 1"),
        0x0025B453: ("sar", "edx, 1"),
        0x0025B470: ("mov", "ebx, dword ptr [ecx + 8]"),
        0x0025B475: ("mov", "edi, dword ptr [ebp + 0xc]"),
        0x0025B478: ("not", "ebx"),
        0x0025B48E: ("shr", "ebx, 8"),
        0x0025B498: ("mov", "dword ptr [ecx + 8], ebx"),
        0x0025B49F: ("not", "ebx"),
        0x0025B4A1: ("mov", "dword ptr [ecx + 8], ebx"),
        0x0025B398: ("ret", "8"),
        0x0025B4A8: ("ret", "8"),
    }
    for site, expected in required.items():
        instruction = insns.get(site)
        if (instruction is None or
                (instruction.mnemonic, instruction.op_str) != expected):
            raise RuntimeError(
                "save-checksum ABI/algorithm changed at %08x" % site)

    table_sentinel = insns.get(0x0025B3A4)
    table_store = insns.get(0x0025B45C)
    table_load = insns.get(0x0025B491)
    # `img` is the frozen DEFAULT_BASE proof image while `insns` belongs to
    # the image being emitted.  Absolute operands therefore use the emitted
    # base (0x98000000 for Vita), not the proof image's base.
    expected_table = ((emit_image_base +
                       VITA_SAVE_CHECKSUM_FASTPATH_TABLE_RVA) & 0xFFFFFFFF)
    if (table_sentinel is None or len(table_sentinel.operands) != 2 or
            table_sentinel.operands[0].type != T.cx.X86_OP_MEM or
            (table_sentinel.operands[0].mem.disp & 0xFFFFFFFF) !=
            ((expected_table + 4) & 0xFFFFFFFF) or
            table_store is None or len(table_store.operands) != 2 or
            table_store.operands[0].type != T.cx.X86_OP_MEM or
            table_store.operands[0].mem.index != T.cx.X86_REG_EDI or
            table_store.operands[0].mem.scale != 4 or
            (table_store.operands[0].mem.disp & 0xFFFFFFFF) !=
            expected_table or
            table_load is None or len(table_load.operands) != 2 or
            table_load.operands[1].type != T.cx.X86_OP_MEM or
            table_load.operands[1].mem.index != T.cx.X86_REG_EDX or
            table_load.operands[1].mem.scale != 4 or
            (table_load.operands[1].mem.disp & 0xFFFFFFFF) !=
            expected_table):
        raise RuntimeError("save-checksum lazy table provenance changed")
    return True


def vita_save_reader_fastpath_for_body(
        img, root_rva, insns, order, emit_image_base):
    """Authenticate the unique memory Save Reader read slot and its ABI."""
    if root_rva != VITA_SAVE_READER_FASTPATH_ROOT_RVA:
        return False
    if (os.path.getsize(img.path) != VITA_EXIT_MENU_PROFILE_PE_SIZE or
            _vita_pill_bloom_bypass_file_sha256(img.path) !=
            VITA_EXIT_MENU_PROFILE_PE_SHA256):
        raise RuntimeError("save-reader fast-path input PE identity changed")

    raw_img = Image(img.path, img.orig_base)
    raw = raw_img.code_at(
        root_rva, VITA_SAVE_READER_FASTPATH_END_RVA - root_rva)
    if (hashlib.sha256(raw).hexdigest() !=
            VITA_SAVE_READER_FASTPATH_BODY_SHA256 or
            len(order) != VITA_SAVE_READER_FASTPATH_INSNS or
            not order or order[0] != root_rva or
            order[-1] != 0x0025BAA0 or
            rva_sequence_sha256(order) !=
            VITA_SAVE_READER_FASTPATH_ORDER_SHA256):
        raise RuntimeError("save-reader body/CFG identity changed")

    calls = _vita_png_decode_profile_rel32_xrefs(raw_img, root_rva)
    address_refs = tuple(
        rva for rva in sorted(raw_img.reloc_rvas)
        if int.from_bytes(raw_img.code_at(rva, 4), "little") ==
        raw_img.va(root_rva)
    )
    vtable = raw_img.code_at(
        VITA_SAVE_READER_VTABLE_RVA, VITA_SAVE_READER_VTABLE_BYTES)
    emitted_img = Image(img.path, emit_image_base)
    emitted_slot = int.from_bytes(
        emitted_img.code_at(VITA_SAVE_READER_VTABLE_READ_SLOT_RVA, 4),
        "little")
    if (calls or
            address_refs != (VITA_SAVE_READER_VTABLE_READ_SLOT_RVA,) or
            hashlib.sha256(vtable).hexdigest() !=
            VITA_SAVE_READER_VTABLE_SHA256 or
            int.from_bytes(vtable[0x14:0x18], "little") !=
            raw_img.va(root_rva) or
            emitted_slot != emitted_img.va(root_rva)):
        raise RuntimeError("save-reader unique vtable provenance changed")

    required = {
        0x0025BA60: ("push", "ebp"),
        0x0025BA63: ("mov", "eax, dword ptr [ebp + 0xc]"),
        0x0025BA66: ("imul", "eax, dword ptr [ebp + 0x10]"),
        0x0025BA6C: ("mov", "edi, ecx"),
        0x0025BA6E: ("mov", "esi, dword ptr [edi + 0x1c]"),
        0x0025BA71: ("sub", "esi, dword ptr [edi + 0x18]"),
        0x0025BA76: ("cmovb", "esi, eax"),
        0x0025BA79: ("mov", "eax, dword ptr [edi + 0x10]"),
        0x0025BA7C: ("add", "eax, dword ptr [edi + 0x18]"),
        0x0025BA84: ("call", "0x5ec14c"),
        0x0025BA89: ("add", "dword ptr [edi + 0x18], esi"),
        0x0025BA8F: ("mov", "ecx, dword ptr [edi + 0x18]"),
        0x0025BA92: ("mov", "eax, esi"),
        0x0025BA94: ("cmp", "ecx, dword ptr [edi + 0x1c]"),
        0x0025BA97: ("setae", "cl"),
        0x0025BA9A: ("mov", "byte ptr [edi + 0x21], cl"),
        0x0025BAA0: ("ret", "0xc"),
    }
    for site, expected in required.items():
        instruction = insns.get(site)
        if (instruction is None or
                (instruction.mnemonic, instruction.op_str) != expected):
            raise RuntimeError(
                "save-reader ABI/algorithm changed at %08x" % site)

    thunk = raw_img.code_at(VITA_SAVE_READER_MEMCPY_THUNK_RVA, 6)
    if (thunk[:2] != b"\xff\x25" or
            int.from_bytes(thunk[2:], "little") !=
            raw_img.va(VITA_SAVE_READER_MEMCPY_IAT_RVA)):
        raise RuntimeError("save-reader memcpy import provenance changed")
    return True


def vita_save_read32_fused_for_body(
        img, root_rva, insns, order, emit_image_base):
    """Authenticate the scalar read32 wrapper and both retained callees."""
    if root_rva != VITA_SAVE_READ32_FUSED_ROOT_RVA:
        return False
    if (os.path.getsize(img.path) != VITA_EXIT_MENU_PROFILE_PE_SIZE or
            _vita_pill_bloom_bypass_file_sha256(img.path) !=
            VITA_EXIT_MENU_PROFILE_PE_SHA256):
        raise RuntimeError("save-read32 fused input PE identity changed")

    raw_img = Image(img.path, img.orig_base)
    raw = raw_img.code_at(
        root_rva, VITA_SAVE_READ32_FUSED_END_RVA - root_rva)
    if (hashlib.sha256(raw).hexdigest() !=
            VITA_SAVE_READ32_FUSED_BODY_SHA256 or
            len(order) != VITA_SAVE_READ32_FUSED_INSNS or
            not order or order[0] != root_rva or
            order[-1] != 0x0052EABC or
            rva_sequence_sha256(order) !=
            VITA_SAVE_READ32_FUSED_ORDER_SHA256):
        raise RuntimeError("save-read32 fused body/CFG identity changed")

    calls = _vita_png_decode_profile_rel32_xrefs(raw_img, root_rva)
    packed_calls = b"".join(
        site.to_bytes(4, "little") for site in calls)
    address_refs = tuple(
        rva for rva in sorted(raw_img.reloc_rvas)
        if int.from_bytes(raw_img.code_at(rva, 4), "little") ==
        raw_img.va(root_rva)
    )
    if (len(calls) != VITA_SAVE_READ32_FUSED_CALLER_COUNT or
            hashlib.sha256(packed_calls).hexdigest() !=
            VITA_SAVE_READ32_FUSED_CALLERS_SHA256 or address_refs):
        raise RuntimeError("save-read32 fused whole-program callers changed")

    required = {
        0x0052EA90: ("push", "ebp"),
        0x0052EA91: ("mov", "ebp, esp"),
        0x0052EA93: ("push", "esi"),
        0x0052EA94: ("mov", "esi, dword ptr [ebp + 8]"),
        0x0052EA97: ("push", "edi"),
        0x0052EA98: ("mov", "edi, ecx"),
        0x0052EA9A: ("push", "1"),
        0x0052EA9C: ("push", "4"),
        0x0052EA9E: ("push", "esi"),
        0x0052EA9F: ("mov", "ecx, dword ptr [edi]"),
        0x0052EAA1: ("mov", "eax, dword ptr [ecx]"),
        0x0052EAA3: ("call", "dword ptr [eax + 0x14]"),
        0x0052EAA6: ("mov", "eax, dword ptr [esi]"),
        0x0052EAA8: ("lea", "ecx, [edi + 0xc]"),
        0x0052EAAB: ("mov", "dword ptr [ebp + 8], eax"),
        0x0052EAAE: ("lea", "eax, [ebp + 8]"),
        0x0052EAB1: ("push", "4"),
        0x0052EAB3: ("push", "eax"),
        0x0052EAB4: ("call", "0x25b340"),
        0x0052EAB9: ("pop", "edi"),
        0x0052EABA: ("pop", "esi"),
        0x0052EABB: ("pop", "ebp"),
        0x0052EABC: ("ret", "4"),
    }
    for site, expected in required.items():
        instruction = insns.get(site)
        if (instruction is None or
                (instruction.mnemonic, instruction.op_str) != expected):
            raise RuntimeError(
                "save-read32 fused ABI/algorithm changed at %08x" % site)

    # Pin the indirect edge to the exact Save Reader class and leaf.  The
    # emitted-base check also proves the slot relocation used by Vita output.
    vtable = raw_img.code_at(
        VITA_SAVE_READER_VTABLE_RVA, VITA_SAVE_READER_VTABLE_BYTES)
    emitted_img = Image(img.path, emit_image_base)
    emitted_slot = int.from_bytes(
        emitted_img.code_at(VITA_SAVE_READER_VTABLE_READ_SLOT_RVA, 4),
        "little")
    if (hashlib.sha256(vtable).hexdigest() !=
            VITA_SAVE_READER_VTABLE_SHA256 or
            int.from_bytes(vtable[0x14:0x18], "little") !=
            raw_img.va(VITA_SAVE_READER_FASTPATH_ROOT_RVA) or
            emitted_slot != emitted_img.va(
                VITA_SAVE_READER_FASTPATH_ROOT_RVA)):
        raise RuntimeError("save-read32 fused reader edge changed")
    return True


def vita_save_reader_direct_edges_for_body(
        img, root_rva, insns, order, body):
    """Pin three complete parser roots and their Save Reader call sites."""
    spec = VITA_SAVE_READER_DIRECT_EDGE_ROOT_SPECS.get(root_rva)
    if spec is None:
        return ()
    if (os.path.getsize(img.path) != VITA_EXIT_MENU_PROFILE_PE_SIZE or
            _vita_pill_bloom_bypass_file_sha256(img.path) !=
            VITA_EXIT_MENU_PROFILE_PE_SHA256):
        raise RuntimeError("save-reader direct-edge input PE identity changed")

    raw_img = Image(img.path, img.orig_base)
    raw = raw_img.code_at(root_rva, spec["end"] - root_rva)
    if (hashlib.sha256(raw).hexdigest() != spec["body_sha256"] or
            len(order) != spec["insns"] or not order or
            order[0] != root_rva or order[-1] != spec["last"] or
            rva_sequence_sha256(order) != spec["order_sha256"]):
        raise RuntimeError(
            "save-reader direct-edge body/CFG changed at %08x" % root_rva)

    callers = _vita_png_decode_profile_rel32_xrefs(raw_img, root_rva)
    packed_callers = b"".join(
        site.to_bytes(4, "little") for site in callers)
    address_refs = tuple(
        rva for rva in sorted(raw_img.reloc_rvas)
        if int.from_bytes(raw_img.code_at(rva, 4), "little") ==
        raw_img.va(root_rva)
    )
    if (len(callers) != spec["callers"] or
            hashlib.sha256(packed_callers).hexdigest() !=
            spec["callers_sha256"] or address_refs):
        raise RuntimeError(
            "save-reader direct-edge callers changed at %08x" % root_rva)

    sites = []
    for instruction, _statements in body:
        if (instruction.mnemonic != "call" or
                instruction.op_str != "dword ptr [eax + 0x14]"):
            continue
        operands = instruction.operands
        operand = operands[0] if len(operands) == 1 else None
        mem = (operand.mem if operand is not None and
               operand.type == T.cx.X86_OP_MEM else None)
        if (mem is None or mem.base != T.cx.X86_REG_EAX or
                mem.index not in (0, T.cx.X86_REG_INVALID) or
                mem.disp != 0x14 or operand.size != 4):
            raise RuntimeError(
                "save-reader direct-edge ABI changed at %08x" %
                instruction.address)
        sites.append(instruction.address)
    sites = tuple(sites)
    if (len(sites) != spec["sites"] or
            rva_sequence_sha256(sites) != spec["sites_sha256"]):
        raise RuntimeError(
            "save-reader direct-edge site census changed at %08x" % root_rva)
    return sites


def vita_memset_thunk_fastpath_for_body(
        img, root_rva, insns, order, emit_image_base):
    """Authenticate the frozen memset import thunk and all direct callers."""
    if root_rva != VITA_MEMSET_THUNK_FASTPATH_ROOT_RVA:
        return False
    if (os.path.getsize(img.path) != VITA_EXIT_MENU_PROFILE_PE_SIZE or
            _vita_pill_bloom_bypass_file_sha256(img.path) !=
            VITA_EXIT_MENU_PROFILE_PE_SHA256):
        raise RuntimeError("memset-thunk fast-path input PE identity changed")

    raw_img = Image(img.path, img.orig_base)
    raw = raw_img.code_at(
        root_rva, VITA_MEMSET_THUNK_FASTPATH_END_RVA - root_rva)
    if (hashlib.sha256(raw).hexdigest() !=
            VITA_MEMSET_THUNK_FASTPATH_BODY_SHA256 or
            len(order) != VITA_MEMSET_THUNK_FASTPATH_INSNS or
            order != [root_rva] or
            rva_sequence_sha256(order) !=
            VITA_MEMSET_THUNK_FASTPATH_ORDER_SHA256):
        raise RuntimeError("memset-thunk body/CFG identity changed")

    calls = _vita_png_decode_profile_rel32_xrefs(raw_img, root_rva)
    packed_calls = b"".join(
        site.to_bytes(4, "little") for site in calls)
    address_refs = tuple(
        rva for rva in sorted(raw_img.reloc_rvas)
        if int.from_bytes(raw_img.code_at(rva, 4), "little") ==
        raw_img.va(root_rva)
    )
    if (len(calls) != VITA_MEMSET_THUNK_FASTPATH_CALLER_COUNT or
            hashlib.sha256(packed_calls).hexdigest() !=
            VITA_MEMSET_THUNK_FASTPATH_CALLERS_SHA256 or address_refs or
            not set(VITA_MEMSET_THUNK_FASTPATH_GAMESTATE_SITES).issubset(
                calls)):
        raise RuntimeError("memset-thunk whole-program callers changed")

    imports = read_imports(img.path)
    if (len(imports) <= VITA_MEMSET_THUNK_FASTPATH_IMPORT_ID or
            imports[VITA_MEMSET_THUNK_FASTPATH_IMPORT_ID] !=
            (VITA_MEMSET_THUNK_FASTPATH_IAT_RVA,
             VITA_MEMSET_THUNK_FASTPATH_IMPORT_NAME)):
        raise RuntimeError("memset-thunk dense import identity changed")

    instruction = insns.get(root_rva)
    operand = (instruction.operands[0] if instruction is not None and
               len(instruction.operands) == 1 else None)
    expected_iat = ((emit_image_base +
                     VITA_MEMSET_THUNK_FASTPATH_IAT_RVA) & 0xFFFFFFFF)
    if (instruction is None or instruction.mnemonic != "jmp" or
            instruction.op_str !=
            "dword ptr [0x%08x]" % expected_iat or
            operand is None or operand.type != T.cx.X86_OP_MEM or
            operand.mem.base not in (0, T.cx.X86_REG_INVALID) or
            operand.mem.index not in (0, T.cx.X86_REG_INVALID) or
            (operand.mem.disp & 0xFFFFFFFF) != expected_iat or
            operand.size != 4):
        raise RuntimeError("memset-thunk IAT dispatch identity changed")
    return True


def vita_kage_mutex_seam_for_body(img, root_rva, insns, order, sync_iat_sites):
    """Authenticate one KAGE mutex wrapper for the native Lock/Unlock seam.

    Returns the seam spec for the two frozen roots, None for every other
    root.  The refcount sync-IAT authenticator has already pinned the body
    bytes, the CFG order, the callers, the vtable slots and the IAT sites of
    both roots (it raises on drift); this function requires that proof to
    have selected every site and pins in addition each instruction whose
    effect host_vita_kage_mutex_seam.c replays natively."""
    spec = VITA_KAGE_MUTEX_SEAM_SPECS.get(root_rva)
    if spec is None:
        return None
    if (os.path.getsize(img.path) != VITA_EXIT_MENU_PROFILE_PE_SIZE or
            _vita_pill_bloom_bypass_file_sha256(img.path) !=
            VITA_EXIT_MENU_PROFILE_PE_SHA256):
        raise RuntimeError("KAGE mutex seam input PE identity changed")
    owner = VITA_REFCOUNT_SYNC_IAT_ROOT_SPECS[root_rva]
    selected = tuple(site["site"] for site in sync_iat_sites)
    expected = tuple(site for site, _slot, _name in owner["sites"])
    if selected != expected or len(order) != owner["insns"]:
        raise RuntimeError(
            "KAGE mutex seam requires the authenticated sync-IAT sites at "
            "%08x" % root_rva)
    for site, want in spec["required"].items():
        instruction = insns.get(site)
        if (instruction is None or
                (instruction.mnemonic, instruction.op_str) != want):
            raise RuntimeError(
                "KAGE mutex seam ABI/algorithm changed at %08x" % site)
    return spec


def render_vita_kage_mutex_seam_declaration(spec):
    """The fenced extern declaration of the seam helper (body prologue)."""
    return (
        VITA_KAGE_MUTEX_SEAM_FENCE,
        "    extern int %s(CPU *__restrict);" % spec["helper"],
        "#endif",
    )


def render_vita_kage_mutex_seam(spec):
    """The fenced early return ahead of the first translated instruction.

    Written in the CPU-struct spelling on purpose: gpr_locals brackets it
    with GUEST_GPR_FLUSH/RELOAD, so the helper sees the published register
    file and a handled call returns with the CPU struct authoritative."""
    return (
        VITA_KAGE_MUTEX_SEAM_FENCE,
        "    /* %s */" % spec["marker"],
        "    if (%s(c)) return;" % spec["helper"],
        "#endif",
    )


def vita_kage_mutex_seam_packing_bytes(spec):
    """Bytes the seam adds to a body's legacy_text(): subtracted from the
    packing size so unit membership stays what it was before the seam."""
    return sum(len(line) + 1
               for line in (render_vita_kage_mutex_seam_declaration(spec) +
                            render_vita_kage_mutex_seam(spec)))
def vita_floor_thunk_fastpath_enabled():
    """Generation-time switch for the floor thunk seam (default off)."""
    value = os.environ.get(VITA_FLOOR_THUNK_FASTPATH_ENV, "0")
    if value not in ("0", "1"):
        raise ValueError("%s must be 0 or 1, not %r" %
                         (VITA_FLOOR_THUNK_FASTPATH_ENV, value))
    return value == "1"


def vita_floor_thunk_fastpath_for_body(
        img, root_rva, insns, order, emit_image_base):
    """Authenticate the frozen floor import thunk and all direct callers."""
    if root_rva != VITA_FLOOR_THUNK_FASTPATH_ROOT_RVA:
        return False
    if not vita_floor_thunk_fastpath_enabled():
        return False
    if (os.path.getsize(img.path) != VITA_EXIT_MENU_PROFILE_PE_SIZE or
            _vita_pill_bloom_bypass_file_sha256(img.path) !=
            VITA_EXIT_MENU_PROFILE_PE_SHA256):
        raise RuntimeError("floor-thunk fast-path input PE identity changed")

    raw_img = Image(img.path, img.orig_base)
    raw = raw_img.code_at(
        root_rva, VITA_FLOOR_THUNK_FASTPATH_END_RVA - root_rva)
    if (hashlib.sha256(raw).hexdigest() !=
            VITA_FLOOR_THUNK_FASTPATH_BODY_SHA256 or
            len(order) != VITA_FLOOR_THUNK_FASTPATH_INSNS or
            order != [root_rva] or
            rva_sequence_sha256(order) !=
            VITA_FLOOR_THUNK_FASTPATH_ORDER_SHA256):
        raise RuntimeError("floor-thunk body/CFG identity changed")

    calls = _vita_png_decode_profile_rel32_xrefs(raw_img, root_rva)
    packed_calls = b"".join(
        site.to_bytes(4, "little") for site in calls)
    address_refs = tuple(
        rva for rva in sorted(raw_img.reloc_rvas)
        if int.from_bytes(raw_img.code_at(rva, 4), "little") ==
        raw_img.va(root_rva)
    )
    if (len(calls) != VITA_FLOOR_THUNK_FASTPATH_CALLER_COUNT or
            hashlib.sha256(packed_calls).hexdigest() !=
            VITA_FLOOR_THUNK_FASTPATH_CALLERS_SHA256 or address_refs or
            not set(VITA_FLOOR_THUNK_FASTPATH_HOT_SITES).issubset(calls)):
        raise RuntimeError("floor-thunk whole-program callers changed")

    imports = read_imports(img.path)
    if (len(imports) <= VITA_FLOOR_THUNK_FASTPATH_IMPORT_ID or
            imports[VITA_FLOOR_THUNK_FASTPATH_IMPORT_ID] !=
            (VITA_FLOOR_THUNK_FASTPATH_IAT_RVA,
             VITA_FLOOR_THUNK_FASTPATH_IMPORT_NAME)):
        raise RuntimeError("floor-thunk dense import identity changed")

    instruction = insns.get(root_rva)
    operand = (instruction.operands[0] if instruction is not None and
               len(instruction.operands) == 1 else None)
    expected_iat = ((emit_image_base +
                     VITA_FLOOR_THUNK_FASTPATH_IAT_RVA) & 0xFFFFFFFF)
    if (instruction is None or instruction.mnemonic != "jmp" or
            instruction.op_str !=
            "dword ptr [0x%08x]" % expected_iat or
            operand is None or operand.type != T.cx.X86_OP_MEM or
            operand.mem.base not in (0, T.cx.X86_REG_INVALID) or
            operand.mem.index not in (0, T.cx.X86_REG_INVALID) or
            (operand.mem.disp & 0xFFFFFFFF) != expected_iat or
            operand.size != 4):
        raise RuntimeError("floor-thunk IAT dispatch identity changed")
    return True


def vita_shader_attrib_fastpath_for_body(
        img, root_rva, insns, order, emit_image_base):
    """Authenticate one Shader::EnableAttribs/DisableAttribs root.

    Returns the root's spec (kind, marker, helper) or None.  Pins: the frozen
    PE, the body bytes and emitted CFG order, the two 8-entry format jump
    tables, the unique Shader vtable and its slot as the only reference to the
    root (no rel32 caller, no other address word), the `ret 0xc` epilogue and
    every `call dword ptr [slot]` operand against the emitted image base."""
    spec = VITA_SHADER_ATTRIB_FASTPATH_ROOTS.get(root_rva)
    if spec is None:
        return None
    if (os.path.getsize(img.path) != VITA_EXIT_MENU_PROFILE_PE_SIZE or
            _vita_pill_bloom_bypass_file_sha256(img.path) !=
            VITA_EXIT_MENU_PROFILE_PE_SHA256):
        raise RuntimeError("shader-attrib fast-path input PE identity changed")

    raw_img = Image(img.path, img.orig_base)
    raw = raw_img.code_at(root_rva, spec["end_rva"] - root_rva)
    if (hashlib.sha256(raw).hexdigest() != spec["body_sha256"] or
            len(order) != spec["insns"] or
            not order or order[0] != root_rva or
            order[-1] != spec["last_rva"] or
            rva_sequence_sha256(order) != spec["order_sha256"]):
        raise RuntimeError(
            "shader-attrib body/CFG identity changed at %08x" % root_rva)
    tables = raw_img.code_at(VITA_SHADER_ATTRIB_FASTPATH_TABLES_RVA,
                             VITA_SHADER_ATTRIB_FASTPATH_TABLES_BYTES)
    if (hashlib.sha256(tables).hexdigest() !=
            VITA_SHADER_ATTRIB_FASTPATH_TABLES_SHA256):
        raise RuntimeError("shader-attrib format jump tables changed")

    calls = _vita_png_decode_profile_rel32_xrefs(raw_img, root_rva)
    address_refs = tuple(
        rva for rva in sorted(raw_img.reloc_rvas)
        if int.from_bytes(raw_img.code_at(rva, 4), "little") ==
        raw_img.va(root_rva)
    )
    vtable = raw_img.code_at(VITA_SHADER_ATTRIB_FASTPATH_VTABLE_RVA,
                             VITA_SHADER_ATTRIB_FASTPATH_VTABLE_BYTES)
    slot_offset = (spec["vtable_slot_rva"] -
                   VITA_SHADER_ATTRIB_FASTPATH_VTABLE_RVA)
    emitted_img = Image(img.path, emit_image_base)
    emitted_slot = int.from_bytes(
        emitted_img.code_at(spec["vtable_slot_rva"], 4), "little")
    if (calls or address_refs != (spec["vtable_slot_rva"],) or
            hashlib.sha256(vtable).hexdigest() !=
            VITA_SHADER_ATTRIB_FASTPATH_VTABLE_SHA256 or
            int.from_bytes(vtable[slot_offset:slot_offset + 4], "little") !=
            raw_img.va(root_rva) or
            emitted_slot != emitted_img.va(root_rva)):
        raise RuntimeError(
            "shader-attrib unique vtable provenance changed at %08x" %
            root_rva)

    epilogue = insns.get(spec["last_rva"])
    if (epilogue is None or epilogue.mnemonic != "ret" or
            epilogue.op_str != "0xc"):
        raise RuntimeError(
            "shader-attrib thiscall epilogue changed at %08x" % root_rva)
    for site, slot_rva in sorted(spec["call_sites"].items()):
        instruction = insns.get(site)
        operand = (instruction.operands[0] if instruction is not None and
                   len(instruction.operands) == 1 else None)
        expected_slot = (emit_image_base + slot_rva) & 0xFFFFFFFF
        if (instruction is None or instruction.mnemonic != "call" or
                instruction.op_str !=
                "dword ptr [0x%08x]" % expected_slot or
                operand is None or operand.type != T.cx.X86_OP_MEM or
                operand.mem.base not in (0, T.cx.X86_REG_INVALID) or
                operand.mem.index not in (0, T.cx.X86_REG_INVALID) or
                (operand.mem.disp & 0xFFFFFFFF) != expected_slot or
                operand.size != 4):
            raise RuntimeError(
                "shader-attrib GL slot call identity changed at %08x" % site)
    return spec


def _vita_shader_attrib_packing_delta(text):
    """Bytes the shader-attrib declaration/seam blocks add to a body's text.

    Subtracted from the packing size so unit membership stays exactly what
    the frozen corpus had (CMake pins the owner unit of every seam)."""
    stripped = []
    skipping = False
    for line in text.split("\n"):
        if line == VITA_SHADER_ATTRIB_FASTPATH_GUARD:
            skipping = True
            continue
        if skipping:
            if line == "#endif":
                skipping = False
            continue
        stripped.append(line)
    return unit_packing_size(text) - unit_packing_size("\n".join(stripped))


def require_upstream_contracts():
    functions_recipe_id, _ = Funcs.contract_recipe()
    functions_manifest = BC.require_manifest(
        Funcs.MANIFEST,
        "functions",
        functions_recipe_id,
        {"functions.json": FUNCS},
    )
    bounds_recipe_id, _ = Bounds.contract_recipe(
        functions_manifest["output_set_id"]
    )
    bounds_manifest = BC.require_manifest(
        Bounds.MANIFEST,
        "bounds",
        bounds_recipe_id,
        {"bounds.json": BOUNDS},
    )
    return functions_manifest, bounds_manifest


def contract_recipe(functions_manifest, bounds_manifest):
    here = os.path.dirname(os.path.abspath(__file__))
    source_names = (
        "gen_all.py", "build_one.py", "emit.py", "trans.py", "image.py",
        "iat_meta.py", "sweep2.py", "build_contract.py", "leaf_inline.py",
        "sse_lower.py", "gpr_locals.py",
    )
    inputs = {
        "input/isaac-ng.exe.unpacked.exe": EXE,
        "runtime/manual_kage.h": MANUAL_KAGE_HEADER,
        "runtime/manual_portable.h": MANUAL_PORTABLE_HEADER,
        "runtime/manual_kage.c": MANUAL_KAGE_SOURCE,
        "runtime/manual_portable.c": MANUAL_PORTABLE_SOURCE,
        "runtime/kage_vita_fx_rollback.h":
            VITA_FXLAYERS_ROLLBACK_HEADER,
        "upstream/functions.output_set": BC.digest(
            functions_manifest["output_set_id"]
        ),
        "upstream/bounds.output_set": BC.digest(
            bounds_manifest["output_set_id"]
        ),
    }
    for name in source_names:
        inputs["source/recomp/" + name] = os.path.join(here, name)
    return BC.recipe(
        "generate",
        inputs,
        {
            "target_bytes": TARGET_BYTES,
            "image_base": IMAGE_BASE,
            "coverage_abi_version": COVERAGE_ABI_VERSION,
            "coverage_header_size": COVERAGE_HEADER_SIZE,
            "coverage_semantics": (
                "canonical-rva/function; iat-slot/import; "
                "root-case-edge/case"
            ),
            # Generation-time switches that change the emitted text: two
            # corpora that differ only in a switch must not share a
            # generation id (guest_table.c, GUEST_COVERAGE_GENERATION_ID,
            # the room-entry receipt).  Header knobs (GUEST_GPR_LOCAL,
            # GUEST_SSE_LOWER as a -D) are not generation inputs.
            "sse_lower": sse_lower.enabled(),
            "floor_thunk_fastpath": vita_floor_thunk_fastpath_enabled(),
        },
        BC.tool_ids(),
    )


def generated_output_paths():
    names = sorted(
        name for name in os.listdir(OUTDIR)
        if name.endswith((".c", ".h")) or name == COVERAGE_JSON_NAME
    )
    return {name: os.path.join(OUTDIR, name) for name in names}


def _open_generated_text(path):
    """Open one generated C/header artifact with LF bytes on every host."""
    return open(path, "w", encoding="utf-8", newline="\n")


def require_generation_manifest():
    functions_manifest, bounds_manifest = require_upstream_contracts()
    recipe_id, _ = contract_recipe(functions_manifest, bounds_manifest)
    return BC.require_manifest(
        MANIFEST,
        "generate",
        recipe_id,
        generated_output_paths(),
    )


def generation_identity(generation_manifest):
    """Return the exact C identity carried by one validated generation.

    Downstream stages call this only after :func:`require_generation_manifest`,
    but keep the conversion fail-closed as well: neither a missing recipe nor
    non-SHA text may reach a forced C header as a string or identifier.
    """
    if not isinstance(generation_manifest, dict):
        raise BC.ManifestFormatError("generation manifest must be an object")
    if generation_manifest.get("stage") != "generate":
        raise BC.ManifestFormatError("generation manifest has the wrong stage")
    try:
        recipe_id = BC.digest(generation_manifest["recipe_id"]).value
    except KeyError as exc:
        raise BC.ManifestFormatError(
            "generation manifest has no recipe_id"
        ) from exc
    return "gen:" + recipe_id, "guest_generation_" + recipe_id


def _canonical_json_bytes(value):
    return json.dumps(
        value, sort_keys=True, separators=(",", ":"),
        ensure_ascii=False, allow_nan=False,
    ).encode("utf-8")


def _coverage_u32_rows_sha256(rows):
    """Hash fixed-width semantic RVA rows without host-endian ambiguity."""
    digest = hashlib.sha256()
    for row in rows:
        for value in row:
            if isinstance(value, bool) or not isinstance(value, int) or not \
                    0 <= value <= 0xFFFFFFFF:
                raise RuntimeError("coverage hash row contains non-uint32")
            digest.update(value.to_bytes(4, "little"))
    return digest.hexdigest()


def _coverage_imports_sha256(imports):
    digest = hashlib.sha256()
    for slot_rva, name in imports:
        digest.update(slot_rva.to_bytes(4, "little"))
        digest.update(name.encode("utf-8"))
        digest.update(b"\0")
    return digest.hexdigest()


def build_coverage_inventory(canonical_roots, imports, switch_info):
    """Build and freeze the three dense semantic coverage ID spaces.

    IDs are positions in sorted semantic keys.  They never depend on output
    unit boundaries, worker scheduling or C symbol spelling.  Physical hook
    occurrence validation is deliberately separate: one function RVA can be
    reached through a canonical label copied into another translated body,
    and one case key can occur at several physical switch sites.
    """
    function_rvas = tuple(sorted(canonical_roots))
    if (len(function_rvas) != UNIFIED_CANONICAL_ROOTS or
            len(set(function_rvas)) != len(function_rvas)):
        raise RuntimeError("coverage function ID universe changed")
    function_hash = _coverage_u32_rows_sha256(
        (rva,) for rva in function_rvas)
    if function_hash != COVERAGE_FUNCTION_RVAS_SHA256:
        raise RuntimeError(
            "coverage function RVA hash changed: %s" % function_hash)
    function_ids = {rva: index
                    for index, rva in enumerate(function_rvas)}
    for macro, rva, expected_id in COVERAGE_MANUAL_SPECS:
        actual_id = function_ids.get(rva)
        if actual_id != expected_id:
            raise RuntimeError(
                "%s changed ID: %r != %d"
                % (macro, actual_id, expected_id))

    import_rows = tuple(sorted(imports))
    if (len(import_rows) != COVERAGE_EXPECTED_IMPORTS or
            len({slot for slot, _name in import_rows}) != len(import_rows) or
            any(isinstance(slot, bool) or not isinstance(slot, int) or
                not 0 <= slot <= 0xFFFFFFFF or not isinstance(name, str) or
                not name for slot, name in import_rows)):
        raise RuntimeError("coverage import ID universe changed")
    import_hash = _coverage_imports_sha256(import_rows)
    if import_hash != COVERAGE_IMPORTS_SHA256:
        raise RuntimeError(
            "coverage import metadata hash changed: %s" % import_hash)
    import_ids = {slot: index
                  for index, (slot, _name) in enumerate(import_rows)}

    case_pairs = tuple(sorted(
        (root, entry)
        for root, info in switch_info.items()
        for entry in info["entries"]
    ))
    if (len(case_pairs) != COVERAGE_EXPECTED_CASES or
            len(set(case_pairs)) != len(case_pairs) or
            any(root not in canonical_roots for root, _entry in case_pairs)):
        raise RuntimeError("coverage case ID universe changed")
    case_hash = _coverage_u32_rows_sha256(case_pairs)
    if case_hash != COVERAGE_CASES_SHA256:
        raise RuntimeError("coverage case-pair hash changed: %s" % case_hash)
    case_ids = {pair: index for index, pair in enumerate(case_pairs)}

    edge_rows = []
    for root, info in sorted(switch_info.items()):
        for site, targets in sorted(info["edges"].items()):
            unique_targets = tuple(dict.fromkeys(targets))
            if unique_targets != tuple(targets):
                raise RuntimeError(
                    "coverage switch edge targets duplicate at %08x/%08x"
                    % (root, site))
            for target in unique_targets:
                if (root, target) not in case_ids:
                    raise RuntimeError(
                        "coverage edge outside case universe at %08x/%08x"
                        % (root, site))
                edge_rows.append((root, site, target))
    case_edges = tuple(sorted(edge_rows))
    if len(case_edges) != COVERAGE_EXPECTED_CASE_EDGES:
        raise RuntimeError(
            "coverage case-edge census changed: %d != %d"
            % (len(case_edges), COVERAGE_EXPECTED_CASE_EDGES))
    edge_hash = _coverage_u32_rows_sha256(case_edges)
    if edge_hash != COVERAGE_CASE_EDGES_SHA256:
        raise RuntimeError("coverage case-edge hash changed: %s" % edge_hash)

    # A case is blocked only when its canonical root is intentionally loud.
    # The exact blocked-root set is presently empty: 0038579c was a metadata
    # false start inside 003836a0, whose six real switches are executable.
    blocked_pairs = tuple(
        pair for pair in case_pairs
        if pair[0] in COVERAGE_BLOCKED_ROOT_RVAS)
    executable_pairs = tuple(
        pair for pair in case_pairs
        if pair[0] not in COVERAGE_BLOCKED_ROOT_RVAS)
    executable_edges = tuple(
        row for row in case_edges
        if row[0] not in COVERAGE_BLOCKED_ROOT_RVAS)
    if (len(blocked_pairs) != COVERAGE_EXPECTED_BLOCKED_CASES or
            len(executable_pairs) != COVERAGE_EXPECTED_EXECUTABLE_CASES or
            len(executable_edges) != COVERAGE_EXPECTED_CASE_HOOKS):
        raise RuntimeError("coverage executable/blocked case census changed")
    executable_hash = _coverage_u32_rows_sha256(executable_pairs)
    hook_hash = _coverage_u32_rows_sha256(executable_edges)
    if executable_hash != COVERAGE_EXECUTABLE_CASES_SHA256:
        raise RuntimeError(
            "coverage executable-case hash changed: %s" % executable_hash)
    if hook_hash != COVERAGE_CASE_HOOKS_SHA256:
        raise RuntimeError(
            "coverage executable-edge hash changed: %s" % hook_hash)

    blocked_cases = tuple({
        "id": case_ids[pair], "root_rva": pair[0], "entry_rva": pair[1],
    } for pair in blocked_pairs)
    blocked_hash = hashlib.sha256(
        _canonical_json_bytes(list(blocked_cases))).hexdigest()
    if blocked_hash != COVERAGE_BLOCKED_CASES_SHA256:
        raise RuntimeError(
            "coverage blocked-case inventory hash changed: %s"
            % blocked_hash)

    edge_occurrences = collections.Counter(
        (root, target) for root, _site, target in case_edges)
    hook_occurrences = collections.Counter(
        (root, target) for root, _site, target in executable_edges)
    return {
        "function_rvas": function_rvas,
        "function_ids": function_ids,
        "imports": import_rows,
        "import_ids": import_ids,
        "case_pairs": case_pairs,
        "case_ids": case_ids,
        "case_edges": case_edges,
        "executable_case_edges": executable_edges,
        "blocked_pairs": blocked_pairs,
        "blocked_cases": blocked_cases,
        "edge_occurrences": edge_occurrences,
        "hook_occurrences": hook_occurrences,
    }


_COVERAGE_CASE_STATEMENT = re.compile(
    r"  case 0x([0-9a-fA-F]{8})U: goto L_([0-9a-fA-F]{8});")


def instrument_coverage_cases(owner_rva, site_rva, statements,
                              targets, case_ids, image_base):
    """Mark the selected switch edge, never mere arrival at its label."""
    expected_targets = tuple(dict.fromkeys(targets))
    if expected_targets != tuple(targets):
        raise RuntimeError(
            "coverage target list changed at %08x/%08x"
            % (owner_rva, site_rva))
    rewritten = []
    found = []
    hook_rows = []
    for statement in statements:
        match = _COVERAGE_CASE_STATEMENT.fullmatch(statement)
        if match is None:
            rewritten.append(statement)
            continue
        case_va = int(match.group(1), 16)
        target = int(match.group(2), 16)
        if case_va != ((image_base + target) & 0xFFFFFFFF):
            raise RuntimeError(
                "coverage emitted case VA changed at %08x/%08x"
                % (owner_rva, site_rva))
        try:
            coverage_id = case_ids[(owner_rva, target)]
        except KeyError as ex:
            raise RuntimeError(
                "coverage emitted case outside ID universe at %08x/%08x"
                % (owner_rva, site_rva)) from ex
        rewritten.append(
            "  case 0x%08xU: { guest_coverage_case(%dU); "
            "goto L_%08x; }" % (case_va, coverage_id, target))
        found.append(target)
        hook_rows.append((owner_rva, site_rva, target, coverage_id))
    if tuple(found) != expected_targets:
        raise RuntimeError(
            "coverage emitted case rows changed at %08x/%08x: %r != %r"
            % (owner_rva, site_rva, tuple(found), expected_targets))
    return tuple(rewritten), tuple(hook_rows)


def validate_coverage_emission(coverage, stub_rvas, entry_hook_ids,
                               cross_root_hooks, case_hooks,
                               manual_hook_count):
    """Prove generated hook occurrences are a bijection onto frozen intent."""
    if manual_hook_count != COVERAGE_EXPECTED_MANUAL_FUNCTION_HOOKS:
        raise RuntimeError(
            "coverage manual function-hook census changed: %d"
            % manual_hook_count)
    function_ids = coverage["function_ids"]
    expected_entry_ids = tuple(sorted(
        coverage_id for rva, coverage_id in function_ids.items()
        if rva not in MANUAL_RVAS))
    actual_entry_ids = tuple(sorted(entry_hook_ids))
    if (actual_entry_ids != expected_entry_ids or
            len(actual_entry_ids) != COVERAGE_EXPECTED_FUNCTION_ENTRY_HOOKS):
        raise RuntimeError("coverage generated function-entry hooks changed")

    sorted_cross = tuple(sorted(cross_root_hooks))
    cross_pairs = tuple((owner, target)
                        for owner, target, _coverage_id in sorted_cross)
    if (len(sorted_cross) != COVERAGE_EXPECTED_CROSS_ROOT_HOOKS or
            len(set(cross_pairs)) != len(cross_pairs) or
            any(owner == target or target in MANUAL_RVAS or
                function_ids.get(target) != coverage_id
                for owner, target, coverage_id in sorted_cross)):
        bad_cross = tuple(
            (owner, target, coverage_id)
            for owner, target, coverage_id in sorted_cross
            if owner == target or target in MANUAL_RVAS or
            function_ids.get(target) != coverage_id)
        diagnostic_records = [
            {"owner_rva": owner, "target_rva": target}
            for owner, target in cross_pairs
        ]
        diagnostic_owners = sorted({owner for owner, _target in cross_pairs})
        diagnostic_targets = sorted({target for _owner, target in cross_pairs})
        raise RuntimeError(
            "coverage cross-root hook universe changed: "
            "hooks=%d unique=%d bad=%r pairs_sha256=%s owners=%d/%s "
            "targets=%d/%s" % (
                len(sorted_cross), len(set(cross_pairs)), bad_cross[:8],
                hashlib.sha256(_canonical_json_bytes(
                    diagnostic_records)).hexdigest(),
                len(diagnostic_owners), hashlib.sha256(
                    _canonical_json_bytes(diagnostic_owners)).hexdigest(),
                len(diagnostic_targets), hashlib.sha256(
                    _canonical_json_bytes(diagnostic_targets)).hexdigest()))
    pair_records = [
        {"owner_rva": owner, "target_rva": target}
        for owner, target in cross_pairs
    ]
    pair_hash = hashlib.sha256(
        _canonical_json_bytes(pair_records)).hexdigest()
    owners = sorted({owner for owner, _target in cross_pairs})
    targets = sorted({target for _owner, target in cross_pairs})
    owner_hash = hashlib.sha256(_canonical_json_bytes(owners)).hexdigest()
    target_hash = hashlib.sha256(_canonical_json_bytes(targets)).hexdigest()
    if (len(owners) != COVERAGE_EXPECTED_CROSS_ROOT_OWNERS or
            len(targets) != COVERAGE_EXPECTED_CROSS_ROOT_TARGETS or
            pair_hash != COVERAGE_CROSS_ROOT_PAIRS_SHA256 or
            owner_hash != COVERAGE_CROSS_ROOT_OWNERS_SHA256 or
            target_hash != COVERAGE_CROSS_ROOT_TARGETS_SHA256):
        raise RuntimeError(
            "coverage cross-root census/hash changed: %d/%d/%s"
            % (len(owners), len(targets), pair_hash))

    sorted_case_hooks = tuple(sorted(case_hooks))
    actual_case_edges = tuple(
        (root, site, target)
        for root, site, target, _coverage_id in sorted_case_hooks)
    expected_case_edges = coverage["executable_case_edges"]
    bad_case_ids = tuple(
        (root, site, target, coverage_id)
        for root, site, target, coverage_id in sorted_case_hooks
        if coverage["case_ids"].get((root, target)) != coverage_id)
    if actual_case_edges != expected_case_edges or bad_case_ids:
        mismatch = next((
            (index, actual, expected)
            for index, (actual, expected) in enumerate(
                zip(actual_case_edges, expected_case_edges))
            if actual != expected), None)
        if mismatch is None and len(actual_case_edges) != len(expected_case_edges):
            mismatch = (min(len(actual_case_edges), len(expected_case_edges)),
                        None, None)
        missing_case_edges = tuple(sorted(
            set(expected_case_edges) - set(actual_case_edges)))
        extra_case_edges = tuple(sorted(
            set(actual_case_edges) - set(expected_case_edges)))
        actual_case_id_set = {
            coverage_id for _root, _site, _target, coverage_id
            in sorted_case_hooks
        }
        raise RuntimeError(
            "coverage emitted case hooks changed: actual=%d/%s expected=%d "
            "first=%r bad_ids=%r ids=%d missing=%d/%s/%r "
            "extra=%d/%s/%r" % (
                len(actual_case_edges),
                _coverage_u32_rows_sha256(actual_case_edges),
                len(expected_case_edges), mismatch, bad_case_ids[:1],
                len(actual_case_id_set),
                len(missing_case_edges),
                _coverage_u32_rows_sha256(missing_case_edges),
                missing_case_edges[:8],
                len(extra_case_edges),
                _coverage_u32_rows_sha256(extra_case_edges),
                extra_case_edges[:8]))
    actual_case_ids = {
        coverage_id for _root, _site, _target, coverage_id
        in sorted_case_hooks
    }
    blocked_case_ids = {
        row["id"] for row in coverage["blocked_cases"]
    }
    if (len(sorted_case_hooks) != COVERAGE_EXPECTED_CASE_HOOKS or
            len(actual_case_ids) != COVERAGE_EXPECTED_EXECUTABLE_CASES or
            actual_case_ids & blocked_case_ids or
            actual_case_ids | blocked_case_ids !=
            set(range(COVERAGE_EXPECTED_CASES))):
        raise RuntimeError("coverage executable case-ID partition changed")

    case_stub_roots = {
        root for root, _entry in coverage["case_pairs"] if root in stub_rvas
    }
    if case_stub_roots != COVERAGE_BLOCKED_ROOT_RVAS:
        raise RuntimeError(
            "coverage switch-bearing stub roots changed: %s"
            % ",".join("%08x" % rva for rva in sorted(case_stub_roots)))

    generated_function_hooks = (
        len(actual_entry_ids) + len(sorted_cross))
    total_function_hooks = generated_function_hooks + manual_hook_count
    if total_function_hooks != COVERAGE_EXPECTED_FUNCTION_HOOKS:
        raise RuntimeError(
            "coverage physical function-hook census changed: %d"
            % total_function_hooks)
    return {
        "cross_root_hooks": sorted_cross,
        "case_hooks": sorted_case_hooks,
        "function_generated_entry_hook_count": len(actual_entry_ids),
        "function_manual_hook_count": manual_hook_count,
        "function_cross_root_hook_count": len(sorted_cross),
        "function_generated_hook_count": generated_function_hooks,
        "function_hook_count": total_function_hooks,
    }


def write_coverage_contract(coverage, emission, stub_rvas,
                            build_id, generation_id):
    """Write deterministic machine-readable and generated-C contracts."""
    function_records = []
    for rva in coverage["function_rvas"]:
        public_symbol, emitted_symbol = function_symbols(rva)
        function_records.append({
            "id": coverage["function_ids"][rva],
            "rva": rva,
            "symbol": public_symbol,
            "emitted_symbol": emitted_symbol,
            "manual": rva in MANUAL_RVAS,
            "stub": rva in stub_rvas,
        })
    import_records = [
        {"id": coverage["import_ids"][slot],
         "slot_rva": slot, "name": name}
        for slot, name in coverage["imports"]
    ]
    case_records = []
    for pair in coverage["case_pairs"]:
        case_records.append({
            "id": coverage["case_ids"][pair],
            "root_rva": pair[0],
            "entry_rva": pair[1],
            "executable": pair not in coverage["blocked_pairs"],
            "edge_occurrences": coverage["edge_occurrences"][pair],
            "hook_occurrences": coverage["hook_occurrences"][pair],
        })
    blocked_cases = list(coverage["blocked_cases"])
    blocked_case_ids = [row["id"] for row in blocked_cases]
    case_edge_records = [
        {
            "root_rva": root,
            "site_rva": site,
            "entry_rva": entry,
            "case_id": coverage["case_ids"][(root, entry)],
            "executable": root not in COVERAGE_BLOCKED_ROOT_RVAS,
        }
        for root, site, entry in coverage["case_edges"]
    ]
    cross_root_records = [
        {"owner_rva": owner, "target_rva": target,
         "function_id": coverage["function_ids"][target]}
        for owner, target, _coverage_id in emission["cross_root_hooks"]
    ]

    semantic = {
        "abi_version": COVERAGE_ABI_VERSION,
        "header_size": COVERAGE_HEADER_SIZE,
        "schema_hash_rule": COVERAGE_SCHEMA_HASH_RULE,
        "function_count": len(function_records),
        "import_count": len(import_records),
        "case_count": len(case_records),
        "case_executable_count": COVERAGE_EXPECTED_EXECUTABLE_CASES,
        "case_blocked_count": len(blocked_cases),
        "case_edge_count": len(case_edge_records),
        "case_hook_count": len(emission["case_hooks"]),
        "function_generated_entry_hook_count":
            emission["function_generated_entry_hook_count"],
        "function_manual_hook_count":
            emission["function_manual_hook_count"],
        "function_cross_root_hook_count":
            emission["function_cross_root_hook_count"],
        "function_hook_count": emission["function_hook_count"],
        "function_rvas_sha256": COVERAGE_FUNCTION_RVAS_SHA256,
        "imports_sha256": COVERAGE_IMPORTS_SHA256,
        "cases_sha256": COVERAGE_CASES_SHA256,
        "case_executable_sha256": COVERAGE_EXECUTABLE_CASES_SHA256,
        "case_edges_sha256": COVERAGE_CASE_EDGES_SHA256,
        "case_hooks_sha256": COVERAGE_CASE_HOOKS_SHA256,
        "blocked_cases_sha256": COVERAGE_BLOCKED_CASES_SHA256,
        "cross_root_pairs_sha256": COVERAGE_CROSS_ROOT_PAIRS_SHA256,
        "cross_root_owners_sha256": COVERAGE_CROSS_ROOT_OWNERS_SHA256,
        "cross_root_targets_sha256": COVERAGE_CROSS_ROOT_TARGETS_SHA256,
        "functions": function_records,
        "imports": import_records,
        "cases": case_records,
        "case_edges": case_edge_records,
        "blocked_case_ids": blocked_case_ids,
        "blocked_cases": blocked_cases,
        "cross_root_hooks": cross_root_records,
    }
    schema_id = hashlib.sha256(
        _canonical_json_bytes(semantic)).hexdigest()
    document = dict(semantic)
    document.update({
        "schema_id": schema_id,
        "build_id": build_id,
        "generation_id": generation_id,
    })
    json_path = os.path.join(OUTDIR, COVERAGE_JSON_NAME)
    with open(json_path, "wb") as target:
        target.write(_canonical_json_bytes(document))
        target.write(b"\n")

    header_path = os.path.join(OUTDIR, COVERAGE_HEADER_NAME)
    with open(header_path, "w", encoding="utf-8", newline="\n") as target:
        target.write(
            "/* GENERATED by recomp/gen_all.py -- do not edit.\n"
            " * schema_id is SHA-256 of compact, sort_keys canonical JSON\n"
            " * after removing schema_id, build_id and generation_id. */\n"
            "#ifndef GUEST_COVERAGE_GENERATED_H\n"
            "#define GUEST_COVERAGE_GENERATED_H\n\n")
        string_macros = (
            ("GUEST_COVERAGE_SCHEMA_HASH_RULE", COVERAGE_SCHEMA_HASH_RULE),
            ("GUEST_COVERAGE_SCHEMA_ID", schema_id),
            ("GUEST_COVERAGE_BUILD_ID", build_id),
            ("GUEST_COVERAGE_GENERATION_ID", generation_id),
            ("GUEST_COVERAGE_FUNCTION_RVAS_SHA256",
             COVERAGE_FUNCTION_RVAS_SHA256),
            ("GUEST_COVERAGE_IMPORTS_SHA256", COVERAGE_IMPORTS_SHA256),
            ("GUEST_COVERAGE_CASES_SHA256", COVERAGE_CASES_SHA256),
            ("GUEST_COVERAGE_CASE_EXECUTABLE_SHA256",
             COVERAGE_EXECUTABLE_CASES_SHA256),
            ("GUEST_COVERAGE_CASE_EDGES_SHA256",
             COVERAGE_CASE_EDGES_SHA256),
            ("GUEST_COVERAGE_CASE_HOOKS_SHA256",
             COVERAGE_CASE_HOOKS_SHA256),
            ("GUEST_COVERAGE_BLOCKED_CASES_SHA256",
             COVERAGE_BLOCKED_CASES_SHA256),
            ("GUEST_COVERAGE_CROSS_ROOT_PAIRS_SHA256",
             COVERAGE_CROSS_ROOT_PAIRS_SHA256),
        )
        for macro, value in string_macros:
            target.write('#define %s "%s"\n' % (macro, value))
        target.write("\n")
        integer_macros = (
            ("GUEST_COVERAGE_ABI_VERSION", COVERAGE_ABI_VERSION),
            ("GUEST_COVERAGE_HEADER_SIZE", COVERAGE_HEADER_SIZE),
            ("GUEST_COVERAGE_FUNCTION_COUNT", len(function_records)),
            ("GUEST_COVERAGE_IMPORT_COUNT", len(import_records)),
            ("GUEST_COVERAGE_CASE_COUNT", len(case_records)),
            ("GUEST_COVERAGE_CASE_EXECUTABLE_COUNT",
             COVERAGE_EXPECTED_EXECUTABLE_CASES),
            ("GUEST_COVERAGE_CASE_BLOCKED_COUNT", len(blocked_cases)),
            ("GUEST_COVERAGE_CASE_EDGE_COUNT", len(case_edge_records)),
            ("GUEST_COVERAGE_CASE_HOOK_COUNT", len(emission["case_hooks"])),
            ("GUEST_COVERAGE_FUNCTION_GENERATED_ENTRY_HOOK_COUNT",
             emission["function_generated_entry_hook_count"]),
            ("GUEST_COVERAGE_FUNCTION_MANUAL_HOOK_COUNT",
             emission["function_manual_hook_count"]),
            ("GUEST_COVERAGE_FUNCTION_CROSS_ROOT_HOOK_COUNT",
             emission["function_cross_root_hook_count"]),
            ("GUEST_COVERAGE_FUNCTION_HOOK_COUNT",
             emission["function_hook_count"]),
        )
        for macro, value in integer_macros:
            target.write("#define %s %dU\n" % (macro, value))
        target.write("\n")
        for macro, _rva, coverage_id in COVERAGE_MANUAL_SPECS:
            target.write("#define %s %dU\n" % (macro, coverage_id))
        target.write("\n#endif\n")
    return schema_id


def _false_start_pin_recipe():
    """Canonical, JSON-safe identity of every false-start proof."""
    rows = []
    for start, pin in sorted(FALSE_START_PINS.items()):
        row = {"start": start}
        for key, value in sorted(pin.items()):
            row[key] = value.hex() if isinstance(value, bytes) else value
        rows.append(row)
    return rows


def _noreturn_switch_proof_recipe():
    """Canonical, JSON-safe identity of the recovered switch proofs."""
    rows = []
    for proof in NORETURN_SWITCH_PROOFS:
        row = {}
        for key, value in sorted(proof.items()):
            row[key] = value.hex() if isinstance(value, bytes) else value
        rows.append(row)
    metrics = []
    for owner, spec in sorted(NORETURN_SWITCH_OWNER_METRICS.items()):
        row = {"owner": owner}
        for key, value in sorted(spec.items()):
            row[key] = list(value) if isinstance(value, tuple) else value
        metrics.append(row)
    return {"proofs": rows, "owner_metrics": metrics}


