def _global_switch_fixed_point_recipe():
    """Canonical identity of the bounded cross-owner convergence waves."""
    rows = []
    for spec in GLOBAL_SWITCH_FIXED_POINT_SPECS:
        row = {}
        for key, value in sorted(spec.items()):
            if isinstance(value, bytes):
                row[key] = value.hex()
            elif isinstance(value, tuple):
                row[key] = list(value)
            else:
                row[key] = value
        rows.append(row)
    sibling_rows = []
    for spec in SPLIT_REMAP_OWNER_LOCAL_SIBLING_SPECS:
        row = {}
        for key, value in sorted(spec.items()):
            if isinstance(value, bytes):
                row[key] = value.hex()
            elif isinstance(value, tuple):
                row[key] = list(value)
            else:
                row[key] = value
        sibling_rows.append(row)
    return {
        "max_waves": GLOBAL_SWITCH_FIXED_POINT_MAX_WAVES,
        "waves": [list(wave) for wave in GLOBAL_SWITCH_FIXED_POINT_WAVES],
        "memberships": [list(row)
                        for row in GLOBAL_SWITCH_FIXED_POINT_MEMBERSHIPS],
        "membership_sha256":
            GLOBAL_SWITCH_FIXED_POINT_MEMBERSHIPS_SHA256,
        "sites_sha256": GLOBAL_SWITCH_FIXED_POINT_SITES_SHA256,
        "roots_sha256": GLOBAL_SWITCH_FIXED_POINT_ROOTS_SHA256,
        "root_metrics": [list(row)
                         for row in GLOBAL_SWITCH_FIXED_POINT_ROOT_METRICS],
        "switches": rows,
        "owner_local_siblings": sibling_rows,
        "owner_local_root_metrics": [list(row)
                                     for row in
                                     SPLIT_REMAP_OWNER_LOCAL_ROOT_METRICS],
    }


def _entity_player_update_helper_remap_pin_recipe():
    """Canonical identity of the split player's complete eight-table CFG."""
    owner = {}
    for key, value in sorted(
            ENTITY_PLAYER_UPDATE_HELPER_REMAP_OWNER.items()):
        if isinstance(value, bytes):
            owner[key] = value.hex()
        elif isinstance(value, tuple):
            owner[key] = list(value)
        else:
            owner[key] = value
    remaps = []
    for site, pin in sorted(ENTITY_PLAYER_UPDATE_HELPER_REMAP_PINS.items()):
        row = {"site": site}
        for key, value in sorted(pin.items()):
            if key == "site":
                continue
            if isinstance(value, bytes):
                row[key] = value.hex()
            elif isinstance(value, tuple):
                row[key] = list(value)
            else:
                row[key] = value
        remaps.append(row)
    generic = []
    for pin in ENTITY_PLAYER_UPDATE_HELPER_GENERIC_TABLES:
        row = {}
        for key, value in sorted(pin.items()):
            if isinstance(value, bytes):
                row[key] = value.hex()
            elif isinstance(value, tuple):
                row[key] = list(value)
            else:
                row[key] = value
        generic.append(row)
    return {"owner": owner, "remaps": remaps, "generic": generic}


def _entity_effect_update_switch_pin_recipe():
    """Canonical identity of the complete nine-table giant owner package."""
    owner = {}
    for key, value in sorted(ENTITY_EFFECT_UPDATE_SWITCH_OWNER.items()):
        owner[key] = value.hex() if isinstance(value, bytes) else value
    rows = []
    for site, pin in sorted(ENTITY_EFFECT_UPDATE_SWITCH_PINS.items()):
        row = {"site": site}
