    if pc_clock_roots != {PC_CLOCK_ROOT_RVA}:
        raise RuntimeError(
            "PC clock seam memberships changed: %s"
            % ",".join("%08x" % r for r in sorted(pc_clock_roots)))
    for site, owners, _branch, _zero, _nonzero in PC_GLFW_GUARD_CENSUS:
        actual = frozenset(pc_glfw_guard_site_roots[site])
